---------------------------------------------------------------
-- Table: [Item]
---------------------------------------------------------------
IF OBJECT_ID('[Item]', 'U') IS NULL
BEGIN
CREATE TABLE [Item] (
    [Id] int IDENTITY(1,1)  NOT NULL,
    [SubCategoryId] int   NULL,
    [ItemDesc] varchar(500)   NULL,
    [ShortDesc] varchar(5000)   NULL,
    [SortOrder] int   NULL,
    [Barcode] varchar(50)   NULL,
    [ImageURL] nvarchar(-0.5)   NULL,
    [CreatedBy] int   NULL,
    [CreateDate] datetime   NULL,
    [IsActive] bit   NULL,
    [IsDeleted] bit   NULL,
    [IsAddonMultiselect] bit   NULL,
    [IsOptionsMultiselect] bit   NULL,
    [IsAddonOptional] bit   NULL,
    [IsOptionsOptional] bit   NULL,
    [IsOptions2Multiselect] bit   NULL,
    [IsOptions2Optional] bit   NULL,
    [ItemType] varchar(50)  DEFAULT ('NonInventory') NULL,
    [MaxItemQty] int  DEFAULT ((0)) NULL,
    [IsRecipe] bit  DEFAULT ((0)) NULL,
    [Recipecode] varchar(100)   NULL,
    [UpdatedAt] datetime  DEFAULT (getdate()) NULL,
    CONSTRAINT [PK_Item] PRIMARY KEY ([Id])
);
END
GO

SET IDENTITY_INSERT [Item] ON;
