IF OBJECT_ID('[SubCategory]', 'U') IS NULL
BEGIN
CREATE TABLE [SubCategory] (
    [Id] int IDENTITY(1,1)  NOT NULL,
    [CategoryId] int   NULL,
    [SubCategiryDesc] varchar(500)   NULL,
    [ShortDesc] varchar(50)   NULL,
    [SortOrder] int   NULL,
    [CreatedBy] int   NULL,
    [CreateDate] datetime   NULL,
    [IsActive] bit   NULL,
    [IsDeleted] bit   NULL,
    [UpdatedAt] datetime  DEFAULT (getdate()) NULL
);
END
