-- Stored Procedure: [dbo_FlightDetails_488eb90e-50d1-4caa-bea2-9e6bd20a0533_QueueActivationSender]
IF OBJECT_ID('[dbo_FlightDetails_488eb90e-50d1-4caa-bea2-9e6bd20a0533_QueueActivationSender]', 'P') IS NOT NULL DROP PROCEDURE [dbo_FlightDetails_488eb90e-50d1-4caa-bea2-9e6bd20a0533_QueueActivationSender];
GO
CREATE PROCEDURE [dbo].[dbo_FlightDetails_488eb90e-50d1-4caa-bea2-9e6bd20a0533_QueueActivationSender] 
WITH EXECUTE AS SELF
AS 
BEGIN 
    SET NOCOUNT ON;
    DECLARE @h AS UNIQUEIDENTIFIER;
    DECLARE @mt NVARCHAR(200);

    RECEIVE TOP(1) @h = conversation_handle, @mt = message_type_name FROM [dbo].[dbo_FlightDetails_488eb90e-50d1-4caa-bea2-9e6bd20a0533_Sender];

    IF @mt = N'http://schemas.microsoft.com/SQL/ServiceBroker/EndDialog'
    BEGIN
        END CONVERSATION @h;
    END

    IF @mt = N'http://schemas.microsoft.com/SQL/ServiceBroker/DialogTimer' OR @mt = N'http://schemas.microsoft.com/SQL/ServiceBroker/Error'
    BEGIN 
        

        END CONVERSATION @h;

        DECLARE @conversation_handle UNIQUEIDENTIFIER;
        DECLARE @schema_id INT;
