        IF EXISTS (SELECT * FROM sys.service_queues WITH (NOLOCK) WHERE schema_id = @schema_id AND name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_Receiver') DROP QUEUE [dbo].[dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_Receiver];
        
        IF EXISTS (SELECT * FROM sys.service_queues WITH (NOLOCK) WHERE schema_id = @schema_id AND name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_Sender') DROP QUEUE [dbo].[dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_Sender];

        
        IF EXISTS (SELECT * FROM sys.service_contracts WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33') DROP CONTRACT [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33];
        
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Insert') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Insert];
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Update') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Update];
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Delete') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/StartMessage/Delete];
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/Id') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/Id];
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/ISChange') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/ISChange];
        IF EXISTS (SELECT * FROM sys.service_message_types WITH (NOLOCK) WHERE name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/EndMessage') DROP MESSAGE TYPE [dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33/EndMessage];

        
        IF EXISTS (SELECT * FROM sys.objects WITH (NOLOCK) WHERE schema_id = @schema_id AND name = N'dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_QueueActivationSender') DROP PROCEDURE [dbo].[dbo_OrderMaster_ea5d8f3b-505a-44f9-b489-ab67810a4b33_QueueActivationSender];

        
    END
END

