-- Stored Procedure: [SP_AddAddons]
IF OBJECT_ID('[SP_AddAddons]', 'P') IS NOT NULL DROP PROCEDURE [SP_AddAddons];
GO

CREATE Procedure [dbo].[SP_AddAddons]
@AddonsJson		varchar(max),
@Msg			varchar(200) Out
As
BEGIN TRY            
    BEGIN TRANSACTION  


	Declare @AddonJsonTable  Table(
			AddonId	int,
			ItemId	int,
			IsAddonMultiselect bit,
			CreateDate Date)

			Insert Into @AddonJsonTable
		Select *,GETDATE()'CreateDate' from OpenJson(@AddonsJson)
			With (AddonId	int,
			ItemId	int,
			IsAddonMultiselect	bit)

			Delete A From ItemAddOns A
			Inner Join @AddonJsonTable I On A.ItemId = I.ItemId

			Insert Into ItemAddOns(AddonId,ItemId,CreateDate)
			Select AddonId,ItemId,CreateDate from @AddonJsonTable

			Update I set I.IsAddonMultiselect  = J.IsAddonMultiselect 
			From Item I 
			Inner Join @AddonJsonTable J On J.ItemId  = I.Id

			Set @Msg ='Addons Add Successfully'
COMMIT TRANSACTION            
END TRY            
BEGIN CATCH            
          
 ROLLBACK TRANSACTION          
 Set @Msg = ERROR_MESSAGE()      
End CATCH 

GO

