@CustomerLan		float,
@AddressId			int OutPut
as
Begin
Insert Into CustomerDetail(CountryId,CityId,CustomerId,DoorNo,CustomerAddress,CustomerAddress1,CustomerLat,CustomerLan,CreateDate,IsActive,IsDeleted)
					Values(@CountryId,@CityId,@CustomerId,@DoorNo,@CustomerAddress,@CustomerAddress1,@CustomerLat,@CustomerLan,GETDATE(),1,0)

					Set @AddressId = SCOPE_IDENTITY()

					Select @AddressId

End

