CREATE Procedure [dbo].[SP_AddOptions1]
@Option1Json		varchar(max),
@Msg			varchar(200) Out
As
BEGIN TRY            
    BEGIN TRANSACTION  


	Declare @Options1JsonTable  Table(
			ItemId	int,
			Option1Id	int,
			IsOptionsMultiselect bit,
			CreateDate Date)

			Insert Into @Options1JsonTable
		Select *,GETDATE()'CreateDate' from OpenJson(@Option1Json)
			With (
			ItemId	int,
			Option1Id	int,
			IsOptionsMultiselect	bit)

			Delete A From itemOptions1 A
			Inner Join @Options1JsonTable I On A.ItemId = I.ItemId

			Insert Into itemOptions1(ItemId,Option1Id,CreateDate)
			Select ItemId,Option1Id,CreateDate from @Options1JsonTable

			Update I set I.IsOptionsMultiselect  = J.IsOptionsMultiselect 
			From Item I 
			Inner Join @Options1JsonTable J On J.ItemId  = I.Id

			Set @Msg ='Options1 Add Successfully'
COMMIT TRANSACTION            
END TRY            
BEGIN CATCH            
          
 ROLLBACK TRANSACTION          
 Set @Msg = ERROR_MESSAGE()      
End CATCH 

GO

