    BEGIN TRANSACTION      
    
    
 Declare @Options2JsonTable  Table(    
   ItemId int,    
   Option1Id int,    
   IsOptionsMultiselect bit,    
   CreateDate Date)    
    
   Insert Into @Options2JsonTable    
  Select *,GETDATE()'CreateDate' from OpenJson(@Option2Json)    
   With (    
   ItemId int,    
   Option1Id int,    
   IsOptionsMultiselect bit)    
    
   Delete A From itemOptions1 A    
   Inner Join @Options2JsonTable I On A.ItemId = I.ItemId    
    
