CREATE Procedure [dbo].[SP_AllDriverList]
@ResturantId		int
As
Begin
Select DD.Id,DD.DriverName,DD.NIC,DD.CellNo,DD.DriverNo,DL.UserName,DL.UserPassword from DriverDetail DD
Inner Join driverlogin DL On DD.Id = DL.DriverId
Where DD.IsActive = 1 And DD.IsDeleted = 0 And DD.ResturantId = @ResturantId
End

GO

-- Stored Procedure: [SP_AllItemList]
IF OBJECT_ID('[SP_AllItemList]', 'P') IS NOT NULL DROP PROCEDURE [SP_AllItemList];
GO

CREATE Procedure [dbo].[SP_AllItemList]    
As  
Begin  
Select   
C.CategoryDesc,SC.SubCategiryDesc,SC.CategoryId  
,I.Id,I.SubCategoryId,I.ItemDesc,I.ShortDesc,I.SortOrder,I.ImageURL,I.IsActive   
,IR.Id RateId,IR.Rate,IV.Id ItemVeriationId,IV.ItemSize  
from Item I  
Inner Join ItemRate IR On I.Id = IR.ItemId  
Inner Join SubCategory SC On SC.Id = I.SubCategoryId  
Inner Join Category C On SC.CategoryId = C.Id  
Inner Join ItemVeriation IV On IR.ItemVeriationId = IV.Id  
Where I.Id = I.Id And C.IsActive=1 And C.IsDeleted = 0 And SC.IsActive = 1 And SC.IsDeleted = 0	And I.IsDeleted=0 
--And I.IsActive = 1 
Order By C.CategoryDesc  
End

GO

