CREATE Procedure [dbo].[SP_AllSubCategoryList]    
As    
Begin    
Select C.CategoryDesc,SC.Id,SC.CategoryId,SC.SubCategiryDesc,Sc.ShortDesc,SC.SortOrder,SC.IsActive from SubCategory Sc    
Inner Join Category C ON SC.CategoryId = C.Id    
Where SC.Id = SC.Id And SC.IsActive = 1 And SC.IsDeleted = 0    
Order By Sc.SortOrder    
End  

