-- Stored Procedure: [SP_AssigendTableToWaiter]
IF OBJECT_ID('[SP_AssigendTableToWaiter]', 'P') IS NOT NULL DROP PROCEDURE [SP_AssigendTableToWaiter];
GO
CREATE Procedure [dbo].[SP_AssigendTableToWaiter]  
@json varchar(Max),  
@Msg varchar(100) Out  
AS  
Begin  
  
  
 Declare @AssignTableJsonTable  Table(  
   WaiterId int,  
   TableId int,  
   TableNo varchar(100)  
   )  
  
   Insert Into @AssignTableJsonTable  
  Select * from OpenJson(@json)  
   With (WaiterId int,  
   TableId int,  
   TableNo varchar(100))  
  
   Delete A From AssignTable A  
   Inner Join @AssignTableJsonTable J On A.WaiterId = J.WaiterId  
  
   Insert Into AssignTable(
    WaiterId,
    TableId,
    TableNo
)  
   Select WaiterId,
    TableId,
    TableNo from @AssignTableJsonTable  
  
End  
GO

