-- Stored Procedure: [SP_CreateOrder_Dinein_Copy]
IF OBJECT_ID('[SP_CreateOrder_Dinein_Copy]', 'P') IS NOT NULL DROP PROCEDURE [SP_CreateOrder_Dinein_Copy];
GO

  
                                                                                                                                                                                                                                                           
CREATE Procedure [dbo].[SP_CreateOrder_Dinein_Copy]  
                                                                                                                                                                                                        
    @OrderMasterId int,  
                                                                                                                                                                                                                                    
    @OrderTypeId int,
                                                                                                                                                                                                                                        
	@DepartmentId int,
                                                                                                                                                                                                                                          
    @CustomerId int,  
                                                                                                                                                                                                                                       
    @RestaurantId int,  
                                                                                                                                                                                                                                     
    @Fname varchar(50),  
                                                                                                                                                                                                                                    
    @Email varchar(50),  
                                                                                                                                                                                                                                    
    @CustAddress varchar(500),  
                                                                                                                                                                                                                             
    @TelephoneNo varchar(50),  
                                                                                                                                                                                                                              
    @CountryId int,  
                                                                                                                                                                                                                                        
    @CityId int,  
                                                                                                                                                                                                                                           
    @DoorNo varchar(50),  
                                                                                                                                                                                                                                   
    @CustomerAddress varchar(500),  
                                                                                                                                                                                                                         
    @CustomerAddress1 varchar(500),  
                                                                                                                                                                                                                        
    @CustomerLat float,  
                                                                                                                                                                                                                                    
    @CustomerLan float,  
                                                                                                                                                                                                                                    
    @PaymentId int,  
                                                                                                                                                                                                                                        
    @PicupLocation varchar(Max),  
                                                                                                                                                                                                                           
    @PickupLat float,  
                                                                                                                                                                                                                                      
    @PickupLan float,  
                                                                                                                                                                                                                                      
    @OrderAmount Decimal(18, 2),  
                                                                                                                                                                                                                           
    @OrderDiscount Decimal(18, 2),  
                                                                                                                                                                                                                         
    @OrderDiscountPer Decimal(18, 2),  
                                                                                                                                                                                                                      
    @OrderNetAmount Decimal(18, 2),  
                                                                                                                                                                                                                        
    @Json NVARCHAR(MAX),  
                                                                                                                                                                                                                                   
    @JsonOrderDetailOption1 NVARCHAR(MAX),  
                                                                                                                                                                                                                 
    @JsonOrderDetailOption2 NVARCHAR(MAX),  
                                                                                                                                                                                                                 
    @JsonOrderDetailAddOns NVARCHAR(MAX),  
                                                                                                                                                                                                                  
    @CreatedBy int,  
                                                                                                                                                                                                                                        
    @IsHold bit,  
                                                                                                                                                                                                                                           
    @IsFinalPaid bit,  
                                                                                                                                                                                                                                      
    @TableId int,  
                                                                                                                                                                                                                                          
    @TableNo varchar(100),  
                                                                                                                                                                                                                                 
    @DeviceId varchar(Max),  
                                                                                                                                                                                                                                
    @DiscountId int,  
                                                                                                                                                                                                                                       
    @TaxesId int,  
                                                                                                                                                                                                                                          
    @TaxPer Decimal(18, 2),  
                                                                                                                                                                                                                                
    @TaxAmount Decimal(18, 2),  
                                                                                                                                                                                                                             
    @OrderFrom varchar(100),  
                                                                                                                                                                                                                               
    @CustomerName varchar(100) = NULL,  
                                                                                                                                                                                                                     
    @ReferralCode varchar(100) = NULL,
                                                                                                                                                                                                                       
	@WaiterId int = NULL,
                                                                                                                                                                                                                                       
	@OrderUniqueId bigint,
                                                                                                                                                                                                                                      
	@FlightID int = NULL,
                                                                                                                                                                                                                                       
    @Msg varchar(50) Out,  
                                                                                                                                                                                                                                  
    @OrderNo varchar(100) Out,
                                                                                                                                                                                                                               
	@ReferenceName varchar(100) Out
                                                                                                                                                                                                                             
As  
                                                                                                                                                                                                                                                         
Begin  
                                                                                                                                                                                                                                                      
    --Declare @NewCustomerId int                        
                                                                                                                                                                                                     
  
                                                                                                                                                                                                                                                           
    --Exec SP_InserCustomer                         
                                                                                                                                                                                                         
    --     @CustomerId=@CustomerId,                        
                                                                                                                                                                                                  
    --     @RestaurantId=@RestaurantId,                        
                                                                                                                                                                                              
    --     @Fname=@Fname,                        
                                                                                                                                                                                                            
    --     @Email=@Email,                        
                                                                                                                                                                                                            
    --     @CustAddress=@CustAddress,                        
                                                                                                                                                                                                
    --     @TelephoneNo=@TelephoneNo,                        
                                                                                                                                                                                                
    --     @CountryId=@CountryId,                        
                                                                                                                                                                                                    
    --     @CityId=@CityId,                        
                                                                                                                                                                                                          
    --     @DoorNo=@DoorNo,                        
                                                                                                                                                                                                          
    --     @CustomerAddress=@CustomerAddress,                        
                                                                                                                                                                                        
    --     @CustomerAddress1=@CustomerAddress1,                        
                                                                                                                                                                                      
    --     @CustomerLat=@CustomerLat,                        
                                                                                                                                                                                                
    --     @CustomerLan=@CustomerLan,                       
                                                                                                                                                                                                 
    --  @CustomerPassword = NULL,                      
                                                                                                                                                                                                      
    --@DeviceID   = NULL,                      
                                                                                                                                                                                                              
    --     @CreatedBy=@CreatedBy,                        
                                                                                                                                                                                                    
    --     @NewCustomerId = @NewCustomerId OUTPUT  
                                                                                                                                                                                                          
	
                                                                                                                                                                                                                                                            
	Declare @OrderCheck int 
                                                                                                                                                                                                                                    
	set @OrderCheck =  
                                                                                                                                                                                                                                         
    (  
                                                                                                                                                                                                                                                      
        Select Id From OrderMaster Where OrderUniqueId = @OrderUniqueId
                                                                                                                                                                                      
    )  
                                                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
    if (@OrderMasterId = 0 AND (@OrderCheck = 0 OR @OrderCheck = '' OR @OrderCheck IS NULL))  
                                                                                                                                                               
    Begin  
                                                                                                                                                                                                                                                  
        Declare @ResturantShortName Varchar(100)  
                                                                                                                                                                                                           
        Declare @JobRefNo varchar(100)  
                                                                                                                                                                                                                     
        Declare @IsChange bit  
                                                                                                                                                                                                                              
  
                                                                                                                                                                                                                                                           
        set @TaxPer =  
                                                                                                                                                                                                                                      
        (  
                                                                                                                                                                                                                                                  
            Select TaxPercentage From Taxes Where TaxName = 'GST' and IsActive = 1  
                                                                                                                                                                         
        )  
                                                                                                                                                                                                                                                  
        IF (@TaxPer != 0)  
                                                                                                                                                                                                                                  
        Begin  
                                                                                                                                                                                                                                              
            SET @TaxAmount = @OrderAmount * (@TaxPer / 100);  
                                                                                                                                                                                               
        End  
                                                                                                                                                                                                                                                
        SET @OrderNetAmount = @OrderAmount + @TaxAmount;  
                                                                                                                                                                                                   
  
                                                                                                                                                                                                                                                           
        Insert Into OrderMaster  
                                                                                                                                                                                                                            
        (  
                                                                                                                                                                                                                                                  
            CustomerId,  
                                                                                                                                                                                                                                    
            OrderTypeId,
                                                                                                                                                                                                                                     
			DepartmentId,
                                                                                                                                                                                                                                             
            CountryId,  
                                                                                                                                                                                                                                     
            CityId,  
                                                                                                                                                                                                                                        
            ResturantId,  
                                                                                                                                                                                                                                   
            PaymentId,  
                                                                                                                                                                                                                                     
            PicupLocation,  
                                                                                                                                                                                                                                 
            PickupLat,  
                                                                                                                                                                                                                                     
            PickupLan,  
                                                                                                                                                                                                                                     
            DestinationLocation,  
                                                                                                                                                                                                                           
            DestinationLat,  
                                                                                                                                                                                                                                
            DestinationLan,  
                                                                                                                                                                                                                                
            OrderAmount,  
                                                                                                                                                                                                                                   
            OrderDiscount,  
                                                                                                                                                                                                                                 
            OrderDiscountPer,  
                                                                                                                                                                                                                              
            OrderNetAmount,  
                                                                                                                                                                                                                                
            CreatedBy,  
                                                                                                                                                                                                                                     
            CreateDate,  
                                                                                                                                                                                                                                    
            OrderDate,  
                                                                                                                                                                                                                                     
            IsActive,  
                                                                                                                                                                                                                                      
            IsDeleted,  
                                                                                                                                                                                                                                     
            IsHold,  
                                                                                                                                                                                                                                        
          IsFinalPaid,  
                                                                                                                                                                                                                                     
            TableId,  
                                                                                                                                                                                                                                       
            TableNo,  
                                                                                                                                                                                                                                       
            DeviceId,  
                                                                                                                                                                                                                                      
            ISChange,  
                                                                                                                                                                                                                                      
            DiscountId,  
                                                                                                                                                                                                                                    
            TaxesId,  
                                                                                                                                                                                                                                       
            TaxPer,  
                                                                                                                                                                                                                                        
            TaxAmount,  
                                                                                                                                                                                                                                     
            OrderFrom,  
                                                                                                                                                                                                                                     
            CustomerName,  
                                                                                                                                                                                                                                  
            ReferralCode,
                                                                                                                                                                                                                                    
			WaiterId,
                                                                                                                                                                                                                                                 
			OrderUniqueId,
                                                                                                                                                                                                                                            
			ReferenceName
                                                                                                                                                                                                                                             
        )  
                                                                                                                                                                                                                                                  
        Values  
                                                                                                                                                                                                                                             
        (@CustomerId,  
                                                                                                                                                                                                                                      
         @OrderTypeId,
                                                                                                                                                                                                                                       
		 @DepartmentId,
                                                                                                                                                                                                                                            
         @CountryId,  
                                                                                                                                                                                                                                       
         @CityId,  
                                                                                                                                                                                                                                          
         @RestaurantId,  
                                                                                                                                                                                                                                    
         @PaymentId,  
                                                                                                                                                                                                                                       
         @PicupLocation,  
                                                                                                                                                                                                                                   
         @PickupLat,  
                                                                                                                                                                                                                                       
         @PickupLan,  
                                                                                                                                                                                                                                       
         @CustomerAddress,  
                                                                                                                                                                                                                                 
         @CustomerLat,  
                                                                                                                                                                                                                                     
         @CustomerLan,  
                                                                                                                                                                                                                                     
         @OrderAmount,  
                                                                                                                                                                                                                                     
         @OrderDiscount,  
                                                                                                                                                                                                                                   
         @OrderDiscountPer,  
                                                                                                                                                                                                                                
         @OrderNetAmount,  
                                                                                                                                                                                                                                  
         @CreatedBy,  
                                                                                                                                                                                                                                       
         FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'),  
                                                                                                                                                                       
         FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'),  
                                                                                                                                                                       
         0  ,  
                                                                                                                                                                                                                                              
         0  ,  
                                                                                                                                                                                                                                              
         @IsHold,  
                                                                                                                                                                                                                                          
         @IsFinalPaid,  
                                                                                                                                                                                                                                     
         @TableId,  
                                                                                                                                                                                                                                         
         @TableNo,  
                                                                                                                                                                                                                                         
         @DeviceId,  
                                                                                                                                                                                                                                        
         1  ,  
                                                                                                                                                                                                                                              
         @DiscountId,  
                                                                                                                                                                                                                                      
         @TaxesId,  
                                                                                                                                                                                                                                         
         @TaxPer,  
                                                                                                                                                                                                                                          
         @TaxAmount,  
                                                                                                                                                                                                                                       
         @OrderFrom,  
                                                                                                                                                                                                                                       
         @CustomerName,  
                                                                                                                                                                                                                                    
         @ReferralCode,
                                                                                                                                                                                                                                      
		 @WaiterId,
                                                                                                                                                                                                                                                
		 @OrderUniqueId,
                                                                                                                                                                                                                                           
		 @ReferenceName
                                                                                                                                                                                                                                            
        )  
                                                                                                                                                                                                                                                  
        Select @ResturantShortName = RestaurantShortName  
                                                                                                                                                                                                   
        From Restaurant  
                                                                                                                                                                                                                                    
  
                                                                                                                                                                                                                                                           
        set @OrderMasterId = SCOPE_IDENTITY();  
                                                                                                                                                                                                             
        Select @JobRefNo = @ResturantShortName + '-' + RIGHT('000000' + CAST(@OrderMasterId AS VARCHAR(7)), 7)  
                                                                                                                                             
        Update OrderMaster  
                                                                                                                                                                                                                                 
        Set JobRefNo = @JobRefNo  
                                                                                                                                                                                                                           
        Where Id = @OrderMasterId  
                                                                                                                                                                                                                          
  
                                                                                                                                                                                                                                                           
        Update OrderMaster  
                                                                                                                                                                                                                                 
        Set DeletedOrderAmount = @OrderAmount,  
                                                                                                                                                                                                             
            DeletedOrderNetAmount = @OrderNetAmount,  
                                                                                                                                                                                                       
            Deletedtaxamount = @TaxAmount  
                                                                                                                                                                                                                  
        Where Id = @OrderMasterId  
                                                                                                                                                                                                                          
              and DeletedOrderAmount IS NOT NULL  
                                                                                                                                                                                                           
              and DeletedOrderNetAmount IS NOT NULL  
                                                                                                                                                                                                        
              AND Deletedtaxamount IS NOT NULL  
                                                                                                                                                                                                             
    end  
                                                                                                                                                                                                                                                    
    else  
                                                                                                                                                                                                                                                   
    Begin  
                                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
		IF (@OrderMasterId = 0)
        BEGIN
            set @OrderMasterId = @OrderCheck  
        END
                                                                                                                                                                                                                         
        Set @TaxPer =  
                                                                                                                                                                                                                                      
        (  
                                                                                                                                                                                                                                                  
            Select TaxPercentage From Taxes Where TaxName = 'GST' and IsActive = 1  
                                                                                                                                                                         
        )  
                                                                                                                                                                                                                                                  
        IF (@TaxPer != 0)  
                                                                                                                                                                                                                                  
        Begin  
                                                                                                                                                                                                                                              
            SET @TaxAmount = @OrderAmount * (@TaxPer / 100);  
                                                                                                                                                                                               
        End  
                                                                                                                                                                                                                                                
        SET @OrderNetAmount = @OrderAmount + @TaxAmount;  
                                                                                                                                                                                                   
  
                                                                                                                                                                                                                                                           
        Select @IsChange = ISChange  
                                                                                                                                                                                                                        
        from OrderMaster  
                                                                                                                                                                                                                                   
        Where Id = @OrderMasterId  
                                                                                                                                                                                                                          
        if (@IsChange = 1)  
                                                                                                                                                                                                                                 
        begin  
                                                                                                                                                                                                                                              
            Set @IsChange = 0  
                                                                                                                                                                                                                              
        End  
                                                                                                                                                                                                                                                
        else  
                                                                                                                                                                                                                                               
        begin  
                                                                                                                                                                                                                                              
            Set @IsChange = 1  
                                                                                                                                                                                                                              
        End  
                                                                                                                                                                                                                                                
        if (@OrderFrom = 'CustomerApp')  
                                                                                                                                                                                                                    
        begin  
                                                                                                                                                                                                                                              
            Update OrderMaster  
                                                                                                                                                                                                                             
            Set IsHold = @IsHold,  
                                                                                                                                                                                                                          
                IsFinalPaid = @IsFinalPaid,  
                                                                                                                                                                                                                
                DeviceId = @DeviceId,  
                                                                                                                                                                                                                      
                ISChange = @IsChange,  
                                                                                                                                                                                                                      
                OrderAmount = @OrderAmount,  
                                                                                                                                                                                                                
                OrderNetAmount = @OrderNetAmount,  
                                                                                                                                                                                                          
                OrderDiscount = @OrderDiscount,  
                                                                                                                                                                                                            
                DiscountId = @DiscountId,  
                                                                                                                                                                                                                  
                TaxesId = @TaxesId,  
                                                                                                                                                                                                                        
                TaxPer = @TaxPer,  
                                                                                                                                                                                                                          
                TaxAmount = @TaxAmount  
                                                                                                                                                                                                                     
            Where Id = @OrderMasterId  
                                                                                                                                                                                                                      
        end  
                                                                                                                                                                                                                                                
        else  
                                                                                                                                                                                                                                               
        begin  
                                                                                                                                                                                                                                              
            Update OrderMaster  
                                                                                                                                                                                                                             
            Set IsHold = @IsHold,  
                                                                                                                                                                                                                          
                IsFinalPaid = @IsFinalPaid,  
                                                                                                                                                                                                                
                ISChange = @IsChange,  
                                                                                                                                                                                                                      
                OrderAmount = @OrderAmount,  
                                                                                                                                                                                                                
                OrderNetAmount = @OrderNetAmount,  
                                                                                                                                                                                                          
                OrderDiscount = @OrderDiscount,  
                                                                                                                                                                                                            
                DiscountId = @DiscountId,  
                                                                                                                                                                                                                  
                TaxesId = @TaxesId,  
                                                                                                                                                                                                                        
                TaxPer = @TaxPer,  
                                                                                                                                                                                                                          
                TaxAmount = @TaxAmount  
                                                                                                                                                                                                                     
            Where Id = @OrderMasterId  
                                                                                                                                                                                                                      
        end  
                                                                                                                                                                                                                                                
  
                                                                                                                                                                                                                                                           
        Update OrderMaster  
                                                                                                                                                                                                                                 
        Set DeletedOrderAmount = @OrderAmount,  
                                                                                                                                                                                                             
            DeletedOrderNetAmount = @OrderNetAmount,  
                                                                                                                                                                                                       
            Deletedtaxamount = @TaxAmount  
                                                                                                                                                                                                                  
        Where Id = @OrderMasterId  
                                                                                                                                                                                                                          
              and DeletedOrderAmount IS NOT NULL  
                                                                                                                                                                                                           
              and DeletedOrderNetAmount IS NOT NULL  
                                                                                                                                                                                                        
              AND Deletedtaxamount IS NOT NULL  
                                                                                                                                                                                                             
  
                                                                                                                                                                                                                                                           
    End  
                                                                                                                                                                                                                                                    
    if (@Json != 'NULL')  
                                                                                                                                                                                                                                   
    Begin  
                                                                                                                                                                                                                                                  
        DECLARE @jsontable TABLE  
                                                                                                                                                                                                                           
        (  
                                                                                                                                                                                                                                                  
            OrderMasterId int,  
                                                                                                                                                                                                                             
            CategoryId varchar(200),  
                                                                                                                                                                                                                       
            SubCategoryId int,  
                                                                                                                                                                                                                             
            ItemId int,  
                                                                                                                                                                                                                                    
            ItemVeriationId int,  
                                                                                                                                                                                                                           
            ItemRateId int,  
                                                                                                                                                                                                                                
            ItemQty int,  
                                                                                                                                                                                                                                   
            Rate decimal(18, 2),  
                                                                                                                                                                                                                           
            Amount decimal(18, 2),  
                                                                                                                                                                                                                         
            CreatedBy int,  
                                                                                                                                                                                                                                 
            CreateDate datetime,  
                                                                                                                                                                                                                           
            IsActive bit,  
                                                                                                                                                                                                                                  
            IsDeleted bit,  
                                                                                                                                                                                                                                 
			IsHold bit,  
                                                                                                                                                                                                                                             
            IsFinalPaid bit,  
                                                                                                                                                                                                                               
            OrderDetailSelfId bigint,  
                                                                                                                                                                                                                      
            IsPrinted int,  
                                                                                                                                                                                                                                 
            Notes varchar(Max)  
                                                                                                                                                                                                                             
        )  
                                                                                                                                                                                                                                                  
        INSERT INTO @jsontable  
                                                                                                                                                                                                                             
        SELECT *  
                                                                                                                                                                                                                                           
        FROM  
                                                                                                                                                                                                                                               
            OPENJSON(@Json)  
                                                                                                                                                                                                                                
            WITH  
                                                                                                                                                                                                                                           
            (  
                                                                                                                                                                                                                                              
                OrderMasterId int,  
                                                                                                                                                                                                                         
                CategoryId varchar(200),  
                                                                                                                                                                                                                   
                SubCategoryId int,  
                                                                                                                                                                                                                         
                ItemId int,  
                                                                                                                                                                                                                                
                ItemVeriationId int,  
                                                                                                                                                                                                                       
                ItemRateId int,  
                                                                                                                                                                                                                            
                ItemQty int,  
                                                                                                                                                                                                                               
                Rate decimal(18, 2),  
                                                                                                                                                                                                                       
                Amount decimal(18, 2),  
                                                                                                                                                                                                                     
                CreatedBy int,  
                                                                                                                                                                                                                             
                CreateDate datetime,  
                                                                                                                                                                                                                       
                IsActive bit,  
                                                                                                                                                                                                                              
                IsDeleted bit,  
                                                                                                                                                                                                                             
                IsHold bit,  
                                                                                                                                                                                                                                
                IsFinalPaid bit,  
                                                                                                                                                                                                                           
                OrderDetailSelfId bigint,  
                                                                                                                                                                                                                  
                IsPrinted int,  
                                                                                                                                                                                                                             
                Notes varchar(Max)  
                                                                                                                                                                                                                         
            )  
                                                                                                                                                                                                                                              
        Update @jsontable  
                                                                                                                                                                                                                                  
        Set OrderMasterId = @OrderMasterId,  
                                                                                                                                                                                                                
            CreatedBy = @CreatedBy,  
                                                                                                                                                                                                                        
            CreateDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'),  
                                                                                                                                                       
            IsActive = 1,  
                                                                                                                                                                                                                                  
            IsDeleted = 0  
                                                                                                                                                                                                                                  
  
                                                                                                                                                                                                                                                           
        Update OrderDetail  
                                                                                                                                                                                                                                 
        Set IsHold = 0  
                                                                                                                                                                                                                                     
        Where OrderMasterId = @OrderMasterId  
                                                                                                                                                                                                               
  
                                                                                                                                                                                                                                                           
        Insert into OrderDetail  
                                                                                                                                                                                                                            
        Select *,  
                                                                                                                                                                                                                                          
               NULL,  
                                                                                                                                                                                                                                       
               NULL,
                                                                                                                                                                                                                                         
               NULL
                                                                                                                                                                                                                                          
        from @jsontable  
                                                                                                                                                                                                                                    
  
                                                                                                                                                                                                                                                           
        -- For Receipt Count on Item addition in same order  
                                                                                                                                                                                                
        Update OrderMaster  
                                                                                                                                                                                                                                 
        Set ReceiptCount = ISNULL(ReceiptCount, 0) + 1  
                                                                                                                                                                                                     
        Where Id = @OrderMasterId  
                                                                                                                                                                                                                          
  
                                                                                                                                                                                                                                                           
  
                                                                                                                                                                                                                                                           
        --******************Option1**********************      
                                                                                                                                                                                              
        if (@JsonOrderDetailOption1 != 'NULL')  
                                                                                                                                                                                                             
        begin  
                                                                                                                                                                                                                                              
            Declare @Option1Table Table  
                                                                                                                                                                                                                    
            (  
                                                                                                                                                                                                                                              
                Option1Id int,  
                                                                                                                                                                                                                             
                OrderId int,  
                                                                                                                                                                                                                               
                ItemId int,  
                                                                                                                                                                                                                                
                ItemVeriationId int,  
                                                                                                                                                                                                                       
                ItemRateId int,  
                                                                                                                                                                                                                            
                CategoryId int,  
                                                                                                                                                                                                                            
                SubCategoryId int,  
                                                                                                                                                                                                                         
                OrderDetailSelfId bigint  
                                                                                                                                                                                                                   
            )  
                                                                                                                                                                                                                                              
            Insert Into @Option1Table  
                                                                                                                                                                                                                      
            SELECT *  
                                                                                                                                                                                                                                       
            FROM  
                                                                                                                                                                                                                                           
                OPENJSON(@JsonOrderDetailOption1)  
                                                                                                                                                                                                          
                WITH  
                                                                                                                                                                                                                                       
                (  
                                                                                                                                                                                                                                          
                    Option1Id int,  
                                                                                                                                                                                                                         
                    OrderId int,  
                                                                                                                                                                                                                           
                    ItemId int,  
                                                                                                                                                                                                                            
                    ItemVeriationId int,  
                                                                                                                                                                                                                   
                    ItemRateId int,  
                                                                                                                                                                                                                        
                    CategoryId int,  
                                                                                                                                                                                                                        
                    SubCategoryId int,  
                                                                                                                                                                                                                     
                    OrderDetailSelfId bigint  
                                                                                                                                                                                                               
                )  
                                                                                                                                                                                                                                          
            Update @Option1Table  
                                                                                                                                                                                                                           
            Set OrderId = @OrderMasterId  
                                                                                                                                                                                                                   
  
                                                                                                                                                                                                                                                           
            Insert Into OrderDetailOption1  
                                                                                                                                                                                                                 
            Select *  
                                                                                                                                                                                                                                       
            from @Option1Table  
                                                                                                                                                                                                                             
        end  
                                                                                                                                                                                                                                                
        --******************Option1**********************      
                                                                                                                                                                                              
        --******************Option2**********************      
                                                                                                                                                                                              
        if (@JsonOrderDetailOption2 != 'NULL')  
                                                                                                                                                                                                             
        begin  
                                                                                                                                                                                                                                              
            Declare @Option2Table Table  
                                                                                                                                                                                                                    
            (  
                                                                                                                                                                                                                                              
                Option2Id int,  
                                                                                                                                                                                                                             
                OrderId int,  
                                                                                                                                                                                                                               
                ItemId int,  
                                                                                                                                                                                                                                
                ItemVeriationId int,  
                                                                                                                                                                                                                       
                ItemRateId int,  
                                                                                                                                                                                                                            
                CategoryId int,  
                                                                                                                                                                                                                            
                SubCategoryId int,  
                                                                                                                                                                                                                         
                OrderDetailSelfId bigint  
                                                                                                                                                                                                                   
            )  
                                                                                                                                                                                                                                              
            Insert Into @Option2Table  
                                                                                                                                                                                                                      
            SELECT *  
                                                                                                                                                                                                                                       
            FROM  
                                                                                                                                                                                                                                           
                OPENJSON(@JsonOrderDetailOption2)  
                                                                                                                                                                                                          
                With  
                                                                                                                                                                                                                                       
                (  
                                                                                                                                                                                                                                          
                    Option2Id int,  
                                                                                                                                                                                                                         
                    OrderId int,  
                                                                                                                                                                                                                           
                    ItemId int,  
                                                                                                                                                                                                                            
                    ItemVeriationId int,  
                                                                                                                                                                                                                   
                    ItemRateId int,  
                                                                                                                                                                                                                        
                    CategoryId int,  
                                                                                                                                                                                                                        
                    SubCategoryId int,  
                                                                                                                                                                                                                     
                    OrderDetailSelfId bigint  
                                                                                                                                                                                                               
                )  
                                                                                                                                                                                                                                          
  
                                                                                                                                                                                                                                                           
            Update @Option2Table  
                                                                                                                                                                                                                           
            Set OrderId = @OrderMasterId  
                                                                                                                                                                                                                   
  
                                                                                                                                                                                                                                                           
            Insert Into OrderDetailOption2  
                                                                                                                                                                                                                 
            Select *  
                                                                                                                                                                                                                                       
            from @Option2Table  
                                                                                                                                                                                                                             
        end  
                                                                                                                                                                                                                                                
        --******************Option2**********************      
                                                                                                                                                                                              
        --******************Addon**********************      
                                                                                                                                                                                                
        if (@JsonOrderDetailAddOns != 'NULL')  
                                                                                                                                                                                                              
        begin  
                                                                                                                                                                                                                                              
            Declare @AddonTable Table  
                                                                                                                                                                                                                      
            (  
                                                                                                                                                                                                                                              
                AddonId int,  
                                                                                                                                                                                                                               
                OrderId int,  
                                                                                                                                                                                                                               
                ItemId int,  
                                                                                                                                                                                                                                
                ItemVeriationId int,  
                                                                                                                                                                                                                       
                ItemRateId int,  
                                                                                                                                                                                                                            
                CategoryId int,  
                                                                                                                                                                                                                            
                SubCategoryId int,  
                                                                                                                                                                                                                         
                OrderDetailSelfId bigint  
                                                                                                                                                                                                                   
            )  
                                                                                                                                                                                                                                              
            Insert into @AddonTable  
                                                                                                                                                                                                                        
            SELECT *  
                                                                                                                                                                                                                                       
            FROM  
                                                                                                                                                                                                                                           
                OPENJSON(@JsonOrderDetailAddOns)  
                                                                                                                                                                                                           
                WITH  
                                                                                                                                                                                                                                       
                (  
                                                                                                                                                                                                                                          
                    AddonId int,  
                                                                                                                                                                                                                           
                    OrderId int,  
                                                                                                                                                                                                                           
                    ItemId int,  
                                                                                                                                                                                                                            
                    ItemVeriationId int,  
                                                                                                                                                                                                                   
                    ItemRateId int,  
                                                                                                                                                                                                                        
                    CategoryId int,  
                                                                                                                                                                                                                        
                    SubCategoryId int,  
                                                                                                                                                                                                                     
                    OrderDetailSelfId bigint  
                                                                                                                                                                                                               
                )  
                                                                                                                                                                                                                                          
            Update @AddonTable  
                                                                                                                                                                                                                             
            Set OrderId = @OrderMasterId  
                                                                                                                                                                                                                   
  
                                                                                                                                                                                                                                                           
            Insert Into OrderDetailAddOns  
                                                                                                                                                                                                                  
            Select *  
                                                                                                                                                                                                                                       
            from @AddonTable  
                                                                                                                                                                                                                               
        end  
                                                                                                                                                                                                                                                
    --******************Addon**********************      
                                                                                                                                                                                                    
  
                                                                                                                                                                                                                                                           
  
                                                                                                                                                                                                                                                           
    End  
                                                                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
	
                                                                                                                                                                                                                                                            
	-- For Lounges update Flight with Order Id
                                                                                                                                                                                                                  
    Update FlightDetails  
                                                                                                                                                                                                                                   
    Set OrderId = @OrderMasterId  
                                                                                                                                                                                                                           
    where Id = @FlightID and OrderId = 0  
                                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
    Select @OrderNo = JobRefNo  
                                                                                                                                                                                                                             
    from OrderMaster  
                                                                                                                                                                                                                                       
    Where Id = @OrderMasterId  
                                                                                                                                                                                                                              
    Select @Msg = @OrderMasterId  
                                                                                                                                                                                                                           
  
                                                                                                                                                                                                                                                           
End  
                                                                                                                                                                                                                                                        

