-- Stored Procedure: [SP_GetALLFcmToken]
IF OBJECT_ID('[SP_GetALLFcmToken]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetALLFcmToken];
GO
  
CREATE Procedure [dbo].[SP_GetALLFcmToken]  
@OrderFrom varchar(100),  
@OrderId int   
As  
Begin  
 Declare @TableId int  
Declare @WaiterId int  
Declare @deviceId varchar(MAX)  
Select @deviceId = DeviceId from OrderMaster Where Id = @OrderId  
if(@OrderFrom ='WaiterApp' And @deviceId IS NOT NULL)  
Begin  
 Select @deviceId FCMToken  
 Union  
 Select DeviceId FCMToken from login Where (ISBackOffice  = 0 OR ISBackOffice IS NULL)  
End  
Else if(@OrderFrom ='WaiterApp')  
Begin  
 Select DeviceId FCMToken from login Where (ISBackOffice  = 0 OR ISBackOffice IS NULL)  
End  
else if(@OrderFrom = 'CustomerApp')  
Begin  
 Select @TableId = TableId from OrderMaster Where Id = @OrderId  
 Select @WaiterId =  WaiterId from AssignTable Where TableId = @TableId  
 Select FCMToken from Waiter Where Id = @WaiterId  
 Union  
 Select DeviceId FCMToken from login Where (ISBackOffice  = 0 OR ISBackOffice IS NULL)  
End  
else if(@OrderFrom = 'WebAPP')  
begin  
	Select @TableId = TableId from OrderMaster Where Id = @OrderId  
	Select @WaiterId = WaiterId from OrderMaster Where Id = @OrderId  
	if(@WaiterId = NULL)
		Begin
			Select @WaiterId =  WaiterId from AssignTable Where TableId = @TableId  
		End
 --Select FCMToken from Waiter Where Id = @WaiterId  
  
 --Send notification to customer  
 Declare @CustomerApp varchar(50)  
 Select @CustomerApp = OrderFrom From OrderMaster Where Id = @OrderId  
 if(@CustomerApp = 'CustomerApp')  
 BEGIN  
  Select FCMToken from Waiter Where Id = @WaiterId  
  Union  
  Select @deviceId FCMToken  
 END  
 ELSE  
  Select FCMToken from Waiter Where Id = @WaiterId  
  
End  
else if(@OrderFrom = 'Feedback')  
Begin  
 --Notification only on web in case of feedback submit  
 Select DeviceId FCMToken from login Where (ISBackOffice  = 0 OR ISBackOffice IS NULL)  
End  
End  

GO

