-- Stored Procedure: [SP_GetAllOrders]
IF OBJECT_ID('[SP_GetAllOrders]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetAllOrders];
GO
-- Run this script in your SQL Server database to update the stored procedure for DB-level pagination.

CREATE Procedure [dbo].[SP_GetAllOrders]           
  @OrderStatus Varchar(100)='',            
  @IsWeb   varchar(100)='',            
  @FromDate  varchar(100)='',            
  @ToDate   varchar(100)='',  
  @OrderNo varchar(100) = '',  
  @OrderTypeId varchar(100) = NULL,  
  @PaymentStatus varchar(100) = NULL,
  @CustomerName varchar(100) = NULL,
  @PageNumber INT = 1,
  @PageSize INT = 10
  As            
  Begin            
  Select *, TotalCount = COUNT(*) OVER() from             
  (            
  Select OrderMaster.Id,JobRefNo, OrderTypeId, ISNULL(CustomerName, '') CustomerName,
  Case When DeletedOrderAmount Is Null Then ISNULL(OrderAmount,0.00) Else DeletedOrderAmount End OrderAmount,  
  Case When DeletedTaxAmount Is Null Then ISNULL(TaxAmount, 0.00) Else DeletedTaxAmount End TaxAmount,        
  Case When TaxPer IS NULL Then 0.00 Else TaxPer End TaxPer,Case When OrderDiscount Is Null Then 0.00 Else OrderDiscount End OrderDiscount,        
  Case When DiscountPer IS NULL Then ISNULL(OrderDiscountPer, 0)  Else DiscountPer End OrderDiscountPer,  
  ISNULL(DeletedOrderNetAmount, OrderNetAmount) AS OrderNetAmount,  
  Case   
   When OrderTypeId = 6 Then 'Takeaway'  
   When OrderTypeId = 8 Then 'Entertainment'  
   When OrderTypeId = 9 Then 'Staff'  
   When OrderTypeId = 10 Then 'Party'  
   Else OrderMaster.TableNo   
  End TableNo  
  ,CASE   
      WHEN IsFinalPaid = 0 THEN 'Pending'  
      WHEN IsFinalPaid = 1 THEN 'Cleared'  
      ELSE 'Cancelled'  
  END AS OrderStatus  
  ,OrderFrom IsWeb      
  ,isPaymentCollected  
  ,CONVERT(date,OrderDate) OrderOnlyDate, convert(varchar,OrderDate,100) as  OrderDate ,Case When  CFB.FeedBackDesc IS Null Then '' Else CFB.FeedBackDesc End FeedBackDesc,    
  Case When CFB.Rating IS NULL Then 0 Else CFB.Rating End Rating,  
  Case When CFB.ServiceRating IS NULL Then 0 Else CFB.ServiceRating End ServiceRating,  
  Case When CFB.AmbianceRating IS NULL Then 0 Else CFB.AmbianceRating End AmbianceRating,  
  Case When PaymentType IS NULL THEN '' ELSE PaymentType End PaymentType  
  from OrderMaster         
  Left Join CustomerFeedBack CFB On OrderMaster.Id = CFB.OrderId        
  ) As Tbl             
  Where             
  (OrderStatus = @OrderStatus Or (@OrderStatus ='' OR @OrderStatus IS NULL))            
  And (IsWeb = @IsWeb Or (@IsWeb ='' Or @IsWeb IS NULL))      
  And (OrderTypeId = @OrderTypeId Or (@OrderTypeId ='' Or @OrderTypeId IS NULL))   
  And (IsPaymentCollected = @PaymentStatus Or (@PaymentStatus ='' Or @PaymentStatus IS NULL))   
  And (JobRefNo LIKE '%' + @OrderNo + '%' Or (@OrderNo ='' Or @OrderNo IS NULL))   
  And (CustomerName LIKE '%' + @CustomerName + '%' Or (@CustomerName ='' Or @CustomerName IS NULL))   
  And case when @FromDate !='' And @ToDate !='' And OrderOnlyDate Between @FromDate And @ToDate then 1             
   when (@FromDate ='' And @ToDate ='') and OrderOnlyDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss') then 1 else 0 end =1          
  Order By OrderStatus desc, JobRefNo  Desc           
  OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
  End

GO

