-- Stored Procedure: [sp_GetBookingTypes_Stats]
IF OBJECT_ID('[sp_GetBookingTypes_Stats]', 'P') IS NOT NULL DROP PROCEDURE [sp_GetBookingTypes_Stats];
GO
CREATE Procedure [dbo].[sp_GetBookingTypes_Stats]   --'08-04-2021 00:00','08-04-2021 23:59',null,null     
@FromDateTime as dateTime = NULL,        
@ToDateTime as dateTime = NULL,         
@ZoneId as int = NULL,                
@PostCode AS VARCHAR(MAX) = NULL     
        
AS                                                    
                
				   
-- IVR Booking          
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE bookingtypeid=4 and pickupdatetime between @FromDateTime and @ToDateTime                          
                            
-- Web Booking        
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE bookingtypeid=3 and pickupdatetime between @FromDateTime and @ToDateTime                            
        
-- App Booking                           
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE bookingtypeid=2 and pickupdatetime between @FromDateTime and @ToDateTime                            
           
-- Waiting booking for next 1 hour             
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE BookingStatusId in (1, 16)  and pickupdatetime between GETDATE() AND  DATEADD(HOUR, 1, GETDATE())                                                
        
-- Ongoing bookings         
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE BookingStatusId in (5) and pickupdatetime >= GETDATE() - 1                           
                      
-- Total booking          
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE   pickupdatetime between @FromDateTime and @ToDateTime                  
        
SELECT TotalAvailableDrivers = (SELECT cnt = COUNT(c.ID) FROM DriverLogin c Where c.DriverStatusId=2 or c.DriverStatusId=6)                       
        , TotalWorkingDrivers = (SELECT cnt = COUNT(c.ID) FROM DriverDetail c Where c.IsActive = 1 and c.IsDeleted = 0)                                  
                    
	
-- Most Pickup Plot                    
SELECT CASE WHEN COUNT(*) > 0 THEN COUNT(*) ELSE -1 END AS [RowCount] FROM BOOKINGstatistics WHERE Pickupzoneid=@ZoneId and RowInsertedOn between @FromDateTime and @ToDateTime        
        
 -- Most Pickup PostCode        
SELECT CASE WHEN COUNT(*) > 0 THEN COUNT(*) ELSE -1 END AS [RowCount] FROM BOOKINGstatistics WHERE pickuppostcode=@POSTCODE and RowInsertedOn between @FromDateTime and @ToDateTime        


----Cancelled
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE BookingStatusId=7 and pickupdatetime between @FromDateTime and @ToDateTime                            

----No Pickup------
--SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE BookingStatusId=2 and pickupdatetime between @FromDateTime and @ToDateTime                            
SELECT COUNT(*) AS [RowCount] FROM BOOKINGstatistics WHERE BookingStatusId=6 and pickupdatetime between @FromDateTime and @ToDateTime                            


GO

-- Stored Procedure: [sp_GetBookingTypes_Stats_Graph]
IF OBJECT_ID('[sp_GetBookingTypes_Stats_Graph]', 'P') IS NOT NULL DROP PROCEDURE [sp_GetBookingTypes_Stats_Graph];
GO

CREATE Procedure [dbo].[sp_GetBookingTypes_Stats_Graph]      
@starttime   datetime=null,
@Endttime   datetime =null 
AS 


--declare @starttime datetime='2020-11-03 18:00' 
--declare @Endttime datetime='2020-11-04 06:00'

select   

   CASE WHEN (DATEPART(HOUR, (bs.PickupDateTime))) =null then 0 else DATEPART(HOUR, (bs.PickupDateTime)) end  as [Time],
CASE WHEN COUNT(*) > 0 THEN COUNT(*) ELSE 0 END as TotalBookings
,DATEPART(day, (bs.PickupDateTime)) as Day 

from BookingStatistics as bs

where bs.PickupDateTime between @starttime and @Endttime
group by DATEPART(HOUR, (bs.PickupDateTime)) ,DATEPART(Day, (bs.PickupDateTime))

GO

-- Stored Procedure: [SP_GetCategories_TableTab]
IF OBJECT_ID('[SP_GetCategories_TableTab]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetCategories_TableTab];
GO
  
CREATE Procedure [dbo].[SP_GetCategories_TableTab]      
AS      
Begin      
Select Distinct C.Id,C.CategoryDesc,C.ShortDesc,C.ImageUrl,C.ResturantId,C.SortOrder--,SC.Id SubCategoryID       
--,STRING_AGG( ISNULL(SC.Id, ' '), ',') SubCategoryID      
from Category C      
Left Join SubCategory SC On C.Id = SC.CategoryId Where C.IsActive = 1 AND C.Id = C.Id 


 and(
        (CONVERT(TIME, C.starttime) <= CONVERT(TIME, GETDATE()) AND CONVERT(TIME, C.endtime) >= CONVERT(TIME, GETDATE())) OR
        (CONVERT(TIME, C.starttime) > CONVERT(TIME, C.endtime) AND
            (CONVERT(TIME, GETDATE()) >= CONVERT(TIME, C.starttime) OR CONVERT(TIME, GETDATE()) <= CONVERT(TIME, C.endtime)))
			or
			C.starttime is null
    )


Order By C.SortOrder
End

GO

-- Stored Procedure: [SP_GetCategoryForDinin]
IF OBJECT_ID('[SP_GetCategoryForDinin]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetCategoryForDinin];
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE Procedure [dbo].[SP_GetCategoryForDinin]
    @ResturantId int
AS
BEGIN
    SELECT C.Id, C.ResturantId, C.CategoryDesc, C.ShortDesc, C.SortOrder, C.ImageUrl, C.CreatedBy, C.CreateDate, C.IsActive, C.IsDeleted,C.MaxCategoryQty,
           STUFF((SELECT ', ' + CAST(Sc.Id AS VARCHAR(10))
                  FROM SubCategory Sc
                  WHERE C.Id = Sc.CategoryId
                  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS SubCategoryId
    FROM Category C
    WHERE C.IsActive = 1 AND C.IsDeleted = 0 AND C.ResturantId = @ResturantId

	 AND (
        (CONVERT(TIME, C.starttime) <= CONVERT(TIME, GETDATE()) AND CONVERT(TIME, C.endtime) >= CONVERT(TIME, GETDATE())) OR
        (CONVERT(TIME, C.starttime) > CONVERT(TIME, C.endtime) AND
            (CONVERT(TIME, GETDATE()) >= CONVERT(TIME, C.starttime) OR CONVERT(TIME, GETDATE()) <= CONVERT(TIME, C.endtime)))

			OR C.starttime IS NULL
    )


	Order By C.SortOrder
END

GO

