-- Stored Procedure: [SP_GetConsumption]
IF OBJECT_ID('[SP_GetConsumption]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetConsumption];
GO
-- =============================================
-- Author:		<Rameez>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE Procedure [dbo].[SP_GetConsumption] 
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Select a.ItemDesc, sum(a.ItemQty) as TotalQty, a.MaterialDesc, a.Qty, (SUM(a.ItemQty) * a.Qty) as Consumption, a.ConsumptionUOM, convert(date,a.CreateDate) as CreatedDate
	from (
	select  I.ItemDesc, ItemQty, MaterialDesc, Qty, ConsumptionUOM,  (ItemQty * Qty) as consumption, convert(date,OD.CreateDate) as CreateDate 
	from OrderDetail OD
	join Item I on I.Id = OD.ItemId
	join Recipe R on R.ItemId = OD.ItemId
	join RawMaterial RM on RM.Id = RawMaterialId
	)a
	Group by a.ItemQty, a.ItemDesc, a.MaterialDesc, a.Qty, a.ConsumptionUOM, convert(date,a.CreateDate)
	order by convert(date,a.CreateDate)

END

GO

-- Stored Procedure: [SP_GetCurrentOrder]
IF OBJECT_ID('[SP_GetCurrentOrder]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetCurrentOrder];
GO
CREATE Procedure [dbo].[SP_GetCurrentOrder]          
@ResturantId  Int          
As          
Begin          
Select OM.Id OrderId,R.RestaurantShortName  +'-0000' + Convert(varchar(100),  OM.Id) OrderNo,CONVERT(varchar, OM.OrderDate,23) OrderDate,C.Fname,C.TelephoneNo,OM.PicupLocation,OM.PickupLat,OM.PickupLan,OM.DestinationLocation,          
OM.DestinationLat,OM.DestinationLan,OM.OrderNetAmount,  
Case When DD.DriverName IS NULL Then '' Else DD.DriverName End DriverName,  
Case When DD.DriverNo IS NULL Then '' Else DD.DriverNo End DriverNo,  
Case When DS.DriverStatusDesc is null Then '' Else DS.DriverStatusDesc End DriverStatusDesc,  
Case When DS.ColorCode Is Null Then '' Else DS.ColorCode End ColorCode  
from OrderMaster OM          
Inner Join Customer C ON OM.CustomerId = C.Id          
Inner Join Restaurant R ON OM.ResturantId = R.Id         
Left Join DriverStatus DS ON DS.Id = OM.DriverStatusId   
Left Join DriverDetail DD On OM.DriverId = DD.Id  
Where OM.ResturantId= @ResturantId And CONVERT(date, OM.OrderDate) =CONVERT(date, getdate()) And  (OM.DriverStatusId IS NULL OR OM.DriverStatusId !=6)         
End

GO

