CREATE Procedure [dbo].[SP_GetCurrentOrderForApp]           
@ResturantId Int,  
@DriverId  int  
As            
Begin            
Select OM.Id OrderId,R.RestaurantShortName  +'-0000' + Convert(varchar(100),  OM.Id) OrderNo,CONVERT(varchar, OM.OrderDate,23) OrderDate,C.Fname,C.TelephoneNo,OM.PicupLocation,OM.PickupLat,OM.PickupLan,OM.DestinationLocation,            
OM.DestinationLat,OM.DestinationLan,OM.OrderNetAmount,    
Case When DD.DriverName IS NULL Then '' Else DD.DriverName End DriverName,    
Case When DD.DriverNo IS NULL Then '' Else DD.DriverNo End DriverNo,    
Case When DS.DriverStatusDesc is null Then '' Else DS.DriverStatusDesc End DriverStatusDesc,    
Case When DS.ColorCode Is Null Then '' Else DS.ColorCode End ColorCode    
from OrderMaster OM            
Inner Join Customer C ON OM.CustomerId = C.Id            
Inner Join Restaurant R ON OM.ResturantId = R.Id           
Left Join DriverStatus DS ON DS.Id = OM.DriverStatusId     
Left Join DriverDetail DD On OM.DriverId = DD.Id    
Where OM.ResturantId= @ResturantId And OM.DriverId = @DriverId And CONVERT(date, OM.OrderDate) =CONVERT(date, getdate()) And  (OM.DriverStatusId IS NULL OR OM.DriverStatusId !=6)           
End 

GO

-- Stored Procedure: [SP_GetCurrentOrderForDashboard]
IF OBJECT_ID('[SP_GetCurrentOrderForDashboard]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetCurrentOrderForDashboard];
GO
  
-- =============================================  
-- Author:      AI Assistant  
-- Create date: 2026-02-17  
-- Description: Retrieves current orders with advanced filtering and financial analytics.  
--              Backward compatible with original SP.  
-- =============================================  
CREATE PROCEDURE [dbo].[SP_GetCurrentOrderForDashboard]  
    @ResturantId INT,  
    -- New optional filters (defaults maintain backward compatibility)  
    @FromDate DATE = NULL,  
    @ToDate DATE = NULL,  
    @OrderStatusId INT = NULL,  
    @OrderTypeId INT = NULL,  
    @IncludeCancelled BIT = 1,  
    @Mode VARCHAR(20) = 'DETAIL' -- 'DETAIL', 'HOURLY', 'SUMMARY'  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- 1. Default Dates to Today if NULL  
    IF @FromDate IS NULL SET @FromDate = CAST(GETDATE() AS DATE);  
    IF @ToDate IS NULL SET @ToDate = CAST(GETDATE() AS DATE);  
  
    -- 2. Detail Mode (Returns full list - Backward Compatible)  
    IF @Mode = 'DETAIL'  
    BEGIN  
        SELECT   
            -- Existing Columns (Preserved for compatibility)  
            OM.Id AS OrderId,  
            OM.Id AS OrderNo,  
            OM.OrderDate,  
            OM.ResturantId,  
            OM.CustomerId,  
            C.Fname, -- Assuming Joined Customer Table  
            C.TelephoneNo,  
            OM.PicupLocation,  
            OM.PickupLat,  
            OM.PickupLan,  
            -- OM.DestinationLocation, -- Assumed column from JS usage  
            OM.OrderNetAmount,  
            OM.PaymentId,  
              
            -- Driver Status (Color Codes Logic from JS)  
            OM.OrderStatusId,  
  
            -- Financial Fields (New)  
            OM.OrderAmount AS OrderGrossAmount,  
            OM.OrderDiscount,  
            OM.OrderDiscountPer,  
            ISNULL(OM.OrderAmount,0) - ISNULL(OM.OrderDiscount,0) AS TaxableAmount, -- Placeholder logic  
            -- Assuming Tax is calculated or stored. If not, returning 0.  
            0.0 AS TaxAmount,   
              
            -- Metadata  
            DATEDIFF(MINUTE, OM.OrderDate, GETDATE()) AS MinutesElapsed,  
            DATEPART(HOUR, OM.OrderDate) AS OrderHour  
              
        FROM OrderMaster OM  
        LEFT JOIN Customer C ON OM.CustomerId = C.Id  
        WHERE   
            OM.ResturantId = @ResturantId  
            -- SARGable Date Filter  
            AND OM.OrderDate >= @FromDate  
            AND OM.OrderDate < DATEADD(DAY, 1, @ToDate)  
            -- Optional Filters  
            AND (@OrderStatusId IS NULL OR OM.OrderStatusId = @OrderStatusId)  
            AND (@OrderTypeId IS NULL OR OM.PaymentId = @OrderTypeId) -- Assuming PaymentId maps to OrderType (1=DineIn, etc.)  
        ORDER BY OM.OrderDate DESC;  
    END  
  
    -- 3. Hourly Aggregation Mode (For Charts)  
    ELSE IF @Mode = 'HOURLY'  
    BEGIN  
        SELECT   
            DATEPART(HOUR, OM.OrderDate) AS OrderHour,  
            COUNT(*) AS OrderCount,  
            SUM(OM.OrderNetAmount) AS TotalRevenue  
        FROM OrderMaster OM  
  
        WHERE   
            OM.Id = @ResturantId  
            AND OM.OrderDate >= @FromDate  
            AND OM.OrderDate < DATEADD(DAY, 1, @ToDate)  
        GROUP BY DATEPART(HOUR, OM.OrderDate)  
        ORDER BY OrderHour;  
    END  
  
    -- 4. Summary Mode (For Top Cards)  
    ELSE IF @Mode = 'SUMMARY'  
    BEGIN  
        SELECT   
            COUNT(*) AS TotalOrders,  
            SUM(OM.OrderNetAmount) AS TotalRevenue,  
            AVG(OM.OrderNetAmount) AS AvgOrderValue  
        FROM OrderMaster OM  
        WHERE   
            OM.ResturantId = @ResturantId  
            AND OM.OrderDate >= @FromDate  
            AND OM.OrderDate < DATEADD(DAY, 1, @ToDate);  
    END  
  
END  

GO

