CREATE Procedure [dbo].[SP_GetDealItems]  
As  
Begin  
Select I.* from Category C  
Inner Join SubCategory SC ON C.Id = SC.CategoryId  
Inner Join Item I On SC.Id = I.SubCategoryId  
Where C.CategoryDesc = 'DEAL' And I.Id Not In (Select CategoryId from DealDetails where IsActive = 1)  
End

