CREATE Procedure [dbo].[SP_GetDealsDetail]  
@CategoryId  int  
As  
Begin  
Select DD.Id DealId,DD.CategoryId,DD.SubCategoryId,DD.ItemId,DD.ItemVeriationId,DD.ItemRateId,DD.QTY,DD.IsActive,I.ItemDesc,IV.ItemSize from DealDetails DD  
--Inner Join Category C ON DD.CategoryId = C.Id  
Inner Join item C ON DD.CategoryId = C.Id  
Inner Join SubCategory SC ON DD.SubCategoryId = SC.Id  
