CREATE Procedure [dbo].[SP_GetDriverOrdersList]        
@ResturantId  Int,
@DriverId int,
@OrderStatusID int
As        
Begin        
Select OM.Id OrderId,R.RestaurantShortName  +'-0000' + Convert(varchar(100),  OM.Id) OrderNo,CONVERT(varchar, OM.OrderDate,23) OrderDate,C.Fname,C.TelephoneNo,OM.PicupLocation,OM.PickupLat,OM.PickupLan,OM.DestinationLocation,        
OM.DestinationLat,OM.DestinationLan,OM.OrderNetAmount,
Case When DD.DriverName IS NULL Then '' Else DD.DriverName End DriverName,
Case When DD.DriverNo IS NULL Then '' Else DD.DriverNo End DriverNo,
Case When DS.DriverStatusDesc is null Then '' Else DS.DriverStatusDesc End DriverStatusDesc,
Case When DS.ColorCode Is Null Then '' Else DS.ColorCode End ColorCode
from OrderMaster OM        
Inner Join Customer C ON OM.CustomerId = C.Id        
Inner Join Restaurant R ON OM.ResturantId = R.Id       
Left Join DriverStatus DS ON DS.Id = OM.DriverStatusId 
Left Join DriverDetail DD On OM.DriverId = DD.Id
Where (OM.ResturantId= @ResturantId)  
and (OM.DriverId= @ResturantId)  
and (OM.DriverStatusId= @ResturantId)  
And  (OM.DriverStatusId IS NULL OR OM.DriverStatusId !=6)  
and (OM.DriverStatusId IS NULL OR OM.DriverStatusId !=3)and (OM.DriverStatusId IS NULL OR OM.DriverStatusId !=2) 
End 

GO

-- Stored Procedure: [sp_GetFlightDetails]
IF OBJECT_ID('[sp_GetFlightDetails]', 'P') IS NOT NULL DROP PROCEDURE [sp_GetFlightDetails];
GO
CREATE proc [dbo].[sp_GetFlightDetails]          
                                                                                                                                                                                                            
                                                                                                                                                                                                            
                                                 
@FromDate  varchar(100)='',            
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      
                                       
@ToDate   varchar(100)='',  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
@FlightNo varchar(100) = '',   
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
@PaymentStatus varchar(100) = '',
                                                                                                                                                                                                                            
                                                                                                                                                                                                                            
                                 
@PaymentType varchar(100) = '', 
                                                                                                                                                                                                                             
                                                                                                                                                                                                                             
                                
@BankId varchar(100) = '', 
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
@FTPayment varchar(100) = '',
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
@BinNo varchar(100) = '',
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
@PageNumber INT = 1,
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
@PageSize INT = 10,
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
@ExportAll BIT = 0
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
AS
                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                           
  
BEGIN
                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                        
     
    SET NOCOUNT ON;
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   

                                                                                                                                                                                                                                                             
                                                                                                              
                                                                                                                                               
    DECLARE @TotalCount INT;
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            

                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                             

    -- 1. Get the Total Count (Fast without subqueries)
                                                                                                                                                                                                      
                                                                                                                                                                                                      
                                                       
    SELECT @TotalCount = COUNT(DISTINCT f.Id)
                                                                                                                                                                                                                
                                                                                                                                                                                                                
                                             
    FROM FlightDetails f
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
    left join Bank b on f.BankId = b.Id
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      
                                       
    inner join Customer c on f.Id = c.FlightId
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
    left join OrderMaster o ON f.OrderId = o.Id
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
    inner join UserDetail ud ON ud.Id = f.CreatedBy
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
    Where
                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                    
         
        (f.PaymentBy = @PaymentStatus Or (@PaymentStatus ='' Or @PaymentStatus IS NULL) OR f.PaymentType = @PaymentStatus)   
                                                                                                                                
                                                                                                                                
                                                                                                                             
        And (f.FlightNo LIKE '%' + @FlightNo + '%' Or (@FlightNo ='' Or @FlightNo IS NULL)) 
                                                                                                                                                                 
                                                                                                                                                                 
                                                                                            
        And (f.PaymentType LIKE '%' + @PaymentType + '%' Or (@PaymentType ='' Or @PaymentType IS NULL))   
                                                                                                                                                   
                                                                                                                                                   
                                                                                                          
        And (f.BankId = @BankId Or (@BankId ='' Or @BankId IS NULL))   
                                                                                                                                                                                      
                                                                                                                                                                                      
                                                                       
        And (f.FTPayment = @FTPayment Or (@FTPayment ='' Or @FTPayment IS NULL))   
                                                                                                                                                                          
                                                                                                                                                                          
                                                                                   
        And (f.BinNo LIKE '%' + @BinNo + '%' Or (@BinNo ='' Or @BinNo IS NULL))  
                                                                                                                                                                            
                                                                                                                                                                            
                                                                                 
        AND (@FromDate = '' OR @FromDate IS NULL OR CAST(f.CreatedDate AS DATE) >= CAST(@FromDate AS DATE)) AND (@ToDate = '' OR @ToDate IS NULL OR CAST(f.CreatedDate AS DATE) <= CAST(@ToDate AS DATE))
                                                                                                                                                                                                                               
                                                                                                                                                                                                                               
                              

                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                             

    -- 2. Fetch the specific page of IDs, then load their full details
                                                                                                                                                                                       
                                                                                                                                                                                       
                                                                      
    ;WITH PaginatedIds AS (
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
        SELECT f.Id
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
        FROM FlightDetails f
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
        left join Bank b on f.BankId = b.Id
                                                                                                                                                                                                                  
                                                                                                                                                                                                                  
                                           
        inner join Customer c on f.Id = c.FlightId
                                                                                                                                                                                                           
                                                                                                                                                                                                           
                                                  
        left join OrderMaster o ON f.OrderId = o.Id
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
        inner join UserDetail ud ON ud.Id = f.CreatedBy
                                                                                                                                                                                                      
                                                                                                                                                                                                      
                                                       
        Where
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                
             
            (f.PaymentBy = @PaymentStatus Or (@PaymentStatus ='' Or @PaymentStatus IS NULL) OR f.PaymentType = @PaymentStatus)   
                                                                                                                            
                                                                                                                            
                                                                                                                                 
            And (f.FlightNo LIKE '%' + @FlightNo + '%' Or (@FlightNo ='' Or @FlightNo IS NULL)) 
                                                                                                                                                             
                                                                                                                       
                                                                                                                                      
            And (f.PaymentType LIKE '%' + @PaymentType + '%' Or (@PaymentType ='' Or @PaymentType IS NULL))   
                                                                                                                                               
                                                                                                                                               
                                                                                                              
            And (f.BankId = @BankId Or (@BankId ='' Or @BankId IS NULL))   
                                                                                                                                                                                  
                                                                                                                                                                                  
                                                                           
            And (f.FTPayment = @FTPayment Or (@FTPayment ='' Or @FTPayment IS NULL))   
                                                                                                                                                                      
                                                                                                                                                                      
                                                                                       
            And (f.BinNo LIKE '%' + @BinNo + '%' Or (@BinNo ='' Or @BinNo IS NULL))  
                                                                                                                                                                        
                                                                                                                                                                        
                                                                                     
            AND (@FromDate = '' OR @FromDate IS NULL OR CAST(f.CreatedDate AS DATE) >= CAST(@FromDate AS DATE)) AND (@ToDate = '' OR @ToDate IS NULL OR CAST(f.CreatedDate AS DATE) <= CAST(@ToDate AS DATE))
                                                                                                                                                                                                                            
                                                                                                                                                                                                                            
                                 
        GROUP BY f.Id
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
                     
        ORDER BY f.Id DESC
                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                   
                          
        OFFSET (@PageNumber - 1) * (CASE WHEN @ExportAll = 1 THEN 9999999 ELSE @PageSize END) ROWS
                                                                                                                                                           
                                                                                                                                                           
                                                                                                  
        FETCH NEXT (CASE WHEN @ExportAll = 1 THEN 9999999 ELSE @PageSize END) ROWS ONLY
                                                                                                                                                                      
                                                                                                                                                                      
                                                                                       
    )
                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                        
     
    SELECT 
                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                  
           
        f.Id, 
                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                               
              
        MIN(f.CreatedDate) AS CreatedDate, 
                                                                                                                                                                                                                  
                
                                                                                                                                                                                                                                             
        (select RestaurantName from Restaurant) as LOC, 
                                                                                                                                                                                                     
                                                                                                                                                                                                     
                                                        
        b.BankName, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.CardProduct, 
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
        f.FlightNo, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.BinNo, 
                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                            
                 
        f.PIN,
                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                               
              
        (SELECT TOP 1 c1.fname FROM Customer c1 WHERE c1.FlightId = f.Id ) AS PassengerName,
                                                                                                                                                                 
                                                                                                                                                                 
                                                                                            
        (SELECT STRING_AGG(c2.fname , ', ') FROM Customer c2 WHERE c2.FlightId = f.Id AND c2.fname != (SELECT TOP 1 c3.fname FROM Customer c3 WHERE c3.FlightId = f.Id ORDER BY c3.Id)) AS Guests,
                                                           
                                                           
                                                                                                                                                                                                  
        (f.NoofMeals - 1) as noofguest, 
                                                                                                                                                                                                                     
                                                                                                                                                                                                                     
                                        
        (f.NoofMeals-COALESCE(f.Children,0)) NoofMeals, 
                                                                                                                                                                                                     
                                                                                                                                                                                                     
                                                        
        o.JobRefNo, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.BankId, 
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
        f.TableId, 
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
        f.TableNo, 
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
        f.PaymentBy, 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
                     
        f.ReceiptNo, 
                                                                                                                                                                                                                                        
                                                                                                                                
                                                                                                                             
        f.WaiterId, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.IsActive, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.CreatedBy, 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
                     
        f.OrderId, 
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
        f.PaymentType, 
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
        f.Airline, 
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                   
        f.FTPayment, 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
                     
        MIN(c.TelephoneNo) AS TelephoneNo, 
                                                                                                                                                                                                                  
                                                                                                                                                                                                                  
                                           
        f.Children, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        ud.Fname AS GRO, 
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
        f.ScanDate, 
                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                         
                    
        f.ScanBy, 
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
        Case when f.IsScan = 1 Then 'Yes' Else 'No' End as Scan, 
                                                                                                                                                                                            
                                                                                                                                                                                            
                                                                 
        f.IsScan, 
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
        f.NoofMeals TotalMeals,
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
        @TotalCount AS TotalCount
                                                                                                                                                                                                                            
                                                                                                                                                                                                                            
                                 
    FROM PaginatedIds p
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
    INNER JOIN FlightDetails f ON f.Id = p.Id
                                                                                                                                                                                                                
                                                                                                                                                                                                                
                                             
    left join Bank b on f.BankId = b.Id
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      
                                       
    inner join Customer c on f.Id = c.FlightId
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
    left join OrderMaster o ON f.OrderId = o.Id
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
    inner join UserDetail ud ON ud.Id = f.CreatedBy
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
    GROUP BY 
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                
             
        f.Id, b.BankName, f.CardProduct, f.FlightNo, f.BinNo, f.PIN, f.NoofMeals,o.JobRefNo, f.BankId, f.TableId, f.TableNo, f.PaymentBy, f.ReceiptNo, 
                                                                                                      
                                                                                                      
                                                                                                                                                       
        f.WaiterId, f.IsActive, f.CreatedBy, f.OrderId, f.PaymentType, f.Airline, f.FTPayment, f.Children, ud.Fname, f.ScanDate, f.IsScan, f.ScanBy
                                                                                                          
                                                                                                          
                                                                                                                                                   
    ORDER BY f.Id DESC;
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
END
                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                          
   

GO

-- Stored Procedure: [SP_GetHoldOrders]
IF OBJECT_ID('[SP_GetHoldOrders]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetHoldOrders];
