CREATE Procedure [dbo].[SP_GetHoldOrders] As Begin Select O.Id as OrderID, O.*, T.OrderType from OrderMaster O left join OrderType T on T.OrderTypeId = O.OrderTypeId Where O.IsHold = 1 And O.IsFinalPaid = 0 And O.IsDeleted = 0 Order by Id desc End
