-- Stored Procedure: [SP_GetItem_TableTab]
IF OBJECT_ID('[SP_GetItem_TableTab]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetItem_TableTab];
GO
CREATE Procedure [dbo].[SP_GetItem_TableTab]    
@CategoryId int    
AS    
Begin    
Select I.Id,SC.CategoryId, I.SubCategoryId,IR.Id RateId,IR.ItemVeriationId,I.ItemDesc,IR.Rate,IV.ItemSize,I.ImageURL,I.ShortDesc from Category C    
Inner Join SubCategory SC On C.Id = SC.CategoryId     
Inner Join Item I On I.SubCategoryId = Sc.Id    
Inner Join ItemRate IR ON I.Id = IR.ItemId    
Inner Join ItemVeriation IV ON IV.Id = IR.ItemVeriationId     
Where C.IsActive = 1 AND SC.IsActive = 1 AND I.IsActive = 1 AND C.Id = @CategoryId --And C.ResturantId = @ResturantId    
End  

GO

-- Stored Procedure: [Sp_GetITemAddons]
IF OBJECT_ID('[Sp_GetITemAddons]', 'P') IS NOT NULL DROP PROCEDURE [Sp_GetITemAddons];
GO

CREATE Procedure [dbo].[Sp_GetITemAddons]  
@ItemId int  
As  
Begin  
Select IA.Id ItemAddOnsId,IA.AddonId,IA.ItemId,A.Option1Desc as AddonsDesc,I.IsAddonMultiselect,I.IsAddonOptional,I.ItemDesc,A.Rate
from ItemAddOns  IA  
--Inner Join Addons A ON IA.AddonId = A.Id
Inner Join Options1 A ON IA.AddonId = A.Id  
Inner Join Item I ON IA.ItemId = I.Id 
Where IA.ItemId = @ItemId And A.IsActive = 1
  
Select IO1.Id ItemOptions1Id,IO1.ItemId,IO1.Option1Id,O.Option1Desc,O.Id, I.ItemDesc,I.IsOptionsMultiselect,I.IsOptionsOptional,O.Rate 
from ItemOptions1 IO1  
Inner Join Options1 O On IO1.Option1Id = O.Id  
Inner Join Item I On IO1.ItemId = I.Id 
Where IO1.ItemId = @ItemId And O.IsActive = 1
  
Select IO2.Id ItemOptions2Id,IO2.ItemId,IO2.Option1Id Option2Id,O.Option1Desc Option2Desc,O.Id, I.ItemDesc,I.IsOptionsMultiselect,I.IsOptionsOptional,O.Rate 
from ItemOptions2 IO2  
Inner Join Options1 O On IO2.Option1Id = O.Id  
Inner Join Item I On IO2.ItemId = I.Id 
Where IO2.ItemId = @ItemId And O.IsActive = 1
  
  
End

GO

