CREATE Procedure [dbo].[SP_GetItemBySubCategory_Category]
@CategoryId varchar(50),
@SubCategoryId varchar(50)
As 
Begin
Select C.Id CategoryId,SC.Id SubCategoryID,I.Id ItemId, I.ItemDesc from Category C
Inner Join SubCategory SC On C.Id = SC.CategoryId
Inner Join Item I On SC.Id  = I.SubCategoryId
