-- Stored Procedure: [SP_GetItemDetailsByShift]
IF OBJECT_ID('[SP_GetItemDetailsByShift]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetItemDetailsByShift];
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GetItemDetailsByShift]
	-- Add the parameters for the stored procedure here
	@ShiftIdCollection as int,
	@FromDate as varchar(20),
	@ToDate as varchar(20),
	@ItemId as int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	Select OD.ItemId,I.ItemDesc, SUM(OD.ItemQty) SoldQty, Count(OM.Id) Orders, SOD.ShiftIdCollection, SOD.ShiftDate, 
	SM.Shift, SM.StartTime, SM.EndTime, SUM(OD.ItemQty * OD.Rate) Amount, ISNULL(OM.OrderDiscountPer, 0) OrderDiscountPer,
	(SUM(OD.ItemQty * OD.Rate) - SUM(OD.ItemQty * OD.Rate) * ISNULL(OM.OrderDiscountPer, 0) / 100) NetAmount
	From OrderMaster OM
	join OrderDetail OD on OD.OrderMasterId = OM.Id
	join Item I on I.Id = OD.ItemId
	join ShiftOrderDetail SOD on SOD.ShiftIdCollection = OM.ShiftIdCollection And SOD.ShiftDate =  CAST(OM.RecDate AS DATE)
	join ShiftMaster SM on SM.Id = SOD.ShiftIdCollection
	WHERE
        (@ShiftIdCollection IS NULL OR @ShiftIdCollection = '' OR SOD.ShiftIdCollection = @ShiftIdCollection)
        AND (@FromDate IS NULL OR @FromDate = '' OR SOD.ShiftDate >= CAST(@FromDate AS DATE))
		AND (@ToDate IS NULL OR @ToDate = '' OR SOD.ShiftDate <= CAST(@ToDate AS DATE))
        AND (@ItemId IS NULL OR @ItemId = '' OR OD.ItemId = @ItemId)
	Group By OD.ItemId, I.ItemDesc, SOD.ShiftDate, SOD.ShiftIdCollection, SM.Shift, SM.StartTime, SM.EndTime, ISNULL(OM.OrderDiscountPer, 0)
	Order By I.ItemDesc,ShiftDate Desc

END

GO

