CREATE Procedure [dbo].[SP_GetItemForDineIn]        
@SubCategoryId int         
AS        
Begin        
--Select * from Item Where SubCategoryId = @SubCategoryId And IsActive = 1 And IsDeleted = 0        
Select tbl.*,TR.Rate,TR.RateId,TR.ItemVeriationId  from(      
Select * from Item I      
Where I.SubCategoryId = @SubCategoryId      
And IsActive = 1 And IsDeleted = 0        
) tbl      
Left JOIN      
(      
  Select IR.Id RateId, IR.ItemId,IR.ItemVeriationId,IR.Rate,IV.ItemSize from ItemRate IR        
Inner Join ItemVeriation IV On IR.ItemVeriationId = IV.ID   AND IV.defaultVeriation = 1      
) TR ON tbl.Id = TR.ItemId  
Order by SortOrder
End 

  

