-- =============================================  
CREATE Procedure [dbo].[SP_GetNotificationItemDelete]   
   
AS  
BEGIN  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  
  
 Select idr.Id, idr.OrderId, om.JobRefNo as OrderNo, idr.ItemId, idr.OrderDetailSelfId,
 idr.ItemQty, idr.ItemStatus, idr.CreatedBy, idr.CreatedDate, i.ItemDesc, 
 om.TableNo,'New Request received from ' + TableNo + ' to Delete ' 
 + CAST(idr.ItemQty AS VARCHAR(50)) +' '+ i.ItemDesc + ' on Order ' + om.JobRefNo as Notification, 
 CAST(DATEPART(SECOND, GETDATE()) AS Varchar(50)) + ' seconds ago...' as LastUpdated
 from ItemDeleteRequest idr  
 join Item i on i.id = idr.ItemId  
 join OrderMaster om on om.id = idr.OrderId  
 where idr.ItemStatus = 'Pending' And om.IsFinalPaid != 1 
 order by convert(date, idr.CreatedDate) 
  
END

