CREATE Procedure [dbo].[SP_GetOnlineWaiters]  
as  
Begin

	SELECT 
	W.Id, W.WaiterName, W.Waiter_UserName, W.FCMToken,
    CASE WHEN W.IsActive = 1 THEN 'Active' ELSE 'UnActive' END AS WaiterStatus,
    CONVERT(varchar, W.CreatedDate, 23) AS strCreatedDate,
    L.UserName,
    ISNULL(STRING_AGG(f.TableNo, ', '), '') AS HomeAddress  -- Aggregate TableNo as comma-separated values
	FROM 
		Waiter W
	INNER JOIN 
		Login L ON L.UserId = W.CreatedBy
	LEFT JOIN 
		FLightDetails f ON f.WaiterId = W.Id AND f.Orderid = 0
	WHERE 
		W.FCMToken IS NOT NULL
	GROUP BY 
		W.Id, W.WaiterName, W.Waiter_UserName, W.IsActive, W.CreatedDate, W.FCMToken, L.UserName

  
End

