-- Stored Procedure: [SP_GetOrderDetail]
IF OBJECT_ID('[SP_GetOrderDetail]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetOrderDetail];
GO
CREATE Procedure [dbo].[SP_GetOrderDetail]  
    @OrderMasterId INT  
AS  
BEGIN  
    -- Retrieve Option1Desc values for each ItemDesc
    SELECT
        OD.OrderDetailSelfId,
        OD.ItemId,
        I.ItemDesc,
        I.ShortDesc,
        STUFF((
                SELECT ', ' + ISNULL(OO1.Option1Desc, '')
                FROM OrderDetailOption1 O1
                INNER JOIN Options1 OO1 ON OO1.Id = O1.Option1Id
                WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId
                    AND O1.ItemId = OD.ItemId
                    AND O1.CategoryId = OD.CategoryId
                FOR XML PATH('')
            ), 1, 2, '') AS Option1Desc1,
        (
            SELECT STUFF((
                    SELECT ', ' + ISNULL(OO2.Option1Desc, '')
                    FROM OrderDetailOption2 O2
                    INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id
                    WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId
                        AND O2.ItemId = OD.ItemId
                        AND O2.CategoryId = OD.CategoryId
                    FOR XML PATH('')
                ), 1, 2, '')
        ) AS Option1Desc2,
        (
            SELECT STUFF((
                    SELECT ', ' + ISNULL(OO3.Option1Desc, '')
                    FROM OrderDetailAddOns O3
                    INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId
                    WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId
                        AND O3.ItemId = OD.ItemId
                        AND O3.CategoryId = OD.CategoryId
                    FOR XML PATH('')
                ), 1, 2, '')
        ) AS Option1DescA
    INTO #TempOption1Desc
    FROM OrderDetail OD
    INNER JOIN Item I ON I.Id = OD.ItemId
    LEFT JOIN OrderDetailOption1 O1 ON O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId
    LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id
    WHERE OD.OrderMasterId = @OrderMasterId and OD.isdeleted = 0 and OD.isactive = 1
    GROUP BY
        OD.OrderDetailSelfId,
        I.ItemDesc,
        I.ShortDesc,
        OD.ItemId,
        OD.CategoryId;

    -- Retrieve the remaining data based on the provided query
    SELECT
        I.ItemDesc,
        I.ShortDesc,
        (
            CASE
                WHEN Option1Desc1 IS NOT NULL AND Option1Desc2 IS NOT NULL AND Option1DescA IS NOT NULL THEN CONCAT(Option1Desc1, ', ', Option1Desc2, ', ', Option1DescA)
                WHEN Option1Desc1 IS NOT NULL AND Option1DescA IS NOT NULL THEN CONCAT(Option1Desc1, ', ', Option1DescA)
                WHEN Option1Desc1 IS NOT NULL AND Option1Desc2 IS NOT NULL THEN CONCAT(Option1Desc1, ', ', Option1Desc2)
                WHEN Option1Desc2 IS NOT NULL AND Option1DescA IS NOT NULL THEN CONCAT(Option1Desc2, ', ', Option1DescA)
                WHEN Option1Desc1 IS NOT NULL THEN Option1Desc1
                WHEN Option1Desc2 IS NOT NULL THEN Option1Desc2
                WHEN Option1DescA IS NOT NULL THEN Option1DescA
                ELSE ''
            END
        ) AS Option1Desc,
        V.ItemSize AS Variation,
        ISNULL(OD.DeletedItemQty, OD.ItemQty) AS ItemQty,
        OD.Rate,
        ISNULL(OD.DeletedAmount, OD.Amount) AS Amount,
		ISNULL(OD.Notes, '') AS Notes,
		OD.CreateDate, OM.JobRefNo
    FROM OrderDetail OD
	INNER JOIN OrderMaster OM on OM.Id = OD.OrderMasterId
    INNER JOIN Category C ON C.Id = OD.CategoryId
    INNER JOIN SubCategory SC ON SC.Id = OD.SubCategoryId
    INNER JOIN Item I ON I.Id = OD.ItemId
    INNER JOIN ItemVeriation V ON V.Id = OD.ItemVeriationId
    LEFT JOIN #TempOption1Desc O ON O.OrderDetailSelfId = OD.OrderDetailSelfId AND O.ItemId = OD.ItemId
    WHERE OD.OrderMasterId = @OrderMasterId and OD.isdeleted = 0 and OD.isactive = 1
    GROUP BY
        I.ItemDesc,
        I.ShortDesc,
        O.Option1Desc1,
        O.Option1Desc2,
        O.Option1DescA,
        V.ItemSize,
        OD.ItemQty,
        OD.Rate,
        OD.Amount,
		OD.DeletedItemQty,
		OD.DeletedAmount,
		OD.Notes,
		OD.CreateDate, 
		OM.JobRefNo;

    -- Drop the temporary table
    DROP TABLE #TempOption1Desc;
	
END

GO

-- Stored Procedure: [SP_GetOwnerDashboardAnalytics]
IF OBJECT_ID('[SP_GetOwnerDashboardAnalytics]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetOwnerDashboardAnalytics];
GO

CREATE Procedure [dbo].[SP_GetOwnerDashboardAnalytics]
    @FromDate Date, 
    @ToDate Date, 
    @RestaurantId int = 1
As
Begin
    SET NOCOUNT ON;
    SET ARITHABORT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    -- Neutralize parameters
    DECLARE @StartDT DateTime = CAST(@FromDate AS DateTime);
    DECLARE @EndDT DateTime = DATEADD(SECOND, -1, CAST(DATEADD(DAY, 1, @ToDate) AS DateTime));
    DECLARE @Rid int = @RestaurantId;

    ---------------------------------------------------------
    -- 🔥 STEP 1: CACHE ORDERS & JOIN WITH NEWRATE
    ---------------------------------------------------------
    SELECT 
        OM.Id,
        OM.OrderStatusId,
        OM.CreatedBy,
        OM.TableId,
        OM.BankName as OMBankName, -- Aliasing to avoid confusion
        OM.OrderDate,
        OM.PaymentId,
        OM.OrderTypeId,
        SUM(ISNULL(OD.ItemQty, 0) * ISNULL(IR.NewRate, 0)) as TotalAmount_NewRate,
        MAX(ISNULL(OM.OrderDiscount, 0)) as OrderDiscount, 
        MAX(ISNULL(OM.TaxAmount, 0)) as OrderTax
    INTO #Orders
    FROM OrderMaster OM WITH (NOLOCK)
    JOIN OrderDetail OD WITH (NOLOCK) ON OM.Id = OD.OrderMasterId
    LEFT JOIN ItemRate IR WITH (NOLOCK) ON OD.ItemId = IR.ItemId
    WHERE OM.OrderDate BETWEEN @StartDT AND @EndDT
      AND (@Rid IS NULL OR OM.ResturantId = @Rid)
      -- AND OM.IsActive = 1
      -- AND OM.IsDeleted = 0
    GROUP BY OM.Id, OM.OrderStatusId, OM.CreatedBy, OM.TableId, OM.BankName, OM.OrderDate, OM.PaymentId, OM.OrderTypeId;

    ---------------------------------------------------------
    -- 1. SUMMARY METRICS
    ---------------------------------------------------------
    SELECT 
        (SELECT TOP 1 RestaurantName FROM Restaurant WHERE (@Rid IS NULL OR Id = @Rid)) AS RestaurantName,
        ISNULL(SUM(TotalAmount_NewRate), 0) AS TotalRevenue,
        COUNT(DISTINCT Id) AS TotalOrders,
        ISNULL(SUM(OrderDiscount), 0) AS TotalDiscount,
        ISNULL(SUM(OrderTax), 0) AS TotalTax,
        CASE WHEN COUNT(DISTINCT Id) > 0 THEN ISNULL(SUM(TotalAmount_NewRate), 0) / COUNT(DISTINCT Id) ELSE 0 END AS AvgOrderValue,
        ISNULL(SUM(CASE WHEN OrderStatusId = 5 THEN TotalAmount_NewRate ELSE 0 END), 0) AS CancellationLoss,
        COUNT(DISTINCT CASE WHEN OrderStatusId = 5 THEN Id END) AS TotalCancelled,
        0 AS LaborCost 
    FROM #Orders;

    ---------------------------------------------------------
    -- 2. ORDER TYPE DISTRIBUTION
    ---------------------------------------------------------
    SELECT 
        ISNULL(OT.OrderType, 'Other') AS OrderType,
        COUNT(DISTINCT O.Id) AS OrderCount
    FROM #Orders O
    LEFT JOIN OrderType OT WITH (NOLOCK) ON O.OrderTypeId = OT.OrderTypeId
    WHERE OT.IsActive = '1' OR OT.IsActive IS NULL
    GROUP BY OT.OrderType;

    ---------------------------------------------------------
    -- 3. TOP 5 PRODUCTS BY NEWRATE REVENUE
    ---------------------------------------------------------
    SELECT TOP 5 
        I.ItemDesc,
        SUM(OD.ItemQty) AS TotalQty,
        SUM(ISNULL(OD.ItemQty, 0) * ISNULL(IR.NewRate, 0)) AS TotalAmount
    FROM OrderDetail OD WITH (NOLOCK)
    JOIN #Orders O ON OD.OrderMasterId = O.Id
    JOIN Item I WITH (NOLOCK) ON OD.ItemId = I.Id
    LEFT JOIN ItemRate IR WITH (NOLOCK) ON OD.ItemId = IR.ItemId
    GROUP BY I.ItemDesc
    ORDER BY TotalAmount DESC;

    ---------------------------------------------------------
    -- 4. STAFF PERFORMANCE (TOP 5)
    ---------------------------------------------------------
    SELECT TOP 5 
        ISNULL(W.Fname, 'Unknown Staff') AS WaiterName,
        COUNT(DISTINCT O.Id) AS OrdersHandled,
        SUM(ISNULL(O.TotalAmount_NewRate, 0)) AS TotalSalesValue
    FROM #Orders O
    LEFT JOIN userDetail W WITH (NOLOCK) ON O.CreatedBy = W.Id
    GROUP BY W.Fname
    ORDER BY TotalSalesValue DESC;

    ---------------------------------------------------------
    -- 5. TOP BANK USAGE (TOP 5) - Anchored on OrderMaster
    ---------------------------------------------------------
    -- Using #Orders as base to ensure counts match Total Orders.
    -- LEFT JOIN FlightDetails to get refined Bank info if it exists.
    SELECT TOP 5 
        ISNULL(B.BankName, 'Cash/Other') AS PaymentMode,
        COUNT(DISTINCT F.Id) AS Amount
    FROM FlightDetails F
    -- LEFT JOIN FlightDetails F WITH (NOLOCK) ON O.Id = F.OrderId
    LEFT JOIN Bank B WITH (NOLOCK) ON F.BankId = B.Id
	WHERE F.CreatedDate BETWEEN @StartDT AND @EndDT
    GROUP BY ISNULL(B.BankName, 'Cash/Other')
    ORDER BY Amount DESC;

    ---------------------------------------------------------
    -- 6. TABLE CENSUS (DINE-IN ONLY)
    ---------------------------------------------------------

	;WITH UniqueTablesUsed AS (
		SELECT DISTINCT O.TableId 
		FROM #Orders O
		WHERE O.TableId IS NOT NULL
	)
	SELECT 
		COUNT(U.TableId) AS IsOccupied,
		COUNT(TN.Id) AS Count
	FROM TablesNos TN WITH (NOLOCK)
	LEFT JOIN UniqueTablesUsed U 
		ON TN.Id = U.TableId;

    ---------------------------------------------------------
    -- 7. PEAK LOAD PATTERN (HOURLY)
    ---------------------------------------------------------
    SELECT 
        FORMAT(OrderDate, 'HH:00') AS Label,
        SUM(TotalAmount_NewRate) AS Value
    FROM #Orders
    GROUP BY FORMAT(OrderDate, 'HH:00')
    ORDER BY Label;

    ---------------------------------------------------------
    -- 8. DAILY REVENUE TREND
    ---------------------------------------------------------
    SELECT 
        FORMAT(OrderDate, 'yyyy-MM-dd') AS Label,
        SUM(TotalAmount_NewRate) AS Value
    FROM #Orders
    GROUP BY FORMAT(OrderDate, 'yyyy-MM-dd')
    ORDER BY Label;

    ---------------------------------------------------------
    -- 9. YEARLY TREND (Placeholder for compatibility)
    ---------------------------------------------------------
    SELECT '' AS Label, 0 AS Value WHERE 1=0;

    ---------------------------------------------------------
    -- 10. CARD TYPE USAGE - Anchored on OrderMaster
    ---------------------------------------------------------
    SELECT TOP 5 
        ISNULL(BB.CardType, 'Regular/Cash') AS Label,
        COUNT(DISTINCT F.BinNo) AS Value
    FROM FlightDetails F
    -- LEFT JOIN FlightDetails F WITH (NOLOCK) ON O.Id = F.OrderId
    LEFT JOIN BankBin BB WITH (NOLOCK) ON F.BinNo = BB.BinNo AND F.BankId = BB.BankId
	WHERE F.CreatedDate BETWEEN @StartDT AND @EndDT
    GROUP BY ISNULL(BB.CardType, 'Regular/Cash')
    ORDER BY Value DESC;

    DROP TABLE #Orders;
END

GO

-- Stored Procedure: [SP_GetPrinterFromCategory]
IF OBJECT_ID('[SP_GetPrinterFromCategory]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetPrinterFromCategory];
GO


CREATE Procedure [dbo].[SP_GetPrinterFromCategory]
@CategoryId int
As
Begin
Declare @cnt AS INT
SET @cnt = (SELECT COUNT(Id) from Config where ConfigName = 'PrintCategory' and ConfigValue = 'Yes')

IF @cnt = 1
	BEGIN
	Select C.Id,C.ResturantId,C.CategoryDesc,C.ShortDesc,C.SortOrder,C.ImageUrl,C.CreatedBy,C.CreateDate,C.IsActive,C.IsDeleted,
	PC.Id, PC.PrinterName, PC.PrinterIP
	from Category C
	Inner Join PrinterCategory PC ON C.Id = PC.CategoryId
	Where C.IsActive = 1 And C.IsDeleted = 0 and PC.IsActive = 1 And C.Id = @CategoryId
	Group By C.Id,C.ResturantId,C.CategoryDesc,C.ShortDesc,C.SortOrder,C.ImageUrl,C.CreatedBy,C.CreateDate,C.IsActive,C.IsDeleted,
	PC.Id, PC.PrinterName, PC.PrinterIP
	END





End



GO

