CREATE Procedure [dbo].[SP_GetPurchases]
As
Begin
Select PM.*,CONVERT(varchar, PM.CreatedDate,23) strCreatedDate,CONVERT(varchar, PM.PurchaseDate,23) strPurchaseDate,L.UserName,SI.FirstName SupplierName
,Case When PM.PaymentType = 1 Then 'Cash' Else 'Credit' End PaymentDesc
from PurchasesMaster PM
Inner Join login L ON L.UserId = PM.Createdby 
Inner Join SupplierInfo SI ON SI.ID = PM.SupplierInfoId
Select PD.*, UOM.UnitType,RM.MaterialDesc from purchasesDetails PD
Inner Join UOM ON UOM.ID =  PD.UOMId
Inner Join RawMaterial RM ON RM.ID = PD.RawMaterialId
End

GO

