CREATE Procedure [dbo].[SP_GetPurchases_ByID]
@PurchaseID int
As
Begin
	Select PM.*,CONVERT(varchar, PM.CreatedDate,23) strCreatedDate,CONVERT(varchar, PM.PurchaseDate,23) strPurchaseDate,L.UserName,SI.FirstName SupplierName from PurchasesMaster PM
Inner Join login L ON L.UserId = PM.Createdby 
Inner Join SupplierInfo SI ON SI.ID = PM.SupplierInfoId Where PM.Id = @PurchaseID
