CREATE PROCEDURE [dbo].[SP_GetRatingDetails]   
 @orderid as int  
AS  
BEGIN  
 SELECT 'Food' AS Category,   
 Case When Rating IS NULL Then 0 Else Rating End Rating  
    
   
   
FROM customerfeedback  
WHERE orderid = @orderid  
  
UNION ALL  
  
SELECT 'Service' AS Category,   
  
Case When ServiceRating IS NULL Then 0 Else ServiceRating End Rating  
FROM customerfeedback  
WHERE orderid = @orderid  
  
UNION ALL  
  
SELECT 'Ambiance' AS Category,   
  
Case When AmbianceRating IS NULL Then 0 Else AmbianceRating End Rating  
FROM customerfeedback  
WHERE orderid = @orderid  
  
END  

