  CREATE Procedure [dbo].[SP_GetRawMaterial]          
  @MaterialDesc varchar(100)        
AS            
Begin            
        
   Select RM.ID, RM.MaterialDesc,RM.IsActive,RM.IsDeleted,RM.Createdby,CONVERT(varchar, RM.CreatedDate,23) CreatedDate,
   Case When IsActive = 1 Then 'Active' Else 'InActive' End Status, RM.PurchasingUOM, RM.ConsumptionUOM   
   From RawMaterial   RM        
 Where (RM.IsDeleted IS NULL OR RM.IsDeleted = 0)  AnD IsActive = 1         
      
And (RM.MaterialDesc Like '%' +  @MaterialDesc  +'%' OR(@MaterialDesc ='' OR @MaterialDesc IS NULL))        
End

