-- Stored Procedure: [SP_GetTables_SM]
IF OBJECT_ID('[SP_GetTables_SM]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetTables_SM];
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GetTables_SM]

AS
BEGIN
	SELECT tn.*, (tn.Persons - f.noofmeals) SeatsRemaining
	FROM TablesNos tn
	LEFT JOIN FlightDetails f ON f.TableNo = tn.TableNo AND (f.OrderId = 0 OR f.OrderId IS NULL)
	WHERE tn.IsActive = 1
	AND NOT EXISTS (
		SELECT 1
		FROM FlightDetails fd
		WHERE fd.TableNo = tn.TableNo
		AND (fd.OrderId = 0 OR fd.OrderId IS NULL) AND fd.noofmeals = tn.Persons
	)
END

GO

