-- Stored Procedure: [SP_GetTablesMealByWaiter]
IF OBJECT_ID('[SP_GetTablesMealByWaiter]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetTablesMealByWaiter];
GO
CREATE Procedure [dbo].[SP_GetTablesMealByWaiter]
@WaiterId	int,
@CurrentTimestamp	varchar(100)
AS
Begin
	IF @CurrentTimestamp = '0'
    BEGIN
        Select F.Id, F.WaiterId, F.TableId, F.TableNo, W.WaiterName, F.BankId, F.NoofMeals, C.Fname AS CustomerName, F.CreatedDate, F.OrderId
        from FlightDetails F 
        Inner Join Waiter W ON F.WaiterId = W.Id
		JOIN (
			SELECT FlightId, Fname, ROW_NUMBER() OVER (PARTITION BY FlightId ORDER BY CreateDate) AS RowNum
			FROM Customer
		) AS C ON C.FlightId = F.Id AND C.RowNum = 1
        Where W.IsActive = 1 
          And F.IsActive = 1 AND F.OrderId = 0
          And F.WaiterId = @WaiterId 
    END
    ELSE
    BEGIN
        Select F.Id, F.WaiterId, F.TableId, F.TableNo, W.WaiterName, F.BankId, F.NoofMeals, C.Fname AS CustomerName, F.CreatedDate, F.OrderId
        from FlightDetails F 
        Inner Join Waiter W ON F.WaiterId = W.Id
		JOIN (
			SELECT FlightId, Fname, ROW_NUMBER() OVER (PARTITION BY FlightId ORDER BY CreateDate) AS RowNum
			FROM Customer
		) AS C ON C.FlightId = F.Id AND C.RowNum = 1
        Where W.IsActive = 1 
          And F.IsActive = 1  AND F.OrderId = 0
          And F.WaiterId = @WaiterId 
          And F.CreatedDate > @CurrentTimestamp
    END

End

GO

-- Stored Procedure: [SP_GetTablesWithStatus]
IF OBJECT_ID('[SP_GetTablesWithStatus]', 'P') IS NOT NULL DROP PROCEDURE [SP_GetTablesWithStatus];
GO
CREATE PROCEDURE [dbo].[SP_GetTablesWithStatus]    
AS    
BEGIN    
    SET NOCOUNT ON;    
    
    ;WITH LatestOrderPerTable AS (    
        SELECT     
            o.TableId,    
            o.IsHold,    
            o.IsFinalPaid,    
            ROW_NUMBER() OVER (PARTITION BY o.TableId ORDER BY o.CreateDate DESC) AS rn    
        FROM OrderMaster o    
        WHERE     
            o.IsActive = 1 AND     
            o.IsDeleted = 0 AND     
            o.TableId IS NOT NULL    
    )    
    
    SELECT     
        t.Id,    
        t.TableNo,    
        CASE     
            WHEN lo.IsHold = 1 AND lo.IsFinalPaid = 0 THEN 1  -- Occupied    
            ELSE 0                                            -- Available    
        END AS IsOccupied    
    FROM TablesNos t    
    LEFT JOIN LatestOrderPerTable lo     
        ON lo.TableId = t.Id AND lo.rn = 1    
    WHERE t.IsActive = 1    
END    

GO

