-- Stored Procedure: [SP_InserCustomer]
IF OBJECT_ID('[SP_InserCustomer]', 'P') IS NOT NULL DROP PROCEDURE [SP_InserCustomer];
GO
CREATE Procedure [dbo].[SP_InserCustomer]    
@CustomerId				int,    
@RestaurantId			int,    
@Fname					varchar(50),    
@Email					varchar(50),    
@CustAddress			varchar(500),    
@TelephoneNo			varchar(50),    
@CountryId				int,    
@CityId					int,    
@DoorNo					varchar(50),    
@CustomerAddress		varchar(500),    
@CustomerAddress1		varchar(500),    
@CustomerLat			float,    
@CustomerLan			float,
@CustomerPassword		varchar(500),
@DeviceID				varchar(1000),
@CreatedBy				int,    
@NewCustomerId int OUTPUT    
As    
Begin Try    
  BEGIN TRANSACTION    
   if (@CustomerId = '' OR @CustomerId IS null)    
   Begin    
   --set @CustomerId   =  (SELECT ISNULL(MAX(ID),0)+1 FROM Customer)   
    --Select * from Customer
   Insert Into Customer (RestaurantId,Fname,Email,CustAddress,CustomerPassword,DeviceID,TelephoneNo,CreatedBy,CreateDate,IsActive,IsDeleted)    
       Values(@RestaurantId,@Fname,@Email,@CustAddress,@CustomerPassword,@DeviceID,@TelephoneNo,@CreatedBy,GETDATE(),1,0)    
    set @CustomerId   =  SCOPE_IDENTITY()    
   Insert Into CustomerDetail (CountryId,CityId,CustomerId,DoorNo,CustomerAddress,CustomerAddress1,CustomerLat,CustomerLan,CreatedBy,CreateDate,IsActive,IsDeleted)    
        Values(@CountryId,@CityId,@CustomerId,@DoorNo,@CustomerAddress,@CustomerAddress1,@CustomerLat,@CustomerLan,@CreatedBy,GETDATE(),1,0)    
       
   End    
   else    
   Begin    
    if Not Exists (Select Id from CustomerDetail Where CustomerLat = @CustomerLat And CustomerLan = @CustomerLan)    
    Begin    
     Insert Into CustomerDetail (CountryId,CityId,CustomerId,DoorNo,CustomerAddress,CustomerAddress1,CustomerLat,CustomerLan,CreatedBy,CreateDate,IsActive,IsDeleted)    
        Values(@CountryId,@CityId,@CustomerId,@DoorNo,@CustomerAddress,@CustomerAddress1,@CustomerLat,@CustomerLan,@CreatedBy,GETDATE(),1,0)    
    End    
   End    
   Select @NewCustomerId = @CustomerId    
  COMMIT TRANSACTION     
  END TRY      
 BEGIN CATCH     
 ROLLBACK TRANSACTION     
End CATCH 

GO

