CREATE Procedure [dbo].[SP_InsertBank]    
  @BankName varchar(100),  
  @BankAmount decimal(18,2),  
  @IsBank bit,  
  @IsActive bit,  
  @CreatedBy int,  
  @Msg varchar(100) OUT  
AS      
Begin      
	if Not EXists (Select * from Bank Where BankName = @BankName)  
		Begin  
			Insert Into Bank(BankName,IsActive,CreatedBy,CreatedDate, IsBank, BankAmount) 
			Values (@BankName,@IsActive,@CreatedBy,FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'), @IsBank, @BankAmount)  
			Set @Msg = 'Bank Add Successfully'  
		End  
	else  
		Begin  
			Set @Msg = 'Bank Already Exists'  
		End  
End  

GO

