-- Stored Procedure: [SP_InsertFlightDetails]
IF OBJECT_ID('[SP_InsertFlightDetails]', 'P') IS NOT NULL DROP PROCEDURE [SP_InsertFlightDetails];
GO
                                                                                                                                                                                                                                                             
CREATE PROCEDURE [dbo].[SP_InsertFlightDetails]   
                                                                                                                                                                                                           
@PaymentType     VARCHAR(50), 
                                                                                                                                                                                                                               
@BankId          INT,    
                                                                                                                                                                                                                                    
@BinNo           VARCHAR(50),    
                                                                                                                                                                                                                            
@FlightNo        VARCHAR(50),    
                                                                                                                                                                                                                            
@NoofMeals       INT,    
                                                                                                                                                                                                                                    
@TableId         INT,    
                                                                                                                                                                                                                                    
@TableNo         VARCHAR(50),    
                                                                                                                                                                                                                            
@PaymentBy       VARCHAR(50),    
                                                                                                                                                                                                                            
@ReceiptNo       VARCHAR(50),    
                                                                                                                                                                                                                            
@WaiterId        VARCHAR(50),      
                                                                                                                                                                                                                          
@CreatedBy       INT,   
                                                                                                                                                                                                                                     
@CreatedDate     DATETIME,   
                                                                                                                                                                                                                                
@Customers       NVARCHAR(MAX),
                                                                                                                                                                                                                              
@FTPayment       INT,
                                                                                                                                                                                                                                        
@Airline         VARCHAR(50),
                                                                                                                                                                                                                                
@CardProduct     VARCHAR(50),
                                                                                                                                                                                                                                
@PIN             VARCHAR(4),
                                                                                                                                                                                                                                 
@Children        INT,
                                                                                                                                                                                                                                        
@Banks           NVARCHAR(MAX),
                                                                                                                                                                                                                              
@NewCustomerId   INT OUTPUT    
                                                                                                                                                                                                                              
AS    
                                                                                                                                                                                                                                                       
BEGIN TRY    
                                                                                                                                                                                                                                                
  BEGIN TRANSACTION    
                                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 1: Early BIN/PIN Duplicate Check (Across DBs) for direct parameters
                                                                                                                                                                                
  ------------------------------------------------------
                                                                                                                                                                                                     
  IF EXISTS (
                                                                                                                                                                                                                                                
      SELECT 1
                                                                                                                                                                                                                                               
      FROM dbo.FlightDetails fd
                                                                                                                                                                                                                              
      WHERE fd.BinNo = @BinNo
                                                                                                                                                                                                                                
        AND fd.PIN = @PIN
                                                                                                                                                                                                                                    
        --AND fd.CreatedDate >= DATEADD(HOUR, -3, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'))
                                                                                                                                
		AND fd.CreatedDate = DATEADD(HOUR, 5, GETUTCDATE())
                                                                                                                                                                                                                             
  )
                                                                                                                                                                                                                                                          
  BEGIN
                                                                                                                                                                                                                                                      
      RAISERROR('Duplicate Entry found in Majestic within the last 3 hours.', 16, 1);
                                                                                                                                                                        
      RETURN;
                                                                                                                                                                                                                                                
  END
                                                                                                                                                                                                                                                        

                                                                                                                                                                                                                                                             
  --IF EXISTS (
                                                                                                                                                                                                                                              
  --    SELECT 1
                                                                                                                                                                                                                                             
  --    FROM rapiido_skymajestic.dbo.FlightDetails fd2
                                                                                                                                                                                                       
  --    WHERE fd2.BinNo = @BinNo
                                                                                                                                                                                                                             
  --      AND fd2.PIN = @PIN
                                                                                                                                                                                                                                 
  --      AND fd2.CreatedDate >= DATEADD(HOUR, -3, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'))
                                                                                                                               
  --)
                                                                                                                                                                                                                                                        
  --BEGIN
                                                                                                                                                                                                                                                    
  --    RAISERROR('Duplicate Entry found in Sky Majestic within the last 3 hours.', 16, 1);
                                                                                                                                                                  
  --    RETURN;
                                                                                                                                                                                                                                              
  --END
                                                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 2: Parse @Banks JSON and check for duplicates
                                                                                                                                                                                                      
  ------------------------------------------------------
                                                                                                                                                                                                     
  DECLARE @CustomerBankTable TABLE (    
                                                                                                                                                                                                                     
      PassengerName VARCHAR(100),   
                                                                                                                                                                                                                         
      BankId        INT,
                                                                                                                                                                                                                                     
      BankName      VARCHAR(100),
                                                                                                                                                                                                                            
      CardProduct   VARCHAR(50),
                                                                                                                                                                                                                             
      BinNo         VARCHAR(50),
                                                                                                                                                                                                                             
      PIN           VARCHAR(4),
                                                                                                                                                                                                                              
      Meals         INT,
                                                                                                                                                                                                                                     
      FlightId      INT
                                                                                                                                                                                                                                      
  )
                                                                                                                                                                                                                                                          

                                                                                                                                                                                                                                                             
  IF (@Banks IS NOT NULL AND @Banks != 'NULL')
                                                                                                                                                                                                               
  BEGIN
                                                                                                                                                                                                                                                      
      INSERT INTO @CustomerBankTable    
                                                                                                                                                                                                                     
      SELECT * FROM OPENJSON(@Banks) WITH (      
                                                                                                                                                                                                            
          PassengerName VARCHAR(100),   
                                                                                                                                                                                                                     
          BankId        INT,
                                                                                                                                                                                                                                 
          BankName      VARCHAR(100),
                                                                                                                                                                                                                        
          CardProduct   VARCHAR(50),
                                                                                                                                                                                                                         
          BinNo         VARCHAR(50),
                                                                                                                                                                                                                         
          PIN           VARCHAR(4),
                                                                                                                                                                                                                          
          Meals         INT,
                                                                                                                                                                                                                                 
          FlightId      INT
                                                                                                                                                                                                                                  
      )
                                                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
      -- Check for duplicate BIN + PIN in current and secondary databases for each record in @CustomerBankTable
                                                                                                                                              
      IF EXISTS (
                                                                                                                                                                                                                                            
          SELECT 1
                                                                                                                                                                                                                                           
          FROM @CustomerBankTable cb
                                                                                                                                                                                                                         
          WHERE EXISTS (
                                                                                                                                                                                                                                     
              SELECT 1 
                                                                                                                                                                                                                                      
              FROM dbo.FlightDetails fd
                                                                                                                                                                                                                      
              WHERE fd.BinNo = cb.BinNo
                                                                                                                                                                                                                      
                AND fd.PIN = cb.PIN
                                                                                                                                                                                                                          
                --AND fd.CreatedDate >= DATEADD(HOUR, -3, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'))
                                                                                                                        
				AND fd.CreatedDate = DATEADD(HOUR, 5, GETUTCDATE())
                                                                                                                                                                                                                           
          )
                                                                                                                                                                                                                                                  
          --OR EXISTS (
                                                                                                                                                                                                                                      
          --    SELECT 1 
                                                                                                                                                                                                                                    
          --    FROM rapiido_skymajestic.dbo.FlightDetails fd2
                                                                                                                                                                                               
          --    WHERE fd2.BinNo = cb.BinNo
                                                                                                                                                                                                                   
          --      AND fd2.PIN = cb.PIN
                                                                                                                                                                                                                       
          --      AND fd2.CreatedDate >= DATEADD(HOUR, -3, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'))
                                                                                                                       
          --)
                                                                                                                                                                                                                                                
      )
                                                                                                                                                                                                                                                      
      BEGIN
                                                                                                                                                                                                                                                  
          RAISERROR('Duplicate Entry found within the last 3 hours (from @Banks).', 16, 1);
                                                                                                                                                                  
          RETURN;
                                                                                                                                                                                                                                            
      END
                                                                                                                                                                                                                                                    
  END
                                                                                                                                                                                                                                                        

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 3: Normalize PaymentBy Based on PaymentType
                                                                                                                                                                                                        
  ------------------------------------------------------
                                                                                                                                                                                                     
  IF @PaymentType = 'AIRLINE' 
                                                                                                                                                                                                                               
      SET @PaymentBy = 'CASH'
                                                                                                                                                                                                                                
  ELSE IF @PaymentType = 'CARD' 
                                                                                                                                                                                                                             
      SET @PaymentBy = 'CARD'
                                                                                                                                                                                                                                
  ELSE 
                                                                                                                                                                                                                                                      
      SET @PaymentBy = @PaymentBy
                                                                                                                                                                                                                            

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 4: Insert FlightDetails
                                                                                                                                                                                                                            
  ------------------------------------------------------
                                                                                                                                                                                                     
  INSERT INTO FlightDetails (
                                                                                                                                                                                                                                
      BankId, BinNo, FlightNo, NoofMeals, TableId, TableNo, PaymentBy, ReceiptNo,
                                                                                                                                                                            
      WaiterId, CreatedBy, CreatedDate, IsActive, PaymentType, FTPayment,
                                                                                                                                                                                    
      Airline, CardProduct, PIN, Children, IsChange
                                                                                                                                                                                                          
  )    
                                                                                                                                                                                                                                                      
  VALUES (
                                                                                                                                                                                                                                                   
      @BankId, @BinNo, @FlightNo, @NoofMeals, @TableId, @TableNo, @PaymentBy, @ReceiptNo,
                                                                                                                                                                    
      @WaiterId, @CreatedBy, DATEADD(HOUR, 5, GETUTCDATE()),
                                                                                                                                                                                                                      
	  --@WaiterId, @CreatedBy, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'),
                                                                                                                                                      
      1, @PaymentType, @FTPayment, @Airline, @CardProduct, @PIN, @Children, 1
                                                                                                                                                                                
  )    
                                                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
  SET @NewCustomerId = SCOPE_IDENTITY()
                                                                                                                                                                                                                      

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 5: Generate SlipCode
                                                                                                                                                                                                                               
  ------------------------------------------------------
                                                                                                                                                                                                     
  DECLARE @ResturantShortName VARCHAR(100)
                                                                                                                                                                                                                   
  DECLARE @SlipCode VARCHAR(100)
                                                                                                                                                                                                                             

                                                                                                                                                                                                                                                             
  SELECT @ResturantShortName = RestaurantShortName FROM Restaurant  
                                                                                                                                                                                         

                                                                                                                                                                                                                                                             
  SELECT @SlipCode = @ResturantShortName + '-F-' + RIGHT('000000' + CAST(@NewCustomerId AS VARCHAR(7)), 7)  
                                                                                                                                                 

                                                                                                                                                                                                                                                             
  UPDATE FlightDetails  
                                                                                                                                                                                                                                     
  SET SlipCode = @SlipCode
                                                                                                                                                                                                                                   
  WHERE Id = @NewCustomerId  
                                                                                                                                                                                                                                

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 6: Insert Customers
                                                                                                                                                                                                                                
  ------------------------------------------------------
                                                                                                                                                                                                     
  IF (@Customers IS NOT NULL AND @Customers != 'NULL')    
                                                                                                                                                                                                   
  BEGIN    
                                                                                                                                                                                                                                                  
      DECLARE @CustomerTable TABLE (    
                                                                                                                                                                                                                     
          Fname VARCHAR(50),   
                                                                                                                                                                                                                              
          TelephoneNo VARCHAR(50),
                                                                                                                                                                                                                           
          FlightId INT,
                                                                                                                                                                                                                                      
          CreatedBy INT,
                                                                                                                                                                                                                                     
          CreateDate DATETIME,
                                                                                                                                                                                                                               
          IsActive BIT,
                                                                                                                                                                                                                                      
          IsDeleted BIT
                                                                                                                                                                                                                                      
      )    
                                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
      INSERT INTO @CustomerTable    
                                                                                                                                                                                                                         
      SELECT * FROM OPENJSON(@Customers) WITH (      
                                                                                                                                                                                                        
          Fname VARCHAR(50),   
                                                                                                                                                                                                                              
          TelephoneNo VARCHAR(50),
                                                                                                                                                                                                                           
          FlightId INT,
                                                                                                                                                                                                                                      
          CreatedBy INT,
                                                                                                                                                                                                                                     
          CreateDate DATETIME,
                                                                                                                                                                                                                               
          IsActive BIT,
                                                                                                                                                                                                                                      
          IsDeleted BIT
                                                                                                                                                                                                                                      
      )    
                                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
      UPDATE @CustomerTable 
                                                                                                                                                                                                                                 
      SET FlightId = @NewCustomerId, 
                                                                                                                                                                                                                        
          CreatedBy = @CreatedBy, 
                                                                                                                                                                                                                           
          --CreateDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss')
                                                                                                                                                          
		  CreateDate = DATEADD(HOUR, 5, GETUTCDATE())
                                                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
      INSERT INTO Customer (Fname, TelephoneNo, FlightId, CreatedBy, CreateDate, IsActive, IsDeleted)   
                                                                                                                                                     
      SELECT Fname, TelephoneNo, FlightId, CreatedBy, CreateDate, IsActive, IsDeleted FROM @CustomerTable     
                                                                                                                                               
  END    
                                                                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 7: Insert Banks (CustomerBankTable reused)
                                                                                                                                                                                                         
  ------------------------------------------------------
                                                                                                                                                                                                     
  IF (@Banks IS NOT NULL AND @Banks != 'NULL')    
                                                                                                                                                                                                           
  BEGIN    
                                                                                                                                                                                                                                                  
      UPDATE @CustomerBankTable 
                                                                                                                                                                                                                             
      SET FlightId = @NewCustomerId      
                                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
      INSERT INTO FlightCustomerBanks (
                                                                                                                                                                                                                      
          PassengerName, BankId, BankName, CardProduct, BinNo, PIN, Meals, FlightId, IsActive, CreatedDate
                                                                                                                                                   
      )
                                                                                                                                                                                                                                                      
      SELECT 
                                                                                                                                                                                                                                                
          PassengerName, BankId, BankName, CardProduct, BinNo, PIN, Meals, FlightId,
                                                                                                                                                                         
          1, DATEADD(HOUR, 5, GETUTCDATE())
                                                                                                                                                                                                                                       
		  --FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss') 
                                                                                                                                                                            
      FROM @CustomerBankTable     
                                                                                                                                                                                                                           
  END    
                                                                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
  ------------------------------------------------------
                                                                                                                                                                                                     
  -- STEP 8: Commit
                                                                                                                                                                                                                                          
  ------------------------------------------------------
                                                                                                                                                                                                     
  COMMIT TRANSACTION     
                                                                                                                                                                                                                                    
END TRY      
                                                                                                                                                                                                                                                
BEGIN CATCH     
                                                                                                                                                                                                                                             
  ROLLBACK TRANSACTION     
                                                                                                                                                                                                                                  
  -- Optionally return error or re-raise
                                                                                                                                                                                                                     
  DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
                                                                                                                                                                                                    
  RAISERROR(@ErrorMessage, 16, 1);
                                                                                                                                                                                                                           
END CATCH
                                                                                                                                                                                                                                                    

GO

-- Stored Procedure: [SP_InsertProduct]
IF OBJECT_ID('[SP_InsertProduct]', 'P') IS NOT NULL DROP PROCEDURE [SP_InsertProduct];
GO
    
    
CREATE Procedure [dbo].[SP_InsertProduct]    
@SubCategoryId  int,    
@ItemDesc   varchar(500),    
@ShortDesc   varchar(5000),    
@SortOrder   int,    
@ImageURL   nvarchar(Max),    
@CreatedBy   int,    
@IsActive   bit,    
@ItemVeriationId int,    
@Rate    Decimal(18,2),    
@ItemId    int Output    
AS    
Begin Try        
  BEGIN TRANSACTION      
  IF Not Exists (Select ItemDesc From Item Where SubCategoryId = @SubCategoryId And ItemDesc =@ItemDesc)  
  Begin  
 Insert Into Item (SubCategoryId,ItemDesc,ShortDesc,SortOrder,ImageURL,CreatedBy,CreateDate,IsActive,IsDeleted)    
    Values(@SubCategoryId,@ItemDesc,@ShortDesc,@SortOrder,@ImageURL,@CreatedBy,GETDATE(),@IsActive,0)    
    --DEclare @ItemId int    
    set @ItemId   =  SCOPE_IDENTITY()     
    Insert Into ItemRate(ItemId,ItemVeriationId,Rate,CreatedBy,CreateDate,IsActive,IsDeleted)    
     Values(@ItemId,@ItemVeriationId,@Rate,@CreatedBy,GETDATE(),@IsActive,0)    
  End  
  Else  
  Begin  
   Select @ItemId = Id From Item Where SubCategoryId = @SubCategoryId And ItemDesc =@ItemDesc  
  
    Insert Into ItemRate(ItemId,ItemVeriationId,Rate,CreatedBy,CreateDate,IsActive,IsDeleted)    
     Values(@ItemId,@ItemVeriationId,@Rate,@CreatedBy,GETDATE(),@IsActive,0)    
  End  
     Select @ItemId    
  COMMIT TRANSACTION         
  END TRY          
 BEGIN CATCH         
 ROLLBACK TRANSACTION         
End CATCH 

GO

