CREATE Procedure [dbo].[SP_InsertPurchases]
@SupplierInfoId			int,
@PaymentType			varchar(100),
@InvoiceNumber			varchar(500),
@PurchaseDate			datetime,
@CreatedBy				int,
@IsActive				bit,
@JsonPurchaseDetails	varchar(Max),
@Msg					varchar(100) Out
AS
BEGIN TRY            
    BEGIN TRANSACTION  
		DEclare @PurchasesId int 

			Insert into PurchasesMaster(SupplierInfoId,PaymentType,InvoiceNumber,PurchaseDate,CreatedDate,CreatedBy,IsDeleted,IsActive)
									Values (@SupplierInfoId,@PaymentType,@InvoiceNumber,@PurchaseDate,GETDATE(),@CreatedBy,0,@IsActive)
		set @PurchasesId   =  SCOPE_IDENTITY(); 
		Declare @JsonPurchaseDetailsTable  Table(
			PurchasesId	int,
			UOMId	int,
			RawMaterialId bit,
			SizeDesc decimal(18,2),
			QtyDesc decimal(18,2),
			Rate decimal(18,2),
			Amount decimal(18,2),
			CreatedDate	datetime,
			CreatedBy int,
			IsDeleted bit,
			IsActive bit
			
			)
			
			Insert Into @JsonPurchaseDetailsTable
		Select * from OpenJson(@JsonPurchaseDetails)
			With (PurchasesId	int,
			UOMId	int,
			RawMaterialId bit,
			SizeDesc decimal(18,2),
			QtyDesc decimal(18,2),
			Rate decimal(18,2),
			Amount decimal(18,2),
			CreatedDate	datetime,
			CreatedBy int,
			IsDeleted bit,
			IsActive bit
			)

			Update @JsonPurchaseDetailsTable Set PurchasesId =@PurchasesId, CreatedDate =GETDATE(),CreatedBy = @CreatedBy ,IsDeleted = 0 ,IsActive = 1

			Insert into purchasesDetails
			Select * from @JsonPurchaseDetailsTable
			set @Msg ='Invoice Add Successfully'
COMMIT TRANSACTION            
END TRY            
BEGIN CATCH            
          
 ROLLBACK TRANSACTION          
 Set @Msg = ERROR_MESSAGE()      
End CATCH 

GO

