CREATE Procedure [dbo].[SP_InsertWebUserDetail]
@Fname		varchar(100),
@UserName	varchar(100),
@UserPassword	varchar(100),
@MobileNo			varchar(100),
@Address	varchar(Max),
@ISBackOffice	bit,
@WebUserStatus	bit,
@CreatedBy	int,
@Msg	varchar(100) Out
AS
Begin
		If Not Exists(Select l.* from login l join UserDetail u on u.id = l.UserId Where UserName = @UserName And u.IsActive = 1)	
		Begin
			DECLARE @NewUserId INT;

			Insert into UserDetail (Fname, Address, MobileNo, CreatedBy, CreateDate, IsActive)
			Values(@Fname, @Address, @MobileNo, @CreatedBy, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'), @WebUserStatus)

			SET @NewUserId = SCOPE_IDENTITY();

			Insert Into login(ResturantId,UserId,UserName,UserPassword,ISBackOffice)
						Values(1,@NewUserId,@UserName,@UserPassword,@ISBackOffice)
						Set @Msg ='User Added Successfully'
		End
		Else
		Begin
				Set @Msg ='User Already Exists'
		End
End

GO

