CREATE Procedure [dbo].[SP_Item]  
@SubCategoryId int  
AS  
Begin  
--Select * from Item Where IsActive = 1 And IsDeleted = 0 And SubCategoryId = @SubCategoryId  
--Order By SortOrder  
   Select I.Id ItemId,I.SubCategoryId,I.ItemDesc,I.ShortDesc,I.SortOrder,I.ImageURL 
,IR.Rate,IR.Id RateId,IR.ItemVeriationId
,IV.ItemSize
from Item I
Inner Join ItemRate IR On I.Id = IR.ItemId
Inner Join ItemVeriation IV ON IR.ItemVeriationId = IV.Id
Where I.IsActive = 1 And I.IsDeleted = 0 And I.SubCategoryId = @SubCategoryId 
And defaultVeriation = 1

Order By SortOrder  
End

