CREATE Procedure [dbo].[SP_OrderDetailByCustomerId]
@OrderMasterId		int
As
Begin
Select OD.Id OrderDetailId,OD.CategoryId,C.CategoryDesc,OD.SubCategoryId,SC.SubCategiryDesc,OD.ItemId,I.ItemDesc,I.ImageURL,OD.ItemVeriationId,V.ItemSize,OD.ItemQty,OD.Rate from OrderDetail OD  
Inner Join Category C On C.Id = OD.CategoryId  
Inner Join SubCategory SC On SC.Id = OD.SubCategoryId  
Inner Join Item I On I.Id = OD.ItemId  
Inner Join ItemVeriation V On V.Id = OD.ItemVeriationId  
Where OD.OrderMasterId  = @OrderMasterId
End

GO

-- Stored Procedure: [SP_OrderforWaiter]
IF OBJECT_ID('[SP_OrderforWaiter]', 'P') IS NOT NULL DROP PROCEDURE [SP_OrderforWaiter];
GO


  
CREATE Procedure [dbo].[SP_OrderforWaiter]  
@OrderId int  
AS  
Begin  
 Select TableId,TableNo Tablenumber,Id OrderID,JobRefNo OrderNumber, ISNULL(DeletedOrderAmount, OrderAmount) TotalOrderAmount, PaymentType, BankId, BankName, DiscountPer, CardType, BankDiscountId, CustomerName, OrderUniqueId  from OrderMaster Where Id = @OrderId  
  
 Select OD.Id OrderDetailID, OD.CategoryId catID, OD.SubCategoryId subCatID,OD.ItemId productID,OD.ItemVeriationId itemVariantID,OD.ItemRateId priceID, ISNULL(OD.DeletedItemQty, OD.ItemQty) quantity,OD.Rate price,  
 I.ItemDesc productName, I.ShortDesc, OD.OrderDetailSelfId, ISNULL(OD.Notes, '') Notes, V.ItemSize AS Variation  
 From OrderDetail OD   
 left Join Item I ON OD.ItemId = I.Id   
 LEFT JOIN ItemVeriation V ON V.Id = OD.ItemVeriationId  
 Where OrderMasterId = @OrderId and OD.IsDeleted = 0  
 Order by OD.Id  
  
 --Select OA.AddonId addonId, A.Rate,A.AddonsDesc,OA.ItemId, OA.OrderDetailSelfId from OrderDetailAddOns OA  
 --join OrderDetail op  on OA.OrderDetailSelfId =op.OrderDetailSelfId  
 --Inner Join Addons A ON OA.AddonId = A.Id WHERE OA.OrderId = @OrderId  
  
 Select OA.AddonId addonId, A.Rate,A.Option1Desc AddonsDesc,OA.ItemId, OA.OrderDetailSelfId from OrderDetailAddOns OA  
 join OrderDetail op  on OA.OrderDetailSelfId =op.OrderDetailSelfId  
 Inner Join Options1 A ON OA.AddonId  = A.Id Where OA.OrderId =@OrderId and op.IsDeleted = 0  
  
 Select O1.Option1Id,O.Rate,O.Option1Desc,O1.ItemId, O1.OrderDetailSelfId from OrderDetailOption1 O1  
 join OrderDetail op  on O1.OrderDetailSelfId =op.OrderDetailSelfId  
 Inner Join Options1 O ON O1.Option1Id  = O.Id Where O1.OrderId =@OrderId and op.IsDeleted = 0  
  
 Select O1.Option2Id,O.Rate,O.Option1Desc,O1.ItemId, O1.OrderDetailSelfId from OrderDetailOption2 O1  
 join OrderDetail op  on O1.OrderDetailSelfId =op.OrderDetailSelfId  
 Inner Join Options1 O ON O1.Option2Id  = O.Id Where O1.OrderId =@OrderId and op.IsDeleted = 0  
End  
  
  

GO

