CREATE Procedure [dbo].[SP_OrderMasterListByCustomerId]  
@CustomerID  int  
As  
Begin  
Select OM.Id OrderID, OM.CustomerId,OM.ResturantId,OM.PaymentId,OM.PicupLocation,OM.PickupLat,OM.PickupLan,OM.DestinationLocation,OM.DestinationLat,OM.DestinationLan,  
OM.OrderAmount,OM.OrderDiscount,OM.OrderDiscountPer,OM.OrderNetAmount,OM.OrderDate,OM.IsActive,  
DD.Id DriverId,DD.DriverName,DS.Id DriverStatusId,DS.DriverStatusDesc,BS.Id BookingstatusID,BS.BookingStatusDesc  
from OrderMaster OM   
Left Join DriverDetail DD On OM.DriverId = DD.Id  
Left Join BookingStatus BS ON OM.OrderStatusId = BS.Id  
Left Join DriverStatus DS On OM. DriverStatusId = Ds.Id  
Where CustomerId = @CustomerID  
  
End

