-- Stored Procedure: [SP_OrderPaymentUpdate]
IF OBJECT_ID('[SP_OrderPaymentUpdate]', 'P') IS NOT NULL DROP PROCEDURE [SP_OrderPaymentUpdate];
GO



CREATE Procedure [dbo].[SP_OrderPaymentUpdate]        
@OrderMstID  bigint,      
@PaymentStatusID int=0,  
@OrderNetAmount  decimal=0,
@PaidAmount   decimal=0,
@TipsAmount  decimal=0,      
@TransactionID nvarchar(100)=null,      
@TransactionStatus   varchar(50)=null,
@TransactionResult  nvarchar(1000)=null,      
@PaymentDatetime datetime=null,      
@PaymentGateway   varchar(50)=null

As        
Begin      
declare @status varchar(max)
declare @balanceAmount bit=0

select @balanceAmount=case when (@OrderNetAmount=@PaidAmount) or (@PaidAmount>@OrderNetAmount) then  1 else 0 end
  begin try 
   
  IF EXISTS    
    (
	select Id from OrderMaster where Id=@OrderMstID
	
	) 
	begin


		  insert into OrderPayment 
		  values(
		  @OrderMstID,@PaymentStatusID,@OrderNetAmount,@PaidAmount,@TipsAmount,(@OrderNetAmount-@PaidAmount),@balanceAmount,@TransactionID,@TransactionStatus,@TransactionResult,
		  @PaymentDatetime,@PaymentGateway,1,FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss')
  
		  );
				 SET @status='success';

     end

  Else	
       BEGIN
        SET @status='Order-ID not found';
		End
	 
	 end try

     begin catch
	   SET @status='Failed:'+ ERROR_MESSAGE();          
     end catch  
	 

	select @status
End

GO

-- Stored Procedure: [SP_OrderUpdateForShift]
IF OBJECT_ID('[SP_OrderUpdateForShift]', 'P') IS NOT NULL DROP PROCEDURE [SP_OrderUpdateForShift];
GO
-- =============================================
-- Author:  	<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_OrderUpdateForShift] 
@OrderId AS int,
@PaymentType AS varchar(20),
@BankId AS int,
@BankName AS varchar(50),
@DiscountPer AS varchar(5),
@CardType AS varchar(50),
@BankDiscountId AS int,
@RecAmount AS decimal,
@RecBy AS int,
@PaymentRemarks AS varchar(500),
@OrderNetAmount AS decimal,
@OrderStatus AS varchar(20)
AS
BEGIN

  DECLARE @shiftid AS int;
  DECLARE @shiftdate DATE;
  DECLARE @currentdatetime DATETIMEOFFSET;

  SET @shiftid = 0;

  -- Get current date and time adjusted to Pakistan Standard Time (UTC +5)
  SET @currentdatetime = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss')

  -- Get the start time of the morning shift from the shiftmaster table
  DECLARE @shiftstarttime TIME;
  SET @shiftstarttime = (SELECT StartTime FROM shiftmaster WHERE isactive = 1 AND IsDayChanged = 0);

  -- Adjust the shift date based on the current time in Pakistan
  IF (CAST(@currentdatetime AS TIME) >= '00:00:00' AND CAST(@currentdatetime AS TIME) < @shiftstarttime)
  BEGIN
      SET @shiftdate = CAST(DATEADD(DAY, -1, @currentdatetime) AS DATE);  -- Shift date is previous day if it's between midnight and shift start time
  END
  ELSE
  BEGIN
      SET @shiftdate = CAST(@currentdatetime AS DATE);  -- Otherwise, use today's date
  END

  -- Determine the current active shift
  SET @shiftid = (SELECT TOP 1
        id AS shiftid
    FROM shiftmaster
    WHERE isactive = 1
    AND (
        (IsDayChanged = 0 AND CAST(@currentdatetime AS time) >= CAST(StartTime AS time) AND CAST(@currentdatetime AS time) <= CAST(EndTime AS time))
        OR
        (IsDayChanged = 1 AND (
            (CAST(@currentdatetime AS time) >= CAST(StartTime AS time) AND CAST(@currentdatetime AS time) <= CAST(EndTime AS time))
            OR
            (CAST(@currentdatetime AS time) >= CAST(EndTime AS time) AND CAST(@currentdatetime AS time) <= '23:59')
            OR
            (CAST(@currentdatetime AS time) >= '00:00' AND CAST(@currentdatetime AS time) <= CAST(EndTime AS time))
        ))
    ))

  UPDATE ordermaster
  SET PaymentType = @PaymentType,
      RecAmount = @RecAmount,
      RecDate = @currentdatetime,  -- Using current datetime
      RecBy = @RecBy,
      ShiftIdCollection = @shiftid,
      PaymentCollectionRemarks = @PaymentRemarks,
      isPaymentCollected = 1,
      isFinalPaid = 1,
      OrderNetAmount = @OrderNetAmount
  WHERE id = @OrderId

  IF(@OrderStatus = 'Pending')
  BEGIN
      DECLARE @IsChange bit 

      SELECT @IsChange = ISChange FROM OrderMaster WHERE Id = @OrderId        
      IF(@IsChange = 1)        
      BEGIN        
          SET @IsChange = 0        
      END        
      ELSE        
      BEGIN        
          SET @IsChange = 1        
      END    

      UPDATE OrderMaster 
      SET IsHold = 0, IsFinalPaid = 1, ISChange = @IsChange              
      WHERE Id = @OrderId   
  END

  -- ENTRY INTO SHIFT CLOSING TABLE
  DECLARE @shiftcount AS int;

  SET @shiftcount = (SELECT
    COUNT(*) AS shiftcheck
  FROM shiftorderdetail
  WHERE (closeby = 0 OR closeby IS NULL)
  AND ShiftIdcollection = @shiftid
  AND shiftdate = @shiftdate) -- Using the adjusted @shiftdate

  IF (@shiftcount > 0)
  BEGIN
    -- Update existing record
    UPDATE ShiftOrderDetail
    SET TotalOrderAmount = TotalOrderAmount + @OrderNetAmount,
        RecAmount = RecAmount + @RecAmount,
        CashOrderAmount =
                         CASE
                           WHEN @PaymentType = 'CASH' THEN CashOrderAmount + (@RecAmount)
                           ELSE CashOrderAmount
                         END,
        CashTaxAmount =
                       CASE
                         WHEN @PaymentType = 'CASH' THEN CashTaxAmount + (SELECT TaxAmount FROM ordermaster WHERE id = @OrderId)
                         ELSE CashTaxAmount
                       END,
        CardOrderAmount =
                         CASE
                           WHEN @PaymentType = 'CARD' THEN CardOrderAmount + (@RecAmount)
                           ELSE CardOrderAmount
                         END,
        CardTaxAmount =
                       CASE
                         WHEN @PaymentType = 'CARD' THEN CardTaxAmount + (SELECT TaxAmount FROM ordermaster WHERE id = @OrderId)
                         ELSE CardTaxAmount
                       END
    WHERE (closeby = 0 OR closeby IS NULL)
    AND ShiftIdcollection = @shiftid
    AND shiftdate = @shiftdate

  END
  ELSE
  BEGIN
    -- Insert new record
    INSERT INTO ShiftOrderDetail ([ShiftIdCollection]
    , [TotalOrderAmount]
    , [RecAmount]
    , [CreatedDate]
    , [CashOrderAmount]
    , [CashTaxAmount]
    , [CardOrderAmount]
    , [CardTaxAmount]
    , [DiscountAmount]
    , [ShiftDate])
    VALUES (@shiftid, @OrderNetAmount, @RecAmount, @currentdatetime, 
            CASE WHEN @PaymentType = 'CASH' THEN @RecAmount ELSE 0 END, 
            CASE WHEN @PaymentType = 'CASH' THEN (SELECT TaxAmount FROM ordermaster WHERE id = @OrderId) ELSE 0 END, 
            CASE WHEN @PaymentType = 'CARD' THEN @RecAmount ELSE 0 END, 
            CASE WHEN @PaymentType = 'CARD' THEN (SELECT TaxAmount FROM ordermaster WHERE id = @OrderId) ELSE 0 END, 
            '0', -- Discount amount (this needs to be passed from frontend)
            @shiftdate) -- Using the adjusted shift date
  END

END

GO

-- Stored Procedure: [SP_PrintOrder]
IF OBJECT_ID('[SP_PrintOrder]', 'P') IS NOT NULL DROP PROCEDURE [SP_PrintOrder];
GO
CREATE Procedure [dbo].[SP_PrintOrder] @OrderMasterId  int As Begin Declare @IsChange bit Select @IsChange =ISChange from OrderMaster Where Id = @OrderMasterId if(@IsChange = 1) begin Set @IsChange = 0 End else begin Set @IsChange = 1 End Update OrderMaster Set ISChange =@IsChange Where Id = @OrderMasterId End
GO

-- Stored Procedure: [SP_ReciptPrint]
IF OBJECT_ID('[SP_ReciptPrint]', 'P') IS NOT NULL DROP PROCEDURE [SP_ReciptPrint];
GO
CREATE PROCEDURE [dbo].[SP_ReciptPrint]  
                                                                                                                                                                                                                    
    @OrderId INT  
                                                                                                                                                                                                                                           
AS  
                                                                                                                                                                                                                                                         
BEGIN  
                                                                                                                                                                                                                                                      
	WAITFOR DELAY '00:00:05';
                                                                                                                                                                                                                                   
    DECLARE @IsFinalPaid BIT  
                                                                                                                                                                                                                               
    SELECT @IsFinalPaid = IsFinalPaid FROM OrderMaster WHERE Id = @OrderId  
                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
    IF (@IsFinalPaid = 1)  
                                                                                                                                                                                                                                  
    BEGIN  
                                                                                                                                                                                                                                                  
        SELECT  
                                                                                                                                                                                                                                             
            R.RestaurantName,  
                                                                                                                                                                                                                              
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,  
                                                                                                                                                                                 
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
                                                                                                                                                                                                    
            CASE WHEN OM.CreatedBy = -1 THEN OT.OrderType + ' Order' ELSE OT.OrderType + ' Order' END OrderType,  
                                                                                                                                           
            JobRefNo OrderNo,  
                                                                                                                                                                                                                              
            CASE WHEN OD.DeletedItemQty IS NULL THEN SUM(OD.ItemQty)   
                                                                                                                                                                                      
                 ELSE SUM(OD.DeletedItemQty) END 'QTY',  
                                                                                                                                                                                                    
            CASE WHEN OD.IsDeleted = 1 THEN CONCAT(I.ItemDesc, '')   
                                                                                                                                                                                        
                 ELSE I.ItemDesc END 'Description',  
                                                                                                                                                                                                        
            OD.Rate,  
                                                                                                                                                                                                                                       
            OM.OrderAmount TotalAmount,  
                                                                                                                                                                                                                    
            OM.OrderNetAmount NetBill,  
                                                                                                                                                                                                                     
            IV.ItemSize,  
                                                                                                                                                                                                                                   
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,  
                                                                                                                                                             
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,  
                                                                                                                                                                                  
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,  
                                                                                                                                                                         
            (SELECT RIGHT(CONVERT(VARCHAR, DATEADD(HOUR, 0, OM.OrderDate), 100), 7)) AS Sliptime,  
                                                                                                                                                          
            OM.TableNo,  
                                                                                                                                                                                                                                    
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
            OD.CategoryId,  
                                                                                                                                                                                                                                 
            W.WaiterName,  
                                                                                                                                                                                                                                  
            OD.Amount,  
                                                                                                                                                                                                                                     
            OM.DiscountPer,  
                                                                                                                                                                                                                                
            OM.PaymentType,  
                                                                                                                                                                                                                                
            'FINAL RECEIPT' 'ReceiptType',  
                                                                                                                                                                                                                 
            OD.Notes,  
                                                                                                                                                                                                                                      
            ISNULL(OD.IsDeleted, 0) AS IsDeleted,  
                                                                                                                                                                                                          
            OM.WaiterName AS AssignedWaiter,  
                                                                                                                                                                                                               
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
            OM.Deletedtaxamount,  
                                                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailOption1 O1  
                                                                                                                                                                                                              
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id  
                                                                                                                                                                                         
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId  
                                                                                                                                                             
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,  
                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailOption2 O2  
                                                                                                                                                                                                              
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id  
                                                                                                                                                                                        
                   WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId  
                                                                                                                                                             
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,  
                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailAddOns O3  
                                                                                                                                                                                                               
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId  
                                                                                                                                                                                          
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId  
                                                                                                                                                             
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,  
                                                                                                                                                                                           
            (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL)), 2) / 100) AS discountamounttest,  
                                                                                                                                                  
            CAST(OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100) AS DECIMAL(10, 0)) AS discountamount,  
                                                                                                      
            CAST(((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) * (OM.TaxPer / 100)) AS DECIMAL(10, 0)) AS taxamountondiscount,  
                                                      
            CAST((((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) + ((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) *
 (OM.TaxPer / 100)))) AS DECIMAL(10, 0)) AS totalamountwithdiscountandtax,
                                                                                                                                                                                   
			OM.CustomerName, OM.SrbInvoiceId
        FROM  
                                                                                                                                                                                                                                               
            OrderMaster OM  
                                                                                                                                                                                                                                 
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId  
                                                                                                                                                                                          
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId  
                                                                                                                                                                                               
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId  
                                                                                                                                                                                     
            INNER JOIN Item I ON OD.ItemId = I.Id  
                                                                                                                                                                                                          
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId  
                                                                                                                                                                                      
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId  
                                                                                                                                                                                              
            LEFT JOIN Waiter W ON W.id = COALESCE(OM.WaiterId, A.WaiterId)  -- Modified join condition
                                                                                                                                                       
            WHERE  
                                                                                                                                                                                                                                          
                OM.Id = @OrderId  
                                                                                                                                                                                                                           
                AND OM.IsFinalPaid = 1  
                                                                                                                                                                                                                     
        GROUP BY  
                                                                                                                                                                                                                                           
            R.RestaurantName,  
                                                                                                                                                                                                                              
            R.PhoneNo1,  
                                                                                                                                                                                                                                    
            R.PhoneNo2,  
                                                                                                                                                                                                                                    
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
            OM.OrderDate,  
                                                                                                                                                                                                                                  
            OT.OrderType,  
                                                                                                                                                                                                                                  
            JobRefNo,  
                                                                                                                                                                                                                                      
            I.ItemDesc,  
                                                                                                                                                                                                                                    
            OD.Rate,  
                                                                                                                                                                                                                                       
            OM.OrderNetAmount,  
                                                                                                                                                                                                                             
            IV.ItemSize,  
                                                                                                                                                                                                                                   
            OM.OrderDiscount,  
                                                                                                                                                                                                                              
            OM.TaxAmount,  
                                                                                                                                                                                                                                  
            OM.OrderAmount,  
                                                                                                                                                                                                                                
            OD.Amount,  
                                                                                                                                                                                                                                     
            OM.TableNo,  
                                                                                                                                                                                                                                    
            OM.CreatedBy,  
                                                                                                                                                                                                                                  
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
            OD.CategoryId,  
                                                                                                                                                                                                                                 
            W.WaiterName,  
                                                                                                                                                                                                                                  
            OD.OrderDetailSelfId,  
                                                                                                                                                                                                                          
            OD.ItemId,  
                                                                                                                                                                                                                                     
            OD.CategoryId,  
                                                                                                                                                                                                                                 
            OM.DiscountPer,  
                                                                                                                                                                                                                                
            OM.TaxPer,  
                                                                                                                                                                                                                                     
            OM.PaymentType,  
                                                                                                                                                                                                                                
            OD.Notes,  
                                                                                                                                                                                                                                      
            OD.IsDeleted,  
                                                                                                                                                                                                                                  
            OM.WaiterName,  
                                                                                                                                                                                                                                 
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
            OM.Deletedtaxamount,
                                                                                                                                                                                                                             
			OM.CustomerName, OM.SrbInvoiceId
    END  
                                                                                                                                                                                                                                                    
    ELSE  
                                                                                                                                                                                                                                                   
    BEGIN  
                                                                                                                                                                                                                                                  
        SELECT  
                                                                                                                                                                                                                                             
            R.RestaurantName,  
                                                                                                                                                                                                                              
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,  
                                                                                                                                                                                 
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
                                                                                                                                                                                                    
            CASE WHEN OM.CreatedBy = -1 THEN OT.OrderType + ' Order' ELSE OT.OrderType + ' Order' END OrderType,  
                                                                                                                                           
            JobRefNo OrderNo,  
                                                                                                                                                                                                                              
            OD.ItemQty QTY,  
                                                                                                                                                                                                                                
            CASE WHEN OD.IsDeleted = 1 THEN CONCAT(I.ItemDesc, '')   
                                                                                                                                                                                        
                 ELSE I.ItemDesc END 'Description',  
                                                                                                                                                                                                        
            OD.Rate,  
                                                                                                                                                                                                                                       
            OM.OrderAmount TotalAmount,  
                                                                                                                                                                                                                    
            OM.OrderNetAmount NetBill,  
                                                                                                                                                                                                                     
            IV.ItemSize,  
                                                                                                                                                                                                                                   
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,  
                                                                                                                                                             
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,  
                                                                                                                                                                                  
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,  
                                                                                                                                                                         
            (SELECT RIGHT(CONVERT(VARCHAR, DATEADD(HOUR, 0, OM.OrderDate), 100), 7)) AS Sliptime,  
                                                                                                                                                          
            OM.TableNo,  
                                                                                                                                                                                                                                    
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
            OD.CategoryId,  
                                                                                                                                                                                                                                 
            W.WaiterName,  
                                                                                                                                                                                                                                  
            OD.Amount,  
                                                                                                                                                                                                                                     
            OM.DiscountPer,  
                                                                                                                                                                                                                                
            OM.PaymentType,  
                                                                                                                                                                                                                                
            'PARTIAL RECEIPT' 'ReceiptType',  
                                                                                                                                                                                                               
            OD.Notes,  
                                                                                                                                                                                                                                      
            ISNULL(OD.IsDeleted, 0) AS IsDeleted,  
                                                                                                                                                                                                          
            OM.WaiterName AS AssignedWaiter,  
                                                                                                                                                                                                               
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
            OM.Deletedtaxamount,  
                                                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailOption1 O1  
                                                                                                                                                                                                              
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id  
                                                                                                                                                                                         
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId  
                                                                                                                                                             
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,  
                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailOption2 O2  
                                                                                                                                                                                                              
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id  
                                                                                                                                                                                        
         WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId  
                                                                                                                                                                       
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,  
                                                                                                                                                                                           
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')  
                                                                                                                                                                                               
                   FROM OrderDetailAddOns O3  
                                                                                                                                                                                                               
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId  
                                                                                                                                                                                          
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId  
                                                                                                                                                             
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,  
                                                                                                                                                                                           
            (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL)), 2) / 100) AS discountamounttest,  
                                                                                                                                                  
            CAST(OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100) AS DECIMAL(10, 0)) AS discountamount,  
                                                                                                      
            CAST(((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) * (OM.TaxPer / 100)) AS DECIMAL(10, 0)) AS taxamountondiscount,  
                                                      
            CAST((((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) + ((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) *
 (OM.TaxPer / 100)))) AS DECIMAL(10, 0)) AS totalamountwithdiscountandtax,
                                                                                                                                                                                   
			OM.CustomerName, OM.SrbInvoiceId
        FROM  
                                                                                                                                                                                                                                               
            OrderMaster OM  
                                                                                                                                                                                                                                 
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId  
                                                                                                                                                                                          
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId  
                                                                                                                                                                                               
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId  
                                                                                                                                                                                     
            INNER JOIN Item I ON OD.ItemId = I.Id  
                                                                                                                                                                                                          
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId  
                                                                                                                                                                                      
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId  
                                                                                                                                                                                              
            LEFT JOIN Waiter W ON W.id = COALESCE(OM.WaiterId, A.WaiterId)  -- Modified join condition
                                                                                                                                                       
            WHERE  
                                                                                                                                                                                                                                          
                OM.Id = @OrderId  
                                                                                                                                                                                                                           
    END  
                                                                                                                                                                                                                                                    
END
                                                                                                                                                                                                                                                          


GO

-- Stored Procedure: [SP_ReciptPrint_Asad]
IF OBJECT_ID('[SP_ReciptPrint_Asad]', 'P') IS NOT NULL DROP PROCEDURE [SP_ReciptPrint_Asad];
GO
CREATE Procedure [dbo].[SP_ReciptPrint_Asad]
    @OrderId INT
AS
BEGIN
    DECLARE @IsFinalPaid BIT
    SELECT @IsFinalPaid = IsFinalPaid FROM OrderMaster WHERE Id = @OrderId

    IF (@IsFinalPaid = 1)
    BEGIN
        SELECT
            R.RestaurantName,
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,
            R.RestaurantAddress1,
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
            CASE WHEN OM.CreatedBy = -1 THEN 'Mobile-' + OT.OrderType ELSE ' Manual-' + OT.OrderType END OrderType,
            JobRefNo OrderNo,
            SUM(OD.ItemQty) QTY,
            I.ItemDesc 'Description',
            OD.Rate,
            OM.OrderAmount TotalAmount,
            OM.OrderNetAmount NetBill,
            IV.ItemSize,
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,
            CONVERT(CHAR(5), GETDATE(), 108) Sliptime,
            OM.TableNo,
            OM.IsFinalPaid,
            OD.CategoryId,
            W.WaiterName,
            OD.Amount,
            OM.DiscountPer,
			OM.PaymentType,
            'FINAL RECEIPT' 'ReceiptType',
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')
                   FROM OrderDetailOption1 O1
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')
                   FROM OrderDetailOption2 O2
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id
                   WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')
                   FROM OrderDetailAddOns O3
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,
				   (convert(decimal,(cast(discountper as decimal)),2)/100) as discountamounttest,

				   ROUND( (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)) ,0)as discountamount,

				  ROUND( ((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)))*(OM.TaxPer/100)),0) as taxamountondiscount,

				   ROUND(((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100))))+
				   ((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)))*(OM.TaxPer/100)),0)

				   
				   as totalamountwithdiscountandtax

        FROM
            OrderMaster OM
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId
            INNER JOIN Item I ON OD.ItemId = I.Id
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId
            LEFT JOIN Waiter W ON W.id = A.WaiterId
            WHERE OD.IsDeleted = 0
                AND OM.Id = @OrderId
                AND OM.IsFinalPaid = 1
        GROUP BY
            R.RestaurantName,
            R.PhoneNo1,
            R.PhoneNo2,
            R.RestaurantAddress1,
            OM.OrderDate,
            OT.OrderType,
            JobRefNo,
            I.ItemDesc,
            OD.Rate,
            OM.OrderNetAmount,
            IV.ItemSize,
            OM.OrderDiscount,
            OM.TaxAmount,
            OM.OrderAmount,
            OD.Amount,
            OM.TableNo,
            OM.CreatedBy,
            OM.IsFinalPaid,
            Od.CategoryId,
            W.WaiterName,
            OD.OrderDetailSelfId,
            OD.ItemId,
            OD.CategoryId,
            Om.DiscountPer,
            Om.TaxPer,
			OM.PaymentType
    END
    ELSE
    BEGIN
        SELECT
            R.RestaurantName,
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,
            R.RestaurantAddress1,
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
            CASE WHEN OM.CreatedBy = -1 THEN 'Mobile-' + OT.OrderType ELSE ' Manual-' + OT.OrderType END OrderType,
            JobRefNo OrderNo,
            OD.ItemQty QTY,
            I.ItemDesc 'Description',
            OD.Rate,
            OM.OrderAmount TotalAmount,
            OM.OrderNetAmount NetBill,
            IV.ItemSize,
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,
            CONVERT(CHAR(5), GETDATE(), 108) Sliptime,
            OM.TableNo,
            OM.IsFinalPaid,
            OD.CategoryId,
            W.WaiterName,
            OD.Amount,
            Om.DiscountPer,
			OM.PaymentType,
            'PARTIAL RECEIPT' 'ReceiptType',
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')
                   FROM OrderDetailOption1 O1
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')
                   FROM OrderDetailOption2 O2
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id
                   WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')
                   FROM OrderDetailAddOns O3
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,

				   (convert(decimal,(cast(discountper as decimal)),2)/100) as discountamounttest,
				  ROUND( (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)) ,0)as discountamount,

				  ROUND( ((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)))*(OM.TaxPer/100)),0) as taxamountondiscount,

				   ROUND(((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100))))+
				   ((OM.OrderAmount - (OM.OrderAmount * (convert(decimal,(cast(discountper as decimal)),2)/100)))*(OM.TaxPer/100)),0)

				   
				   as totalamountwithdiscountandtax
        FROM
            OrderMaster OM
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId
            INNER JOIN Item I ON OD.ItemId = I.Id
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId
            LEFT JOIN Waiter W ON W.id = A.WaiterId
            WHERE OD.IsDeleted = 0
                AND (OD.IsPrinted = 0 OR OD.IsPrinted IS NULL)
                AND OM.Id = @OrderId
            GROUP BY
                R.RestaurantName,
                R.PhoneNo1,
                R.PhoneNo2,
                R.RestaurantAddress1,
                OM.OrderDate,
                OT.OrderType,
                JobRefNo,
                I.ItemDesc,
                OD.Rate,
                OM.OrderNetAmount,
                IV.ItemSize,
                OM.OrderDiscount,
                OM.TaxAmount,
                OM.OrderAmount,
                OD.Amount,
                OM.TableNo,
                OM.CreatedBy,
                OM.IsFinalPaid,
                Od.CategoryId,
                W.WaiterName,
                OD.OrderDetailSelfId,
                OD.ItemId,
                OD.CategoryId,
                OD.ItemQty,
                Om.DiscountPer,
                Om.TaxPer,
				OM.PaymentType
    END
END

GO

-- Stored Procedure: [SP_ReciptPrintKOT]
IF OBJECT_ID('[SP_ReciptPrintKOT]', 'P') IS NOT NULL DROP PROCEDURE [SP_ReciptPrintKOT];
GO

CREATE Procedure [dbo].[SP_ReciptPrintKOT]  
                                                                                                                                                                                                                 
                                                                                                                                                                                                                    
                                         
    @OrderId INT  
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
AS  
                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                         
    
BEGIN  
                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                      
       
	WAITFOR DELAY '00:00:05';
                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                   
                          
    DECLARE @IsFinalPaid BIT  
                                                                                                                                                                                                                               
                                                                                                                                                                                                                               
                              
    SELECT @IsFinalPaid = IsFinalPaid FROM OrderMaster WHERE Id = @OrderId  
                                                                                                                                                                                 
                                                                                                                                                                                 
                                                                            

                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                             

    IF (@IsFinalPaid = 1)  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
    BEGIN  
                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                  
           
        SELECT  
                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                             
                
            R.RestaurantName,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,  
                                                                                                                                                                                 
                                                                                                                                                                                 
                                                                            
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
                                                                                                                                                                                                                          
                                   
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
                                                                                                                                                                                                    
                                                                                                                                                                                                    
                                                         
            CASE WHEN OM.CreatedBy = -1 THEN OT.OrderType + ' Order' ELSE OT.OrderType + ' Order' END OrderType,  
                                                                                                                                           
                                                                                                                 
                                                                                                                                            
            JobRefNo OrderNo,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            CASE WHEN OD.DeletedItemQty IS NULL THEN SUM(OD.ItemQty)   
                                                                                                                                                                                      
                                                                                                                                                                                      
                                                                       
                 ELSE SUM(OD.DeletedItemQty) END 'QTY',  
                                                                                                                                                                                                    
                                                                                                                                                                                                    
                                                         
            CASE WHEN OD.IsDeleted = 1 THEN CONCAT(I.ItemDesc, '')   
                                                                                                                                                                                        
                                                                                                                                                                                        
                                                                     
                 ELSE I.ItemDesc END 'Description',  
                                                                                                                                                                                                        
                                                                                                                                                                                                        
                                                     
            OD.Rate,  
                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                       
                      
            OM.OrderAmount TotalAmount,  
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
                                         
            OM.OrderNetAmount NetBill,  
                                                                                                                                                                                                                     
                                                                                                                                                                                                                     
                                        
            IV.ItemSize,  
                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                   
                          
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,  
                                                                                                                                                                                  
                                                                                                                                                                                  
                                                                           
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,  
                                                                                                                                                                         
                                                                                                                                                                         
                                                                                    
            (SELECT RIGHT(CONVERT(VARCHAR, DATEADD(HOUR, 0, OM.OrderDate), 100), 7)) AS Sliptime,  
                                                                                                                                                          
                                                                                                                                                          
                                                                                                   
            OM.TableNo,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OD.CategoryId,  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            W.WaiterName,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.Amount,  
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
            OM.DiscountPer,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OM.PaymentType,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            'FINAL RECEIPT' 'ReceiptType',  
                                                                                                                                                                                                                 
                                                                                                                                                                                                                 
                                            
            OD.Notes,  
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
            ISNULL(OD.IsDeleted, 0) AS IsDeleted,  
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
            OM.WaiterName AS AssignedWaiter,  
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
                                                                                                                                                                                                                       
                                      
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
                                                                                                                                                                                                                               
                              
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
                                                                                                                                                                                                                             
                                
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
                                                                                                                                                                                                                         
                                    
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
                                                                                
                                                                                                                                                                             
            OM.Deletedtaxamount,  
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
                                  
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailOption1 O1  
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id  
                                                                                                                                                                                         
                                                                                                                                                                                         
                                                                    
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailOption2 O2  
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id  
                                                                                                                                                                                        
                                                                                                                                                                                        
                                                                     
                   WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailAddOns O3  
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId  
                                                                                                                                                                                          
                                                                                                                                                                                          
                                                                   
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL)), 2) / 100) AS discountamounttest,  
                                                                                                                                                  
                                                                                                                                                  
                                                                                                           
            CAST(OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100) AS DECIMAL(10, 0)) AS discountamount,  
                                                                                                      
                                                                                                      
                                                                                                                                                       
            CAST(((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) * (OM.TaxPer / 100)) AS DECIMAL(10, 0)) AS taxamountondiscount,  
                                                      
                                                      
                                                                                                                                                                                                       
            CAST((((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) + ((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) *

                                                                                                                                                                                                                                                             
 (OM.TaxPer / 100)))) AS DECIMAL(10, 0)) AS totalamountwithdiscountandtax,
                                                                                                                                                                                   
                                                                                                                                                                                   
                                                                          
			OM.CustomerName
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
        FROM  
                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                               
              
            OrderMaster OM  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId  
                                                                                                                                                                                          
                                                                                                                                                                                          
                                                                   
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId  
                                                                                                                                                                                     
                                                                                                                                                                                     
                                                                        
            INNER JOIN Item I ON OD.ItemId = I.Id  
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId  
                                                                                                                                                                                      
                                                                                                                                                                                      
                                                                       
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId  
                                                                                                                                                                                              
                                                                                                                                                                                              
                                                               
            LEFT JOIN Waiter W ON W.id = COALESCE(OM.WaiterId, A.WaiterId)  -- Modified join condition
                                                                                                                                                       
                                               
                                                                                                                                                                                                              
            WHERE OM.Id = @OrderId AND ISNULL(OD.IsPrinted, 0) = 0  
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
                                  
                AND OM.IsFinalPaid = 1  
                                                                                                                                                                                                                     
                                                                                                                                                                                                                     
                                        
        GROUP BY  
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
            R.RestaurantName,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            R.PhoneNo1,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            R.PhoneNo2,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
                                                                                                                                                                                                                          
                                   
            OM.OrderDate,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OT.OrderType,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            JobRefNo,  
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
            I.ItemDesc,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            OD.Rate,  
                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                       
                      
            OM.OrderNetAmount,  
                                                                                                                                                                                                                             
                                                                                                                                                                                                                             
                                
            IV.ItemSize,  
                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                   
                          
            OM.OrderDiscount,  
                                                                                                                                                                                                                              
                                                                                                                                                               
                                                                                              
            OM.TaxAmount,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OM.OrderAmount,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OD.Amount,  
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
            OM.TableNo,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            OM.CreatedBy,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OD.CategoryId,  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            W.WaiterName,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.OrderDetailSelfId,  
                                                                                                                                                                                                                          
                                                                                                                                                                                                                          
                                   
            OD.ItemId,  
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
            OD.CategoryId,  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            OM.DiscountPer,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OM.TaxPer,  
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
            OM.PaymentType,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OD.Notes,  
                                                                                                                                                                                                                                      
              
                                                                                                                                                                                                                                               
            OD.IsDeleted,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OM.WaiterName,  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
                                                                                                                                                                                                                       
                                      
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
                                                                                                                                                                                                                               
                              
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
                                                                                                                                                                                                                             
                                
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
                                                                                                                                                                                                                         
                                    
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      
                                       
            OM.Deletedtaxamount,
                                                                                                                                                                                                                             
                                                                                                                                                                                                                             
                                
			OM.CustomerName
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
    END  
                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                    
         
    ELSE  
                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                   
          
    BEGIN  
                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                  
           
        SELECT  
                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                             
                
            R.RestaurantName,  
                                                                                                                                                                                                                              
                                                                                                                              
                                                                                                                               
            ISNULL(R.PhoneNo1, '') + ',' + ISNULL(R.PhoneNo2, '') PhoneNo,  
                                                                                                                                                                                 
                                                                                                                                                                                 
                                                                            
            R.RestaurantAddress1,  
                                                                                                                                                                                                                          
                                                                                                                                                                                                                          
                                   
            CONVERT(VARCHAR, OM.OrderDate, 23) OrderDate,
                                                                                                                                                                                                    
                                                                                                                                                                                                    
                                                         
            CASE WHEN OM.CreatedBy = -1 THEN OT.OrderType + ' Order' ELSE OT.OrderType + ' Order' END OrderType,  
                                                                                                                                           
                                                                                                                                           
                                                                                                                  
            JobRefNo OrderNo,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            OD.ItemQty QTY,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            CASE WHEN OD.IsDeleted = 1 THEN CONCAT(I.ItemDesc, '')   
                                                                                                                                                                                        
                                                                                                                                                                                        
                                                                     
                 ELSE I.ItemDesc END 'Description',  
                                                                                                                                                                                                        
                                                                                                                                                                                                        
                                                     
            OD.Rate,  
                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                       
                      
            OM.OrderAmount TotalAmount,  
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
                                         
            OM.OrderNetAmount NetBill,  
                                                                                                                                                                                                                     
                                                                                                                                                                                                                     
                                        
            IV.ItemSize,  
                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                   
                          
            CASE WHEN OM.OrderDiscount IS NULL THEN 0 ELSE OM.OrderDiscount END OrderDiscount,  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
            CASE WHEN OM.TaxPer IS NULL THEN 0 ELSE OM.TaxPer END TaxPer,  
                                                                                                                                                                                  
                                                                                                                                                                                  
                                                                           
            CASE WHEN OM.TaxAmount IS NULL THEN 0 ELSE OM.TaxAmount END TaxAmount,  
                                                                                                                                                                         
                                                                                                                                                                         
                                                                                    
            (SELECT RIGHT(CONVERT(VARCHAR, DATEADD(HOUR, 0, OM.OrderDate), 100), 7)) AS Sliptime,  
                                                                                                                                                          
                                                                                                                                                          
                                                                                                   
            OM.TableNo,  
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                    
                         
            OM.IsFinalPaid,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OD.CategoryId,  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            W.WaiterName,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.Amount,  
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                     
                        
            OM.DiscountPer,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            OM.PaymentType,  
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                
                             
            'PARTIAL RECEIPT' 'ReceiptType',  
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
            OD.Notes,  
                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                      
                       
            ISNULL(OD.IsDeleted, 0) AS IsDeleted,  
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                   
            OM.WaiterName AS AssignedWaiter,  
                                                                                                                                                                                                               
                                                                                                                                                                                                               
                                              
            OM.PaymentReceiveByName,  
                                                                                                                                                                                                                       
                                                                                                                                                                                                                       
                                      
            OM.ReceiptCount,  
                                                                                                                                                                                                                               
                                                                                                                                                                                                                               
                              
            OD.IsPrinted,  
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  
                           
            OD.DeletedItemQty,  
                                                                                                                                                                                                                             
                                                                                             
                                                                                                                                                                
            OD.DeletedAmount,  
                                                                                                                                                                                                                              
                                                                                                                                                                                                                              
                               
            OM.DeletedOrderAmount,  
                                                                                                                                                                                                                         
                                                                                                                                                                                                                         
                                    
            OM.DeletedOrderNetAmount,  
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      
                                       
            OM.Deletedtaxamount,  
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
                                  
            STUFF((SELECT ', ' + ISNULL(OO1.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailOption1 O1  
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
                   LEFT JOIN Options1 OO1 ON OO1.Id = O1.Option1Id  
                                                                                                                                                                                         
                                                                                                                                                                                         
                                                                    
                   WHERE O1.OrderDetailSelfId = OD.OrderDetailSelfId AND O1.ItemId = OD.ItemId  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc1,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            STUFF((SELECT ', ' + ISNULL(OO2.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailOption2 O2  
                                                                                                                                                                                                              
                                                                                                                                                                                                              
                                               
                   INNER JOIN Options1 OO2 ON OO2.Id = O2.Option2Id  
                                                                                                                                                                                        
                                                                                                                                                                                        
                                                                     
         WHERE O2.OrderDetailSelfId = OD.OrderDetailSelfId AND O2.ItemId = OD.ItemId  
                                                                                                                                                                       
                                                                                                                                                                       
                                                                                      
                   FOR XML PATH('')), 1, 2, '') AS Option1Desc2,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            STUFF((SELECT ', ' + ISNULL(OO3.Option1Desc, '')  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
                   FROM OrderDetailAddOns O3  
                                                                                                                                                                                                               
                                                                                                                                                                                                             
                                                
                   INNER JOIN Options1 OO3 ON OO3.Id = O3.AddonId  
                                                                                                                                                                                          
                                                                                                                                                                                          
                                                                   
                   WHERE O3.OrderDetailSelfId = OD.OrderDetailSelfId AND O3.ItemId = OD.ItemId  
                                                                                                                                                             
                                                                                                                                                             
                                                                                                
                   FOR XML PATH('')), 1, 2, '') AS Option1DescA,  
                                                                                                                                                                                           
                                                                                                                                                                                           
                                                                  
            (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL)), 2) / 100) AS discountamounttest,  
                                                                                                                                                  
                                                                                                                                                  
                                                                                                           
            CAST(OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100) AS DECIMAL(10, 0)) AS discountamount,  
                                                                                                      
                                                                                                      
                                                                                                                                                       
            CAST(((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) * (OM.TaxPer / 100)) AS DECIMAL(10, 0)) AS taxamountondiscount,  
                                                      
                                                      
                                                                                                                                                                                                       
            CAST((((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) + ((OM.OrderAmount - (OM.OrderAmount * (CONVERT(DECIMAL, (CAST(ISNULL(discountper, 0) AS DECIMAL(16, 2))), 2) / 100))) *

                                                                                                                                                                                                                                                             
 (OM.TaxPer / 100)))) AS DECIMAL(10, 0)) AS totalamountwithdiscountandtax,
                                                                                                                                                                                   
                                                                                                                                                                                   
                                                                          
			OM.CustomerName
                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
                  
        FROM  
                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                               
              
            OrderMaster OM  
                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                 
                            
            INNER JOIN OrderDetail OD ON OM.Id = OD.OrderMasterId  
                                                                                                                                                                                          
                                                                                                                                                                                          
                                                                   
            INNER JOIN Restaurant R ON R.Id = OM.ResturantId  
                                                                                                                                                                                               
                                                                                                                                                                                               
                                                              
            INNER JOIN OrderType OT ON OT.OrderTypeId = OM.OrderTypeId  
                                                                                                                                                                                     
                                                                                                                                                                                     
                                                                        
            INNER JOIN Item I ON OD.ItemId = I.Id  
                                                                                                                                                                                                          
                                                            
                                                                                                                                                                                                 
            INNER JOIN ItemVeriation IV ON IV.Id = OD.ItemVeriationId  
                                                                                                                                                                                      
                                                                                                                                                                                      
                                                                       
            LEFT JOIN AssignTable A ON A.TableId = OM.TableId  
                                                                                                                                                                                              
                                                                                                                                                                                              
                                                               
            LEFT JOIN Waiter W ON W.id = COALESCE(OM.WaiterId, A.WaiterId)  -- Modified join condition
                                                                                                                                                       
                                                                                                                                                       
                                                                                                      
            WHERE OM.Id = @OrderId AND ISNULL(OD.IsPrinted, 0) = 0  
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
                                  
    END  
                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                    
         
END
                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                          
   

GO

-- Stored Procedure: [SP_ReciptPrintQR]
IF OBJECT_ID('[SP_ReciptPrintQR]', 'P') IS NOT NULL DROP PROCEDURE [SP_ReciptPrintQR];
GO

CREATE PROCEDURE [dbo].[SP_ReciptPrintQR]
@Id INT
AS
BEGIN
    SELECT 
        CONVERT(DATE, FD.CreatedDate) AS SlipDate, 
        RIGHT(CONVERT(VARCHAR, FD.CreatedDate, 100), 7) AS Sliptime,  
        'SLIP CODE RECEIPT' AS ReceiptType, R.RestaurantName, R.RestaurantAddress, R.RestaurantAddress1, R.PhoneNo1 ,R.ImageURL ,
        (SELECT TOP 1 c1.fname FROM Customer c1 WHERE c1.FlightId = FD.Id) AS CustomerName,
        FD.FlightNo,
        FD.SlipCode,
		FD.NoofMeals
    FROM
        FlightDetails FD
		Join Restaurant R on 1=1
    WHERE 
        FD.Id = @Id;
END;

GO

