-- Stored Procedure: [Sp_Report_BankWiseReport]
IF OBJECT_ID('[Sp_Report_BankWiseReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_BankWiseReport];
GO

CREATE PROCEDURE [dbo].[Sp_Report_BankWiseReport]  
    @FromDate DATETIME = NULL,  
    @ToDate DATETIME = NULL,  
    @ReportName NVARCHAR(255) = NULL,  
    @OrderStatus NVARCHAR(50) = NULL,  
    @IsWeb NVARCHAR(50) = NULL,  
    @OrderNo NVARCHAR(50) = NULL,  
    @OrderTypeId INT = NULL,  
    @PaymentStatus NVARCHAR(50) = NULL,  
    @CustomerName NVARCHAR(100) = NULL,  
    @SearchTerm NVARCHAR(100) = NULL,  
    @DepartmentId INT = NULL,
    @PageNumber INT = 1,  
    @PageSize INT = 10  
AS  
BEGIN  
    SET NOCOUNT ON;  

    -- Calculate the offset for pagination
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Main Query with Pagination
    SELECT 
        BankName,
        CardType,
        SUM(CustomerCount) AS CustomerCount,
        SUM(TotalOrders) AS TotalOrders,
        ROUND(SUM(NetAmount), 0) AS NetAmount
    FROM (
        -- Flight Payments
        SELECT 
            ISNULL(fcb.BankName, 'Unknown Bank') AS BankName,
            ISNULL(fcb.CardProduct, 'N/A') AS CardType,
            COUNT(DISTINCT fcb.PassengerName) AS CustomerCount,
            COUNT(fcb.Id) AS TotalOrders,
            SUM(CAST(ISNULL(fcb.Meals, 0) AS DECIMAL(18,2)) * (ISNULL(om.OrderNetAmount, 0) / NULLIF(CAST(ISNULL(fd.NoofMeals, 0) AS DECIMAL(18,2)), 0))) AS NetAmount
        FROM [dbo].[FlightCustomerBanks] fcb
        INNER JOIN [dbo].[FlightDetails] fd ON fcb.FlightId = fd.Id
        LEFT JOIN [dbo].[OrderMaster] om ON fd.OrderId = om.Id
        WHERE 
            fcb.IsActive = 1
            AND (@FromDate IS NULL OR CAST(fd.CreatedDate AS DATE) >= CAST(@FromDate AS DATE))
            AND (@ToDate IS NULL OR CAST(fd.CreatedDate AS DATE) <= CAST(@ToDate AS DATE))
            AND (@DepartmentId IS NULL OR @DepartmentId = 0 OR om.ResturantId = @DepartmentId OR (om.Id IS NULL AND fd.CreatedBy IS NOT NULL))
            -- AND (@OrderStatus IS NULL OR om.OrderStatus = @OrderStatus OR om.Id IS NULL)
            AND (@OrderNo IS NULL OR om.JobRefNo LIKE '%' + @OrderNo + '%' OR fd.SlipCode LIKE '%' + @OrderNo + '%')
            AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
            AND (@PaymentStatus IS NULL OR om.IsPaymentCollected = @PaymentStatus)
            AND (@CustomerName IS NULL OR om.CustomerName LIKE '%' + @CustomerName + '%' OR fcb.PassengerName LIKE '%' + @CustomerName + '%')
            AND (@SearchTerm IS NULL OR fcb.BankName LIKE '%' + @SearchTerm + '%' OR fcb.CardProduct LIKE '%' + @SearchTerm + '%')
        GROUP BY fcb.BankName, fcb.CardProduct

        UNION ALL

        -- Regular/Dine-in Payments
        SELECT 
            ISNULL(om.BankName, 'Direct Card') AS BankName,
            ISNULL(om.CardType, 'N/A') AS CardType,
            COUNT(DISTINCT om.Id) AS CustomerCount,
            COUNT(om.Id) AS TotalOrders,
            SUM(ISNULL(om.OrderNetAmount, 0)) AS NetAmount
        FROM [dbo].[OrderMaster] om
        WHERE 
            om.BankName IS NOT NULL
            AND om.IsDeleted = 0
            AND (@FromDate IS NULL OR CAST(om.OrderDate AS DATE) >= CAST(@FromDate AS DATE))
            AND (@ToDate IS NULL OR CAST(om.OrderDate AS DATE) <= CAST(@ToDate AS DATE))
            AND (@DepartmentId IS NULL OR @DepartmentId = 0 OR om.ResturantId = @DepartmentId)
            -- AND (@OrderStatus IS NULL OR om.OrderStatus = @OrderStatus)
            AND (@OrderNo IS NULL OR om.JobRefNo LIKE '%' + @OrderNo + '%')
            AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
            AND (@PaymentStatus IS NULL OR om.IsPaymentCollected = @PaymentStatus)
            AND (@CustomerName IS NULL OR om.CustomerName LIKE '%' + @CustomerName + '%')
            AND (@SearchTerm IS NULL OR om.BankName LIKE '%' + @SearchTerm + '%' OR om.CardType LIKE '%' + @SearchTerm + '%')
        GROUP BY om.BankName, om.CardType
    ) AS Combined
    GROUP BY BankName, CardType
    ORDER BY BankName, CardType
    OFFSET @Offset ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Total Count for Pagination
    SELECT COUNT(*) FROM (
        SELECT BankName, CardType
        FROM (
            SELECT fcb.BankName, fcb.CardProduct AS CardType
            FROM [dbo].[FlightCustomerBanks] fcb
            INNER JOIN [dbo].[FlightDetails] fd ON fcb.FlightId = fd.Id
            LEFT JOIN [dbo].[OrderMaster] om ON fd.OrderId = om.Id
            WHERE 
                fcb.IsActive = 1
                AND (@FromDate IS NULL OR CAST(fd.CreatedDate AS DATE) >= CAST(@FromDate AS DATE))
                AND (@ToDate IS NULL OR CAST(fd.CreatedDate AS DATE) <= CAST(@ToDate AS DATE))
                AND (@DepartmentId IS NULL OR @DepartmentId = 0 OR om.ResturantId = @DepartmentId OR (om.Id IS NULL AND fd.CreatedBy IS NOT NULL))
                -- AND (@OrderStatus IS NULL OR om.OrderStatus = @OrderStatus OR om.Id IS NULL)
                AND (@OrderNo IS NULL OR om.JobRefNo LIKE '%' + @OrderNo + '%' OR fd.SlipCode LIKE '%' + @OrderNo + '%')
                AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
                AND (@PaymentStatus IS NULL OR om.IsPaymentCollected = @PaymentStatus)
                AND (@CustomerName IS NULL OR om.CustomerName LIKE '%' + @CustomerName + '%' OR fcb.PassengerName LIKE '%' + @CustomerName + '%')
                AND (@SearchTerm IS NULL OR fcb.BankName LIKE '%' + @SearchTerm + '%' OR fcb.CardProduct LIKE '%' + @SearchTerm + '%')
            GROUP BY fcb.BankName, fcb.CardProduct

            UNION

            SELECT om.BankName, om.CardType
            FROM [dbo].[OrderMaster] om
            WHERE 
                om.BankName IS NOT NULL
                AND om.IsDeleted = 0
                AND (@FromDate IS NULL OR CAST(om.OrderDate AS DATE) >= CAST(@FromDate AS DATE))
                AND (@ToDate IS NULL OR CAST(om.OrderDate AS DATE) <= CAST(@ToDate AS DATE))
                AND (@DepartmentId IS NULL OR @DepartmentId = 0 OR om.ResturantId = @DepartmentId)
                -- AND (@OrderStatus IS NULL OR om.OrderStatus = @OrderStatus)
                AND (@OrderNo IS NULL OR om.JobRefNo LIKE '%' + @OrderNo + '%')
                AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
                AND (@PaymentStatus IS NULL OR om.IsPaymentCollected = @PaymentStatus)
                AND (@CustomerName IS NULL OR om.CustomerName LIKE '%' + @CustomerName + '%')
                AND (@SearchTerm IS NULL OR om.BankName LIKE '%' + @SearchTerm + '%' OR om.CardType LIKE '%' + @SearchTerm + '%')
            GROUP BY om.BankName, om.CardType
        ) AS InternalCombined
    ) AS FinalCombined;

END

GO

-- Stored Procedure: [Sp_Report_CustomerFeedbackDetailReport]
IF OBJECT_ID('[Sp_Report_CustomerFeedbackDetailReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_CustomerFeedbackDetailReport];
GO
CREATE procedure [dbo].[Sp_Report_CustomerFeedbackDetailReport]
	@OrderNo NVARCHAR(50)
	as
	begin

	select I.ItemDesc as Name,Od.ItemQty as Quantity,cf.OrderNo,
		   OD.CreateDate as Date,om.id as OrderId

		from OrderDetail OD
		join OrderMaster OM on OD.OrderMasterId=OM.Id
		join Item I on OD.ItemId=I.Id
		join CustomerFeedBack cf on OM.id=cf.OrderId
	WHERE cf.OrderNo IS NOT NULL AND cf.OrderNo <> '0'
	and cf.OrderNo = @OrderNo
	order by cf.OrderNo desc;
	end

GO

-- Stored Procedure: [Sp_Report_CustomerFeedbackReport]
IF OBJECT_ID('[Sp_Report_CustomerFeedbackReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_CustomerFeedbackReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_CustomerFeedbackReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Create temp table for filtered results
    CREATE TABLE #FeedbackTemp (
        Day NVARCHAR(20),
        OrderDate DATE,
        OrderNo NVARCHAR(50),
        CustomerName NVARCHAR(100),
        Rating INT,
        FeedBack NVARCHAR(MAX),
        Waiter NVARCHAR(100),
        TableNo NVARCHAR(50),
        OrderID INT
    );

    -- Insert data into temp table with filters
    INSERT INTO #FeedbackTemp
    SELECT 
        DATENAME(WEEKDAY, c.CreatedDate) AS Day,
        CAST(c.CreatedDate AS DATE) AS OrderDate,
        c.OrderNo,
        CASE 
            WHEN om.CustomerName IS NULL OR LTRIM(RTRIM(om.CustomerName)) = 'N/A' THEN '-' 
            ELSE om.CustomerName
        END AS CustomerName,
        ISNULL(c.Rating, 0) AS Rating,
        CASE 
            WHEN c.FeedBackDesc IS NULL OR LTRIM(RTRIM(c.FeedBackDesc)) = 'N/A' THEN '-' 
            ELSE c.FeedBackDesc 
        END AS FeedBack,
        ISNULL(w1.WaiterName, ISNULL(w2.WaiterName, '-')) AS Waiter,
        c.TableNo,
        om.Id AS OrderID
    FROM CustomerFeedBack c
    JOIN OrderMaster om ON c.OrderId = om.Id
    LEFT JOIN Waiter w1 ON om.WaiterId = w1.Id
    LEFT JOIN AssignTable at ON om.TableId = at.TableId
    LEFT JOIN Waiter w2 ON at.WaiterId = w2.Id
    WHERE c.OrderNo IS NOT NULL AND c.OrderNo <> '0'
        AND om.OrderDate >= CAST(@FromDate AS DATE) 
        AND om.OrderDate < DATEADD(DAY, 1, CAST(@ToDate AS DATE))
        AND (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus)
        AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
        AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
        AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
        AND (
            @SearchTerm IS NULL OR
            c.OrderNo LIKE '%' + @SearchTerm + '%' OR
            om.CustomerName LIKE '%' + @SearchTerm + '%' OR
            c.FeedBackDesc LIKE '%' + @SearchTerm + '%' OR
            c.TableNo LIKE '%' + @SearchTerm + '%'
        );

    -- Return paged result
    SELECT *
    FROM #FeedbackTemp
    ORDER BY OrderDate DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Return total count
    SELECT COUNT(*) AS TotalCount FROM #FeedbackTemp;

    DROP TABLE #FeedbackTemp;
END

GO

-- Stored Procedure: [Sp_Report_DeliveryDetailsReport]
IF OBJECT_ID('[Sp_Report_DeliveryDetailsReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_DeliveryDetailsReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_DeliveryDetailsReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Temp table to hold filtered result
    SELECT 
        de.CreatedDate AS Date,
        om.JobRefNo AS OrderNo,
        de.CustomerName,
        de.ContactNo,
        de.Address,
        od.ItemQty AS Quantity,
        om.OrderNetAmount AS NetAmount,
        de.DeliveryCharges,
        dd.DriverName AS Driver,
        ot.OrderType,
        om.Id AS OrderId,
        CASE 
            WHEN de.IsDelivered = 1 THEN 'Delivered'
            WHEN de.IsDelivered = 0 THEN 'Pending'
            WHEN om.IsFinalPaid = 1 THEN 'Payment Received' 
            ELSE 'Unknown'
        END AS Status
    INTO #FilteredResult
    FROM DeliveryDetails de
    JOIN OrderMaster om ON om.Id = de.OrderId
    JOIN DriverDetail dd ON de.RiderId = dd.Id 
    JOIN OrderType ot ON de.OrderType = ot.OrderTypeId
    JOIN OrderDetail od ON de.Id = od.Id
    WHERE 
        om.CreateDate >= @FromDate AND om.CreateDate <= @ToDate
        AND (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus)
        AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
        AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
        AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
        AND (
            @SearchTerm IS NULL OR
            de.CustomerName LIKE '%' + @SearchTerm + '%' OR
            de.ContactNo LIKE '%' + @SearchTerm + '%' OR
            om.JobRefNo LIKE '%' + @SearchTerm + '%'
        );

    -- Paged result
    SELECT *
    FROM #FilteredResult
    ORDER BY Date DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Total count
    SELECT COUNT(*) AS TotalCount FROM #FilteredResult;

    DROP TABLE IF EXISTS #FilteredResult;
END

GO

-- Stored Procedure: [SP_Report_DepartmentSummary]
IF OBJECT_ID('[SP_Report_DepartmentSummary]', 'P') IS NOT NULL DROP PROCEDURE [SP_Report_DepartmentSummary];
GO

CREATE Procedure [dbo].[SP_Report_DepartmentSummary]  

    @FromDate datetime,
    @ToDate datetime,
    @ReportName NVARCHAR(255) = NULL,  -- Make parameters optional (default to NULL)
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL
AS  
Begin  
	Select p.PrinterName Department, Sum(om.OrderAmount) OrderAmount, Sum(om.OrderDiscount) OrderDiscount, Sum(om.TaxAmount) TaxAmount, Sum(om.OrderNetAmount) OrderNetAmount
	from PrinterCategory p
	join OrderDetail od ON od.Categoryid = p.CategoryId
	join OrderMaster om ON om.Id = od.OrderMasterId
	join OrderStatus o on om.OrderStatusId=o.Id
	Where p.IsActive = 1 and om.IsActive = 1
			AND OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate
			AND (@OrderStatus IS NULL OR o.Status = @OrderStatus)  
			AND (@PaymentStatus IS NULL OR om.IsPaymentCollected = @PaymentStatus)
			AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
			AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
			AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
	Group BY p.PrinterName
End

GO

-- Stored Procedure: [SP_Report_FOCFinancialReport]
IF OBJECT_ID('[SP_Report_FOCFinancialReport]', 'P') IS NOT NULL DROP PROCEDURE [SP_Report_FOCFinancialReport];
GO

CREATE   PROCEDURE [dbo].[SP_Report_FOCFinancialReport]
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(10) = NULL,
    @FromDate DATETIME,
    @ToDate DATETIME,
    @OrderNo NVARCHAR(255) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(255) = NULL,
    @SearchTerm NVARCHAR(500) = NULL,
    @DepartmentId INT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        om.OrderDate AS [RawDate],
        r.RestaurantName AS [LoungeName],
        d.DepartmentName AS [Department],
        om.CustomerName AS [PersonName],
        i.ItemDesc AS [ItemName],
        od.ItemQty AS [Quantity],
        --ir.NewRate AS [UnitCost],
        --(od.ItemQty * ir.NewRate) AS [TotalCost],
		ISNULL(ir.NewRate,0) AS [UnitCost],
        (od.ItemQty * ISNULL(ir.NewRate,0)) AS [TotalCost],
        om.ReferenceName AS [Reference]
    INTO #FOCFinancialResult
    FROM OrderMaster om WITH (NOLOCK)
    LEFT JOIN OrderType ot WITH (NOLOCK) ON om.OrderTypeId = ot.OrderTypeId
    LEFT JOIN Restaurant r WITH (NOLOCK) ON om.ResturantId = r.Id
    LEFT JOIN Department d WITH (NOLOCK) ON om.DepartmentId = d.DepartmentId
    -- LEFT JOIN UserDetail ud WITH (NOLOCK) ON om.CreatedBy = ud.Id
    LEFT JOIN OrderDetail od WITH (NOLOCK) ON om.Id = od.OrderMasterId
    LEFT JOIN Item i WITH (NOLOCK) ON od.ItemId = i.Id
    LEFT JOIN ItemRate ir WITH (NOLOCK) ON od.ItemId = ir.ItemId
    WHERE 
        om.CreateDate >= CAST(@FromDate AS DATE) 
        AND om.CreateDate < DATEADD(DAY, 1, CAST(@ToDate AS DATE))
        AND om.IsDeleted = 0
        AND od.IsDeleted = 0
        AND ot.OrderType IN ('FOC', 'Staff')
        AND (ISNULL(@DepartmentId, 0) = 0 OR om.DepartmentId = @DepartmentId)
        AND (ISNULL(@OrderTypeId, 0) = 0 OR om.OrderTypeId = @OrderTypeId)
        AND (ISNULL(@OrderNo, '') = '' OR om.JobRefNo LIKE '%' + @OrderNo + '%')
        AND (ISNULL(@CustomerName, '') = '' OR om.CustomerName LIKE '%' + @CustomerName + '%')
        AND (ISNULL(@SearchTerm, '') = '' OR (
            i.ItemDesc LIKE '%' + @SearchTerm + '%' OR 
            d.DepartmentName LIKE '%' + @SearchTerm + '%' OR 
            om.CustomerName LIKE '%' + @SearchTerm + '%'
        ));

    -- Pagination
    SELECT 
        REPLACE(CONVERT(VARCHAR(11), [RawDate], 106),' ','-') AS [Date],
        [LoungeName],
        [Department],
        [PersonName],
        [ItemName],
        [Quantity],
        [UnitCost],
        [TotalCost],
        [Reference]
    FROM #FOCFinancialResult
    ORDER BY [RawDate] DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS 
    FETCH NEXT @PageSize ROWS ONLY;

    SELECT COUNT(*) AS TotalCount FROM #FOCFinancialResult;

    DROP TABLE #FOCFinancialResult;
END

GO

-- Stored Procedure: [Sp_Report_FOCOrders]
IF OBJECT_ID('[Sp_Report_FOCOrders]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_FOCOrders];
GO
CREATE PROCEDURE [dbo].[Sp_Report_FOCOrders]  
                                                                                                                                                                                                               
    @FromDate DATETIME,  
                                                                                                                                                                                                                                    
    @ToDate DATETIME,  
                                                                                                                                                                                                                                      
    @ReportName NVARCHAR(255) = NULL,  
                                                                                                                                                                                                                      
    @OrderStatus NVARCHAR(50) = NULL,  
                                                                                                                                                                                                                      
    @IsWeb NVARCHAR(50) = NULL,  
                                                                                                                                                                                                                            
    @OrderNo NVARCHAR(50) = NULL,  
                                                                                                                                                                                                                          
    @OrderTypeId INT = NULL,  
                                                                                                                                                                                                                               
    @PaymentStatus NVARCHAR(50) = NULL,  
                                                                                                                                                                                                                    
    @CustomerName NVARCHAR(100) = NULL,  
                                                                                                                                                                                                                    
    @SearchTerm NVARCHAR(100) = NULL,  
                                                                                                                                                                                                                      
    @DepartmentId INT = NULL,
                                                                                                                                                                                                                                
    @PageNumber INT = 1,  
                                                                                                                                                                                                                                   
    @PageSize INT = 10  
                                                                                                                                                                                                                                     
AS  
                                                                                                                                                                                                                                                         
BEGIN  
                                                                                                                                                                                                                                                      
    SET NOCOUNT ON;  
                                                                                                                                                                                                                                        

                                                                                                                                                                                                                                                             
    SELECT   
                                                                                                                                                                                                                                                
        om.JobRefNo AS [OrderNo1],  
                                                                                                                                                                                                                         
        ot.OrderType AS [OrderType],  
                                                                                                                                                                                                                       
        om.OrderDate AS [Date],  
                                                                                                                                                                                                                            
        om.OrderDate AS [Time],  
                                                                                                                                                                                                                            
        ud.Fname AS [FOCBy],  
                                                                                                                                                                                                                               
        om.CustomerName AS [FOCTo],  
                                                                                                                                                                                                                        
        SUM(ISNULL(od.ItemQty,0)) AS [TotalItems],  
                                                                                                                                                                                                         
        STRING_AGG('(' + CAST(ISNULL(od.ItemQty,0) AS VARCHAR(50)) + ') ' + ISNULL(i.ItemDesc,''), ', ') AS [ItemNames],
                                                                                                                                     
        d.DepartmentName AS DepartmentName
                                                                                                                                                                                                                   
    INTO #FOCOrders  
                                                                                                                                                                                                                                        
    FROM OrderMaster om  
                                                                                                                                                                                                                                    
    INNER JOIN OrderType ot 
                                                                                                                                                                                                                                 
        ON om.OrderTypeId = ot.OrderTypeId  
                                                                                                                                                                                                                 
    LEFT JOIN UserDetail ud 
                                                                                                                                                                                                                                 
        ON om.CreatedBy = ud.Id  
                                                                                                                                                                                                                            

                                                                                                                                                                                                                                                             
    LEFT JOIN OrderDetail od 
                                                                                                                                                                                                                                
        ON om.Id = od.OrderMasterId
                                                                                                                                                                                                                          
        AND od.IsActive = 1
                                                                                                                                                                                                                                  
        AND od.IsDeleted = 0  
                                                                                                                                                                                                                               

                                                                                                                                                                                                                                                             
    LEFT JOIN Item i 
                                                                                                                                                                                                                                        
        ON od.ItemId = i.Id  
                                                                                                                                                                                                                                

                                                                                                                                                                                                                                                             
    LEFT JOIN Department d 
                                                                                                                                                                                                                                  
        ON om.DepartmentId = d.DepartmentId
                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
    WHERE om.IsActive = 0  
                                                                                                                                                                                                                                  
    AND om.IsDeleted = 0  
                                                                                                                                                                                                                                   
    AND ot.OrderType IN ('FOC','Staff')  
                                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
    AND om.OrderDate >= CAST(@FromDate AS DATE)   
                                                                                                                                                                                                          
    AND om.OrderDate < DATEADD(DAY,1,CAST(@ToDate AS DATE))   
                                                                                                                                                                                              

                                                                                                                                                                                                                                                             
    AND (ISNULL(@OrderNo,'') = '' 
                                                                                                                                                                                                                           
         OR om.JobRefNo LIKE '%' + @OrderNo + '%')
                                                                                                                                                                                                           

                                                                                                                                                                                                                                                             
    AND (ISNULL(@OrderTypeId,0) = 0 
                                                                                                                                                                                                                         
         OR om.OrderTypeId = @OrderTypeId)
                                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
    AND (ISNULL(@CustomerName,'') = '' 
                                                                                                                                                                                                                      
         OR om.CustomerName LIKE '%' + @CustomerName + '%')
                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
    AND (ISNULL(@DepartmentId,'') = '' 
                                                                                                                                                                                                                      
         OR om.DepartmentId = TRY_CAST(@DepartmentId AS INT))
                                                                                                                                                                                                

                                                                                                                                                                                                                                                             
    AND (ISNULL(@SearchTerm,'') = '' 
                                                                                                                                                                                                                        
         OR om.JobRefNo LIKE '%' + @SearchTerm + '%'
                                                                                                                                                                                                         
         OR om.CustomerName LIKE '%' + @SearchTerm + '%'
                                                                                                                                                                                                     
         OR ud.Fname LIKE '%' + @SearchTerm + '%'
                                                                                                                                                                                                            
         OR i.ItemDesc LIKE '%' + @SearchTerm + '%')
                                                                                                                                                                                                         

                                                                                                                                                                                                                                                             
    GROUP BY   
                                                                                                                                                                                                                                              
        om.JobRefNo,  
                                                                                                                                                                                                                                       
        ot.OrderType,  
                                                                                                                                                                                                                                      
        om.OrderDate,  
                                                                                                                                                                                                                                      
        ud.Fname,  
                                                                                                                                                                                                                                          
        om.CustomerName,
                                                                                                                                                                                                                                     
        d.DepartmentName;  
                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                             
    SELECT   
                                                                                                                                                                                                                                                
        ISNULL([OrderNo1], '-') AS [OrderNo1],  
                                                                                                                                                                                                             
        ISNULL([OrderType], '-') AS [OrderType],  
                                                                                                                                                                                                           
        ISNULL(CONVERT(VARCHAR(19), [Date], 120), '-') AS [Date],  
                                                                                                                                                                                          
        ISNULL(CONVERT(VARCHAR(19), [Time], 120), '-') AS [Time],  
                                                                                                                                                                                          
        ISNULL([FOCBy], '-') AS [FOCBy],  
                                                                                                                                                                                                                   
        ISNULL([FOCTo], '-') AS [FOCTo],  
                                                                                                                                                                                                                   
        ISNULL(CAST([TotalItems] AS VARCHAR), '-') AS [TotalItems],  
                                                                                                                                                                                        
        ISNULL([ItemNames], '-') AS [ItemNames],
                                                                                                                                                                                                             
        ISNULL([DepartmentName], '-') AS [DepartmentName]
                                                                                                                                                                                                    
    FROM #FOCOrders  
                                                                                                                                                                                                                                        
    ORDER BY [Date] DESC  
                                                                                                                                                                                                                                   
    OFFSET (@PageNumber - 1) * @PageSize ROWS  
                                                                                                                                                                                                              
    FETCH NEXT @PageSize ROWS ONLY;  
                                                                                                                                                                                                                        

                                                                                                                                                                                                                                                             
    SELECT COUNT(*) AS TotalCount FROM #FOCOrders;  
                                                                                                                                                                                                         

                                                                                                                                                                                                                                                             
    DROP TABLE IF EXISTS #FOCOrders;  
                                                                                                                                                                                              
END                                                                                                                                                                                                                       

GO

-- Stored Procedure: [Sp_Report_OrdersSummery]
IF OBJECT_ID('[Sp_Report_OrdersSummery]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_OrdersSummery];
GO
CREATE PROCEDURE [dbo].[Sp_Report_OrdersSummery]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @OrderTypeId INT = NULL,
    @ReportName NVARCHAR(255) = NULL,  
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
	@DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Put result into temp table
    SELECT 
        ot.OrderType,
        COUNT(DISTINCT om.Id) AS TotalOrders,
        SUM(od.ItemQty) AS TotalItems
    INTO #OrderSummeryResult
    FROM OrderMaster om
    INNER JOIN OrderType ot ON om.OrderTypeId = ot.OrderTypeId
    LEFT JOIN OrderDetail od ON om.Id = od.OrderMasterId
    WHERE 
        om.CreateDate >= CAST(@FromDate AS DATE) 
        AND om.CreateDate < DATEADD(DAY, 1, CAST(@ToDate AS DATE))
        AND om.IsActive = 1 
        AND om.IsDeleted = 0
        AND (od.IsActive = 1 AND od.IsDeleted = 0)
        AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
        --AND (
        --    @SearchTerm IS NULL OR
        --    ot.OrderType LIKE '%' + @SearchTerm + '%' OR
        --    om.CustomerName LIKE '%' + @SearchTerm + '%' OR
        --    om.OrderNo LIKE '%' + @SearchTerm + '%'
        --)
    GROUP BY ot.OrderTypeId, ot.OrderType;

    -- Apply pagination
    SELECT 
        OrderType, TotalOrders, TotalItems
    FROM #OrderSummeryResult
    ORDER BY OrderType
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Return total count
    SELECT COUNT(*) AS TotalCount FROM #OrderSummeryResult;

    DROP TABLE IF EXISTS #OrderSummeryResult;
END


GO

-- Stored Procedure: [Sp_Report_OrderSummeryReport]
IF OBJECT_ID('[Sp_Report_OrderSummeryReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_OrderSummeryReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_OrderSummeryReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @DepartmentId INT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        ot.OrderType,
        COUNT(om.Id) AS TotalOrders,
        CAST(SUM(ISNULL(sub.TotalItems, 0)) AS INT) AS TotalItems
    INTO #OrderSummery
    FROM OrderMaster om
    JOIN OrderType ot ON om.OrderTypeId = ot.OrderTypeId
    LEFT JOIN (
        SELECT OrderMasterId, SUM(ItemQty) AS TotalItems
        FROM OrderDetail
        WHERE IsActive = 1 AND IsDeleted = 0
        GROUP BY OrderMasterId
    ) sub ON om.Id = sub.OrderMasterId
    WHERE om.IsActive = 1 AND om.IsDeleted = 0
    AND om.OrderDate >= CAST(@FromDate AS DATE)
    AND om.OrderDate < DATEADD(DAY, 1, CAST(@ToDate AS DATE))
    AND (ISNULL(@OrderTypeId, 0) = 0 OR om.OrderTypeId = @OrderTypeId)
    AND (ISNULL(@SearchTerm, '') = '' OR ot.OrderType LIKE '%' + @SearchTerm + '%')
    GROUP BY ot.OrderType;

    -- Return Paged Result
    SELECT 
        OrderType,
        TotalOrders,
        TotalItems
    FROM #OrderSummery
    ORDER BY TotalOrders DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Return Total Count
    SELECT COUNT(*) AS TotalCount FROM #OrderSummery;

    DROP TABLE #OrderSummery;
END

GO

-- Stored Procedure: [Sp_Report_PartOfDaySellsReport]
IF OBJECT_ID('[Sp_Report_PartOfDaySellsReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_PartOfDaySellsReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_PartOfDaySellsReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    WITH PartOfDayData AS (
        SELECT 
            -- Updated time slot ranges
            CASE 
                WHEN DATEPART(HOUR, om.CreateDate) BETWEEN 0 AND 11 THEN 'Morning (00:00 to 11:59)'
                WHEN DATEPART(HOUR, om.CreateDate) BETWEEN 12 AND 17 THEN 'Afternoon (12:00 to 17:59)'
                ELSE 'Evening (18:00 to 23:59)'
            END AS PartOfDay,

            DATENAME(WEEKDAY, om.CreateDate) AS DayOfWeek,
            DATEPART(WEEKDAY, om.CreateDate) AS DayOrder,

            SUM(od.ItemQty) AS ItemsSold,
            COUNT(Distinct om.Id) AS Orders
        FROM 
            OrderMaster om
        JOIN OrderDetail od ON om.Id = od.OrderMasterId
		--JOIN OrderStatus o ON om.OrderStatusId = o.Id

        WHERE 
            om.IsActive = 1 AND om.IsDeleted = 0 AND
            od.IsActive = 1 AND od.IsDeleted = 0
            AND OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate
			--AND (@OrderStatus IS NULL OR o.Status = @OrderStatus)  
			AND (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus)
			AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
			AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
			AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
        GROUP BY 
            CASE 
                WHEN DATEPART(HOUR, om.CreateDate) BETWEEN 0 AND 11 THEN 'Morning (00:00 to 11:59)'
                WHEN DATEPART(HOUR, om.CreateDate) BETWEEN 12 AND 17 THEN 'Afternoon (12:00 to 17:59)'
                ELSE 'Evening (18:00 to 23:59)'
            END,
            DATENAME(WEEKDAY, om.CreateDate),
            DATEPART(WEEKDAY, om.CreateDate)
    )

    SELECT 
        PartOfDay,
        DayOfWeek,
        ItemsSold,
        Orders
    FROM PartOfDayData
    ORDER BY
        DayOrder,
        CASE 
            WHEN PartOfDay LIKE 'Morning%' THEN 1
            WHEN PartOfDay LIKE 'Afternoon%' THEN 2
            WHEN PartOfDay LIKE 'Evening%' THEN 3
        END;
END

GO

-- Stored Procedure: [Sp_Report_ReportByWaiter]
IF OBJECT_ID('[Sp_Report_ReportByWaiter]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_ReportByWaiter];
GO
CREATE PROCEDURE [dbo].[Sp_Report_ReportByWaiter]
                                                                                                                                                                                                            
    @FromDate DATETIME,
                                                                                                                                                                                                                                      
    @ToDate DATETIME,
                                                                                                                                                                                                                                        
    @ReportName NVARCHAR(255) = NULL,
                                                                                                                                                                                                                        
    @OrderStatus NVARCHAR(50) = NULL,
                                                                                                                                                                                                                        
    @IsWeb NVARCHAR(50) = NULL,
                                                                                                                                                                                                                              
    @OrderNo NVARCHAR(50) = NULL,
                                                                                                                                                                                                                            
    @OrderTypeId INT = NULL,
                                                                                                                                                                                                                                 
    @PaymentStatus NVARCHAR(50) = NULL,
                                                                                                                                                                                                                      
    @CustomerName NVARCHAR(100) = NULL,
                                                                                                                                                                                                                      
    @SearchTerm NVARCHAR(100) = NULL,
                                                                                                                                                                                                                        
	@DepartmentId NVARCHAR(100) = NULL,
                                                                                                                                                                                                                         
    @PageNumber INT = 1,
                                                                                                                                                                                                                                     
    @PageSize INT = 10
                                                                                                                                                                                                                                       
AS
                                                                                                                                                                                                                                                           
BEGIN
                                                                                                                                                                                                                                                        
    -- Temp table for search and pagination
                                                                                                                                                                                                                  
    CREATE TABLE #WaiterReportTemp (
                                                                                                                                                                                                                         
        JobRefNo NVARCHAR(100),
                                                                                                                                                                                                                              
        Waiter NVARCHAR(100),
                                                                                                                                                                                                                                
        OrderDate DATETIME,
                                                                                                                                                                                                                                  
        OrderId INT,
                                                                                                                                                                                                                                         
        OrderType NVARCHAR(100),
                                                                                                                                                                                                                             
        TableNo NVARCHAR(100)
                                                                                                                                                                                                                                
    );
                                                                                                                                                                                                                                                       

                                                                                                                                                                                                                                                             
    INSERT INTO #WaiterReportTemp
                                                                                                                                                                                                                            
    SELECT 
                                                                                                                                                                                                                                                  
        om.JobRefNo,
                                                                                                                                                                                                                                         
        ISNULL(w1.WaiterName, ISNULL(w2.WaiterName, '-')) AS Waiter,
                                                                                                                                                                                         
        om.CreateDate AS OrderDate,
                                                                                                                                                                                                                          
        om.Id AS OrderId,
                                                                                                                                                                                                                                    
        ot.OrderType,
                                                                                                                                                                                                                                        
        CASE 
                                                                                                                                                                                                                                                
            WHEN At.TableNo IS NULL OR LTRIM(RTRIM(At.TableNo)) = 'N/A' THEN '-' 
                                                                                                                                                                            
            ELSE At.TableNo
                                                                                                                                                                                                                                  
        END AS TableNo
                                                                                                                                                                                                                                       
    FROM OrderMaster om
                                                                                                                                                                                                                                      
    LEFT JOIN Waiter w1 ON om.WaiterId = w1.Id
                                                                                                                                                                                                               
    LEFT JOIN AssignTable at ON om.TableId = at.TableId
                                                                                                                                                                                                      
    LEFT JOIN Waiter w2 ON at.WaiterId = w2.Id
                                                                                                                                                                                                               
    JOIN OrderType ot ON om.OrderTypeId = ot.OrderTypeId
                                                                                                                                                                                                     
    -- JOIN OrderStatus o ON om.OrderStatusId = o.Id
                                                                                                                                                                                                         
    WHERE 
                                                                                                                                                                                                                                                   
        ot.OrderTypeId NOT IN (6, 7, 8, 9, 11, 12, 13)
                                                                                                                                                                                                              
        AND om.CreateDate >= @FromDate AND om.CreateDate <= @ToDate
                                                                                                                                                                                          
        -- AND (@OrderStatus IS NULL OR o.Status = @OrderStatus)
                                                                                                                                                                                             
        AND (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus)
                                                                                                                                                                                      
        AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
                                                                                                                                                                                          
        AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
                                                                                                                                                                                                        
        AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
                                                                                                                                                                                       
        AND (
                                                                                                                                                                                                                                                
            @SearchTerm IS NULL OR 
                                                                                                                                                                                                                          
            ISNULL(w1.WaiterName, '') LIKE '%' + @SearchTerm + '%' OR 
                                                                                                                                                                                       
            ISNULL(w2.WaiterName, '') LIKE '%' + @SearchTerm + '%'or
                                                                                                                                                                                         
			ISNULL(om.JobRefNo,'') LiKE '%'+ @SearchTerm+ '%'
                                                                                                                                                                                                         
        );
                                                                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
    -- Paged result
                                                                                                                                                                                                                                          
    SELECT *
                                                                                                                                                                                                                                                 
    FROM #WaiterReportTemp
                                                                                                                                                                                                                                   
    ORDER BY OrderDate DESC
                                                                                                                                                                                                                                  
    OFFSET (@PageNumber - 1) * @PageSize ROWS
                                                                                                                                                                                                                
    FETCH NEXT @PageSize ROWS ONLY;
                                                                                                                                                                                                                          

                                                                                                                                                                                                                                                             
    -- Total count
                                                                                                                                                                                                                                           
    SELECT COUNT(*) AS TotalCount FROM #WaiterReportTemp;
                                                                                                                                                                                                    

                                                                                                                                                                                                                                                             
    DROP TABLE #WaiterReportTemp;
                                                                                                                                                                                                                            
END
                                                                                                                                                                                                                                                          

GO

-- Stored Procedure: [Sp_Report_RiderDetails]
IF OBJECT_ID('[Sp_Report_RiderDetails]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_RiderDetails];
GO
CREATE procedure [dbo].[Sp_Report_RiderDetails]
@FromDate datetime,
    @ToDate datetime,
    @ReportName NVARCHAR(255) = NULL,  -- Make parameters optional (default to NULL)
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
as
	begin

	select 
	   om.CreateDate as Date,
	   om.JobRefNo as Orders,
	   ot.OrderType,
	   dd.DriverName,
	  om.Id as OrderId
	 
	   INTO #RiderDetails
from DeliveryDetails de
join OrderMaster om on om.Id=de.OrderId
join DriverDetail dd on de.RiderId=dd.Id 
join OrderType ot on de.OrderType=ot.OrderTypeId
join OrderDetail od on de.Id=od.Id
--join OrderStatus o on om.OrderStatusId=o.Id
 where 
						
						OM.IsActive=1
						and OD.IsActive=1
						and OM.IsDeleted=0
						and OD.IsDeleted=0
						AND OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate
						--AND (@OrderStatus IS NULL OR o.Status = @OrderStatus)  
						AND (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus)
						AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
						AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
						AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
						AND(@SearchTerm IS NULL OR 
						dd.DriverName Like '%' +@SearchTerm + '%' OR
						om.JobRefNo Like '%'+ @SearchTerm + '%'
						
						);
					
	select 
	Date,Orders,OrderType,DriverName,OrderId 
	from #RiderDetails
		order by Date desc
		OFFSET (@PageNumber - 1)*@PageSize ROWS
			fetch next @PageSize Rows ONLY;
			
				select COUNT(*) As TotalCount From #RiderDetails;

				Drop table if exists #RiderDetails;

	
								end 

GO

-- Stored Procedure: [Sp_Report_RiderSummaryReport]
IF OBJECT_ID('[Sp_Report_RiderSummaryReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_RiderSummaryReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_RiderSummaryReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Temp table to hold grouped data
    SELECT 
        dd.DriverName AS RiderName,
        dd.CellNo,
        COUNT(om.Id) AS TotalDeliveries,
        SUM(om.OrderNetAmount) AS TotalSales
    INTO #RiderSummary
    FROM DeliveryDetails de
    JOIN OrderMaster om ON om.Id = de.OrderId
    JOIN DriverDetail dd ON de.RiderId = dd.Id 
    JOIN OrderType ot ON de.OrderType = ot.OrderTypeId
    JOIN OrderDetail od ON de.Id = od.Id
    WHERE 
        OM.IsActive = 1 AND OM.IsDeleted = 0 AND
        OD.IsActive = 1 AND OD.IsDeleted = 0 AND
        OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate AND
        (@PaymentStatus IS NULL OR om.IsFinalPaid = @PaymentStatus) AND
        (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId) AND
        (@IsWeb IS NULL OR om.OrderFrom = @IsWeb) AND
        (@CustomerName IS NULL OR om.CustomerName = @CustomerName) AND
        (
            @SearchTerm IS NULL OR
            dd.DriverName LIKE '%' + @SearchTerm + '%' OR
            dd.CellNo LIKE '%' + @SearchTerm + '%'
        )
    GROUP BY 
        dd.DriverName, dd.CellNo;

    -- Paginated result
    SELECT 
        RiderName,
        CellNo,
        TotalDeliveries,
        TotalSales
    FROM #RiderSummary
    ORDER BY TotalDeliveries DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Total count for pagination
    SELECT COUNT(*) AS TotalCount FROM #RiderSummary;

    DROP TABLE IF EXISTS #RiderSummary;
END

GO

-- Stored Procedure: [Sp_Report_SaleByItemReport]
IF OBJECT_ID('[Sp_Report_SaleByItemReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_SaleByItemReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_SaleByItemReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Main paged result using CTE
    WITH CTE_Report AS (
        SELECT 
            I.Id,
            I.ItemDesc,
            MIN(OD.Rate) AS Amount,
            SUM(OD.ItemQty) AS ItemSold,
            SUM(OD.Amount) AS TotalAmount,
			CASE 
    WHEN @OrderTypeId IS NOT NULL AND OM.OrderTypeId = @OrderTypeId 
    THEN Ot.OrderType 
    ELSE '-' 
END AS OrderType
        FROM OrderDetail OD
        JOIN Item I ON OD.ItemId = I.Id
        JOIN OrderMaster OM ON OD.OrderMasterId = OM.Id
		JOIN OrderType ot on om.OrderTypeId=ot.OrderTypeId
        WHERE 
            OD.IsActive = 1 AND OD.IsDeleted = 0 AND I.IsDeleted = 0
            AND OD.CreateDate BETWEEN @FromDate AND @ToDate
            AND (@OrderTypeId IS NULL OR OM.OrderTypeId = @OrderTypeId)
            AND (@IsWeb IS NULL OR OM.OrderFrom = @IsWeb)
            AND (@CustomerName IS NULL OR OM.CustomerName = @CustomerName)
        AND (
    @SearchTerm IS NULL OR
    I.ItemDesc LIKE '%' + @SearchTerm + '%' OR
	I.Id LIKE '%'+@SearchTerm +'%'OR
    --OM.OrderNo LIKE '%' + @SearchTerm + '%' OR
    OM.CustomerName LIKE '%' + @SearchTerm + '%' 
   -- OM.ContactNo LIKE '%' + @SearchTerm + '%' OR
   -- OM.TableNo LIKE '%' + @SearchTerm + '%'
)
        GROUP BY I.Id, I.ItemDesc,om.OrderTypeId,ot.OrderType
    )
    SELECT * FROM CTE_Report
    ORDER BY TotalAmount DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Return total count for pagination
    SELECT COUNT(*) AS TotalCount FROM (
        SELECT 1 AS DummyColumn
        FROM OrderDetail OD
        JOIN Item I ON OD.ItemId = I.Id
        JOIN OrderMaster OM ON OD.OrderMasterId = OM.Id
        WHERE 
            OD.IsActive = 1 AND OD.IsDeleted = 0 AND I.IsDeleted = 0
            AND OD.CreateDate BETWEEN @FromDate AND @ToDate
            AND (@OrderTypeId IS NULL OR OM.OrderTypeId = @OrderTypeId)
            AND (@IsWeb IS NULL OR OM.OrderFrom = @IsWeb)
            AND (@CustomerName IS NULL OR OM.CustomerName = @CustomerName)
            AND (@SearchTerm IS NULL OR I.ItemDesc LIKE '%' + @SearchTerm + '%')
        GROUP BY I.Id, I.ItemDesc
    ) AS CountTable;
END

GO

-- Stored Procedure: [Sp_Report_SalesByCategoryReport]
IF OBJECT_ID('[Sp_Report_SalesByCategoryReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_SalesByCategoryReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_SalesByCategoryReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    -- Temporary table to hold grouped data
    CREATE TABLE #CategorySalesTemp (
        CategoryId INT,
        CategoryName NVARCHAR(255),
        TotalItems INT,
        TotalAmount DECIMAL(18, 2)
    );

    -- Insert filtered + grouped data
    INSERT INTO #CategorySalesTemp (CategoryId, CategoryName, TotalItems, TotalAmount)
    SELECT
        c.Id AS CategoryId,
        c.CategoryDesc AS CategoryName,
        SUM(od.ItemQty) AS TotalItems,
        SUM(od.Amount) AS TotalAmount
    FROM OrderDetail od
    INNER JOIN Category c ON od.CategoryId = c.Id
    INNER JOIN OrderMaster om ON od.OrderMasterId = om.Id
    -- LEFT JOIN OrderStatus o ON om.OrderStatusId = o.Id
    WHERE 
        od.IsActive = 1
        AND od.IsDeleted = 0
        AND om.IsDeleted = 0
        AND om.IsActive = 1
        AND om.CreateDate >= @FromDate AND om.CreateDate <= @ToDate
        -- AND (@OrderStatus IS NULL OR o.Status = @OrderStatus)
        --AND (@PaymentStatus IS NULL OR 
        --     (@PaymentStatus = 'Paid' AND om.IsFinalPaid = 1) OR 
        --     (@PaymentStatus = 'Unpaid' AND om.IsFinalPaid = 0))
        AND (@OrderTypeId IS NULL OR om.OrderTypeId = @OrderTypeId)
        AND (@IsWeb IS NULL OR om.OrderFrom = @IsWeb)
        AND (@CustomerName IS NULL OR om.CustomerName = @CustomerName)
        --AND (@OrderNo IS NULL OR om.OrderNo = @OrderNo)
        AND (
            @SearchTerm IS NULL OR
            c.CategoryDesc LIKE '%' + @SearchTerm + '%' OR
            c.Id LIKE '%' + @SearchTerm + '%'
        )
    GROUP BY 
        c.Id, c.CategoryDesc;

    -- Return paged result
    SELECT *
    FROM #CategorySalesTemp
    ORDER BY TotalItems DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Return total count
    SELECT COUNT(*) AS TotalCount FROM #CategorySalesTemp;

    -- Clean up
    DROP TABLE #CategorySalesTemp;
END

GO

-- Stored Procedure: [Sp_Report_TopSellingItemsByWeekDay]
IF OBJECT_ID('[Sp_Report_TopSellingItemsByWeekDay]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_TopSellingItemsByWeekDay];
GO
CREATE PROCEDURE [dbo].[Sp_Report_TopSellingItemsByWeekDay]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
	@DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Step 1: Generate list of dates
    WITH DateRange AS (
        SELECT CAST(@FromDate AS DATE) AS TheDate
        UNION ALL
        SELECT DATEADD(DAY, 1, TheDate)
        FROM DateRange
        WHERE DATEADD(DAY, 1, TheDate) <= @ToDate
    )
    SELECT * INTO #TempDateRange FROM DateRange
    OPTION (MAXRECURSION 10000);

    -- Step 2: Day passed count
    WITH DayPassedCount AS (
        SELECT 
            DATENAME(WEEKDAY, TheDate) AS DayName,
            COUNT(*) AS DayPassed
        FROM #TempDateRange
        GROUP BY DATENAME(WEEKDAY, TheDate)
    ),

    -- Step 3: Item sales
    ItemSales AS (
        SELECT 
            DATENAME(WEEKDAY, OM.CreateDate) AS DayName,
            I.ItemDesc AS ItemName,
            SUM(OD.ItemQty) AS TotalQtySold,
            SUM(OD.Amount) AS TotalAmount
        FROM OrderDetail OD
        INNER JOIN OrderMaster OM ON OD.OrderMasterId = OM.Id
        INNER JOIN Item I ON OD.ItemId = I.Id
        WHERE 
            OD.IsActive = 1 AND OD.IsDeleted = 0 AND
            OM.IsActive = 1 AND OM.IsDeleted = 0 AND
            I.IsDeleted = 0 AND
            OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate
            AND (@PaymentStatus IS NULL OR OM.IsFinalPaid = @PaymentStatus)
            AND (@OrderTypeId IS NULL OR OM.OrderTypeId = @OrderTypeId)
            AND (@IsWeb IS NULL OR OM.OrderFrom = @IsWeb)
            AND (@CustomerName IS NULL OR OM.CustomerName = @CustomerName)
        GROUP BY DATENAME(WEEKDAY, OM.CreateDate), I.ItemDesc
    ),

    -- Step 4: Ranked items
    RankedItems AS (
        SELECT *,
            ROW_NUMBER() OVER (
                PARTITION BY DayName
                ORDER BY TotalQtySold DESC
            ) AS RowRank
        FROM ItemSales
    ),

    -- Step 5: Daily totals
    DailyTotals AS (
        SELECT 
            DATENAME(WEEKDAY, OM.CreateDate) AS DayName,
            COUNT(DISTINCT OM.Id) AS AllOrdersQty,
            SUM(OD.Amount) AS AllOrdersNetAmount
        FROM OrderDetail OD
        INNER JOIN OrderMaster OM ON OD.OrderMasterId = OM.Id
        WHERE 
            OD.IsActive = 1 AND OD.IsDeleted = 0 AND
            OM.IsActive = 1 AND OM.IsDeleted = 0 AND
            OM.CreateDate >= @FromDate AND OM.CreateDate <= @ToDate
            AND (@PaymentStatus IS NULL OR OM.IsFinalPaid = @PaymentStatus)
            AND (@OrderTypeId IS NULL OR OM.OrderTypeId = @OrderTypeId)
            AND (@IsWeb IS NULL OR OM.OrderFrom = @IsWeb)
            AND (@CustomerName IS NULL OR OM.CustomerName = @CustomerName)
        GROUP BY DATENAME(WEEKDAY, OM.CreateDate)
    )

    -- Store final combined data in a temp table
    SELECT 
        DP.DayName,
        DP.DayPassed,
        RI.TotalQtySold AS TopOrderQty,
        RI.ItemName AS TopOrderName,
        DT.AllOrdersQty,
        DT.AllOrdersNetAmount
    INTO #FinalResult
    FROM DayPassedCount DP
    LEFT JOIN RankedItems RI ON DP.DayName = RI.DayName AND RI.RowRank = 1
    LEFT JOIN DailyTotals DT ON DP.DayName = DT.DayName
    WHERE @SearchTerm IS NULL OR RI.ItemName LIKE '%' + @SearchTerm + '%';

    -- Step 6: Paginated result
    SELECT *
    FROM #FinalResult
    ORDER BY 
        CASE 
            WHEN DayName = 'Monday' THEN 1
            WHEN DayName = 'Tuesday' THEN 2
            WHEN DayName = 'Wednesday' THEN 3
            WHEN DayName = 'Thursday' THEN 4
            WHEN DayName = 'Friday' THEN 5
            WHEN DayName = 'Saturday' THEN 6
            WHEN DayName = 'Sunday' THEN 7
        END
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Step 7: Total count for pagination
    SELECT COUNT(*) AS TotalCount FROM #FinalResult;

    -- Step 8: Cleanup
    DROP TABLE IF EXISTS #TempDateRange;
    DROP TABLE IF EXISTS #FinalResult;
END

GO

-- Stored Procedure: [Sp_Report_WaiterOrdersReport]
IF OBJECT_ID('[Sp_Report_WaiterOrdersReport]', 'P') IS NOT NULL DROP PROCEDURE [Sp_Report_WaiterOrdersReport];
GO
CREATE PROCEDURE [dbo].[Sp_Report_WaiterOrdersReport]
    @FromDate DATETIME,
    @ToDate DATETIME,
    @ReportName NVARCHAR(255) = NULL,
    @OrderStatus NVARCHAR(50) = NULL,
    @IsWeb NVARCHAR(50) = NULL,
    @OrderNo NVARCHAR(50) = NULL,
    @OrderTypeId INT = NULL,
    @PaymentStatus NVARCHAR(50) = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @SearchTerm NVARCHAR(100) = NULL,
    @DepartmentId NVARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- Temp table for filtered + grouped results
    CREATE TABLE #WaiterOrdersTemp (
        Waiter NVARCHAR(100),
        TotalOrders INT,
        ItemsSold INT,
        NetAmount DECIMAL(18, 2),
        TotalDiscount DECIMAL(18, 2),
        TotalTax DECIMAL(18, 2)
    );

    INSERT INTO #WaiterOrdersTemp
    SELECT 
        ISNULL(w.WaiterName, '-') AS Waiter,
        COUNT(DISTINCT OM.Id) AS TotalOrders,
        CAST(SUM(ISNULL(OD.ItemQty, 0)) AS INT) AS ItemsSold,
        SUM(ISNULL(OM.OrderNetAmount, 0)) AS NetAmount,
        ROUND(SUM(ISNULL(OM.OrderDiscount, 0)), 0) AS TotalDiscount,
        ROUND(SUM(ISNULL(OM.TaxAmount, 0)), 0) AS TotalTax
    FROM OrderMaster OM
    LEFT JOIN OrderDetail OD ON OD.OrderMasterId = OM.Id AND OD.IsActive = 1 AND OD.IsDeleted = 0
    LEFT JOIN Waiter w ON OM.WaiterId = w.Id
    WHERE OM.IsActive = 0 AND OM.IsDeleted = 0
        AND OM.OrderDate >= CAST(@FromDate AS DATE)
        AND OM.OrderDate < DATEADD(DAY, 1, CAST(@ToDate AS DATE))
        AND (@PaymentStatus IS NULL OR OM.IsFinalPaid = @PaymentStatus)
        AND (@OrderTypeId IS NULL OR OM.OrderTypeId = @OrderTypeId)
        AND (@IsWeb IS NULL OR OM.OrderFrom = @IsWeb)
        AND (@CustomerName IS NULL OR OM.CustomerName = @CustomerName)
    GROUP BY w.WaiterName
    HAVING @SearchTerm IS NULL OR w.WaiterName LIKE '%' + @SearchTerm + '%';

    -- Paged Result
    SELECT *
    FROM #WaiterOrdersTemp
    ORDER BY TotalOrders DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- Total Count
    SELECT COUNT(*) AS TotalCount FROM #WaiterOrdersTemp;

    DROP TABLE #WaiterOrdersTemp;
END

GO

-- Stored Procedure: [SP_SearchItemCate_Dinein]
IF OBJECT_ID('[SP_SearchItemCate_Dinein]', 'P') IS NOT NULL DROP PROCEDURE [SP_SearchItemCate_Dinein];
