CREATE Procedure [dbo].[SP_SearchItemCate_Dinein]
@SearchTerm  varchar(1000)
As
Begin
Select I.Id,SC.CategoryId, I.SubCategoryId,IR.Id RateId,IR.ItemVeriationId,I.ItemDesc,IR.Rate,IV.ItemSize,I.ImageURL from Category C    
Inner Join SubCategory SC On C.Id = SC.CategoryId     
Inner Join Item I On I.SubCategoryId = Sc.Id    and I.isactive = 1 and I.isdeleted = 0
Inner Join ItemRate IR ON I.Id = IR.ItemId    
Inner Join ItemVeriation IV ON IV.Id = IR.ItemVeriationId     
Where  I.ItemDesc Like '%'+ @SearchTerm +'%' OR C.CategoryDesc Like '%'+ @SearchTerm +'%'

Select Distinct C.Id,C.CategoryDesc,C.ShortDesc,C.ImageUrl,C.ResturantId--,SC.Id SubCategoryID         
--,STRING_AGG( ISNULL(SC.Id, ' '), ',') SubCategoryID        
from Category C        
Left Join SubCategory SC On C.Id = SC.CategoryId Where C.Id IN( Select C.Id
from Category C    
Inner Join SubCategory SC On C.Id = SC.CategoryId     
Inner Join Item I On I.SubCategoryId = Sc.Id    
Inner Join ItemRate IR ON I.Id = IR.ItemId    
Inner Join ItemVeriation IV ON IV.Id = IR.ItemVeriationId     
Where  I.ItemDesc Like '%'+@SearchTerm+'%' OR C.CategoryDesc Like '%'+ @SearchTerm +'%')
End

