-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SetShiftClose]
@ShiftId as int,
@ShiftCloseBy as int,
@ShiftCloseDate as date

AS
BEGIN

declare @IsChange bit

   Select @IsChange =ISChange from shiftorderdetail where ShiftIdCollection = @ShiftId and ShiftDate = @ShiftCloseDate and (CloseBy is null or CloseBy = 0)     
   if(@IsChange = 1)          
   begin          
    Set @IsChange = 0          
   End          
   else          
   begin          
    Set @IsChange = 1          
   End          
	
	update shiftorderdetail set CloseBy = @ShiftCloseBy, ShiftCloseDate = @ShiftCloseDate , ischange = @IsChange
	where ShiftIdCollection = @ShiftId and ShiftDate = @ShiftCloseDate and (CloseBy is null or CloseBy = 0)

END

GO

