-- Stored Procedure: [SP_ShiftOrderDetail_Get]
IF OBJECT_ID('[SP_ShiftOrderDetail_Get]', 'P') IS NOT NULL DROP PROCEDURE [SP_ShiftOrderDetail_Get];
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ShiftOrderDetail_Get] 
	-- Add the parameters for the stored procedure here
	@ShiftId as int,
	@ShiftDate as varchar(20)


AS
BEGIN

select top 1 ShiftIdCollection as ShiftId,TotalOrderAmount,isnull(RecAmount,0) as RecAmount,isnull(ExcessAmount,0) as ExcessAmount,isnull(ShortageAmount,0) as ShortageAmount,isnull(CashOrderAmount,0) as CashOrderAmount,isnull(CashTaxAmount,0) as CashTaxAmount,isnull(CardOrderAmount,0) as CardOrderAmount,isnull(CardTaxAmount,0) as CardTaxAmount,
isnull(DiscountAmount,0) as DiscountAmount, isnull(OpeningAmount,0) as OpeningAmount,ShiftRemarks,ShiftDate,ShiftCloseDate, d.denomination5000, d.denomination1000, d.denomination500, d.denomination100, denomination50,
d.denomination20, d.denomination10, d.denomination5, d.denomination2, d.denomination1, d.Total, d.CloseBy, l.UserName,



(select count(*) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 0 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate) as TotalOrder,
(select count(*) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 0 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate and OrderTypeId = 5) as DineInOrder,
(select ISNULL(Sum(ISNULL(OrderNetAmount,0)),0) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 0 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate and OrderTypeId = 5) as DineInOrderAmount,
(select count(*) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 0 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate and OrderTypeId = 6) as TakeawayOrder,
(select ISNULL(Sum(ISNULL(OrderNetAmount,0)),0) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 0 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate and OrderTypeId = 6) as TakeawayOrderAmount,
0 as RoomOrder,
0 as RoomOrderAmount,
(select count(*) from OrderMaster where  IsDeleted = 1 and isPaymentCollected = 0 and ShiftIdCollection = @ShiftId and Format(CreateDate,'yyyy-MM-dd') = @ShiftDate)  as DeletedOrder,
(select ISNULL(Sum(ISNULL(OrderNetAmount,0)),0) from OrderMaster where  IsDeleted = 1 and isPaymentCollected = 0 and ShiftIdCollection = @ShiftId and Format(CreateDate,'yyyy-MM-dd') = @ShiftDate) as DeletedOrderAmount,
0 as ItemLess,
0 as ItemLessAmount,
(select ISNULL(Sum(ISNULL(OrderNetAmount,0)),0) from OrderMaster where isPaymentCollected = 1 and IsDeleted = 1 and ShiftIdCollection = @ShiftId and Format(RecDate,'yyyy-MM-dd') = @ShiftDate) as OrderSaleReturn
from shiftorderdetail s
left join ShiftDemonination d on s.ShiftIdcollection =d.ShiftId and s.Id = d.shiftorderdetailid
left join login l on l.Id = d.CloseBy
where ShiftIdCollection = @ShiftId and ShiftDate = @ShiftDate
Order by s.CreatedDate desc, d.createddate desc 

END




GO

