-- Stored Procedure: [SP_SubmitCategory]
IF OBJECT_ID('[SP_SubmitCategory]', 'P') IS NOT NULL DROP PROCEDURE [SP_SubmitCategory];
GO
     
CREATE Procedure [dbo].[SP_SubmitCategory]      
@Id    int =0,      
@ResturantId int =0,      
@CategoryDesc varchar(500) = null,      
@ShortDesc  varchar(50) = null,      
@SortOrder  int = 0,    
@ImageUrl varchar(Max) = null,    
@CreatedBy  int = 0,    
@IsActive bit = false,    
@IsEdit   varchar(50) = null,    
@Msg		varchar(100) Out,
@LastId	   int  OutPut   

As      
Begin      
  if(@IsEdit = '')      
  Begin      
	 if Not Exists(Select CategoryDesc From Category Where CategoryDesc = @CategoryDesc)  
	 Begin  
			Insert Into Category (ResturantId,CategoryDesc,ShortDesc,SortOrder,ImageUrl,CreatedBy,CreateDate,IsActive,IsDeleted)      
			Values(@ResturantId,@CategoryDesc,@ShortDesc,@SortOrder,@ImageUrl,@CreatedBy,GETDATE(),@IsActive,0)      
			set @LastId =@@IDENTITY   
			set @Msg ='Category Created Successfully' 
	End  
	Else       
	Begin      
			set @Msg ='Category Already Exists'

	End     
 End      
	Else      
	Begin      
		Declare @Cat Varchar(500)      
		Select @Cat = CategoryDesc from Category Where CategoryDesc = @CategoryDesc  And Id !=@Id    
         
		if(@Cat IS NULL)      
		Begin      
			Update Category Set CategoryDesc = @CategoryDesc,ShortDesc = @ShortDesc, SortOrder= @SortOrder,ImageUrl=@ImageUrl Where Id = @Id      
			set @Msg ='Category Modified Successfully'  
			set @LastId =0
		End      
		Else       
		Begin      
			set @Msg ='Category Already Exists'
			set @LastId =0
		End      
      
  End      
End 

GO

-- Stored Procedure: [SP_TableAvailability]
IF OBJECT_ID('[SP_TableAvailability]', 'P') IS NOT NULL DROP PROCEDURE [SP_TableAvailability];
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_TableAvailability]
	@ClientCode as nvarchar(50)
AS
BEGIN
		SELECT tn.TableNo,r.RestaurantName,r.ClientCode as DefaultClientId
		FROM TablesNos tn
		LEFT JOIN orderMaster om ON tn.id = om.TableID
		AND CONVERT(DATE, om.OrderDate) = CONVERT(DATE, GETDATE())
		inner join Restaurant r on r.id = tn.RestaurantId

		WHERE om.TableID IS NULL and tn.isactive = 1 and r.ClientCode = @ClientCode

END

