-- Stored Procedure: [SP_UpdateDeleteItemRequest]
IF OBJECT_ID('[SP_UpdateDeleteItemRequest]', 'P') IS NOT NULL DROP PROCEDURE [SP_UpdateDeleteItemRequest];
GO
CREATE Procedure [dbo].[SP_UpdateDeleteItemRequest]  
@OrderId int,  
@ItemId int,  
@ItemQty int,
@ItemStatus varchar(20),
@UpdatedBy int,
@RejectReason varchar(50),
@OrderDetailSelfId bigint
  
AS  
Begin  

	 If(@ItemStatus = 'Approved')
		Begin
			Update ItemDeleteRequest set ItemStatus = @ItemStatus, IsApproved = 1, ApprovedDate = getdate(), UpdatedBy = @UpdatedBy
			Where OrderId = @OrderId and ItemId = @ItemId and ItemQty = @ItemQty and OrderDetailSelfId = @OrderDetailSelfId
			
			Declare @IsChange bit 
			Declare @qty int
			Declare @cnt int

			Select @qty = ISNULL(DeletedItemQty, ItemQty) From OrderDetail where OrderDetailSelfId = @OrderDetailSelfId and IsActive = 1 and IsDeleted = 0 and OrderMasterId = @OrderId

			If(@qty = @ItemQty)
			BEGIN
				Update OrderDetail Set IsDeleted = 1, IsPrinted = NULL , DeletedItemQty = (@qty - @ItemQty), DeletedAmount = ((@qty - @ItemQty) * Rate)
				Where OrderMasterId = @OrderId and ItemId = @ItemId and OrderDetailSelfId = @OrderDetailSelfId

				Select @cnt = Count(*) From OrderDetail where OrderMasterId = @OrderId and IsDeleted = 0
				IF(@cnt = 0)
				Begin
					Update Ordermaster Set IsDeleted = 1, IsFinalPaid = NULL Where Id = @OrderId
				End
			END
			ELSE
			BEGIN
				Update OrderDetail Set IsPrinted = NULL , DeletedItemQty = (@qty - @ItemQty), DeletedAmount = ((@qty - @ItemQty) * Rate)
				Where OrderMasterId = @OrderId and ItemId = @ItemId and OrderDetailSelfId = @OrderDetailSelfId
			END
					   

			-- TOTAL CALCULATION IN ORDER MASTER if item deleted (ASAD 11 NOV 2023)
			declare @itemrate as decimal(18,2);
			declare @TaxPer Decimal(18,2);

			-- FOR AMOUNTS ONLY
			set @itemrate = (select (Rate*@ItemQty) from OrderDetail where OrderMasterId = @OrderId and ItemId = @ItemId and OrderDetailSelfId= @OrderDetailSelfId)
			update ordermaster 
			set DeletedOrderAmount = ISNULL(DeletedOrderAmount, OrderAmount) - @itemrate, DeletedOrderNetAmount = ISNULL(DeletedOrderNetAmount, OrderNetAmount) - @itemrate  
			where Id = @OrderId

			-- TAX ONLY
			 set @TaxPer = (Select TaxPercentage From Taxes Where TaxName = 'GST' and IsActive = 1)
						IF(@TaxPer != 0)
						Begin
						SET @itemrate = @itemrate * (@TaxPer / 100);
						End
						else
						begin
						SET @itemrate = 0;
						end
				
			update ordermaster 
			set DeletedOrderNetAmount = ISNULL(DeletedOrderNetAmount, OrderNetAmount) - @itemrate, Deletedtaxamount = ISNULL(Deletedtaxamount, taxamount) - @itemrate  
			where Id = @OrderId

			
			Select @IsChange = ISChange from OrderMaster Where Id = @OrderId        
			if(@IsChange = 1)        
			begin        
				Set @IsChange = 0        
			End        
			else        
			begin        
				Set @IsChange = 1        
			End 

			Update OrderMaster Set IsChange = @IsChange 
			Where Id = @OrderId
			

		End
	Else
		Update ItemDeleteRequest set ItemStatus = @ItemStatus, IsRejected = 1, RejectedDate = getdate(), UpdatedBy = @UpdatedBy, RejectReason = @RejectReason
		Where OrderId = @OrderId and ItemId = @ItemId and ItemQty = @ItemQty and OrderDetailSelfId = @OrderDetailSelfId
		
   
End



GO

