-- Stored Procedure: [SP_UpdateDriverStatus]
IF OBJECT_ID('[SP_UpdateDriverStatus]', 'P') IS NOT NULL DROP PROCEDURE [SP_UpdateDriverStatus];
GO
CREATE Procedure [dbo].[SP_UpdateDriverStatus]      
@status  int,      
@OrderId varchar(50),      
@DriverId int      
As      
Begin      
Declare @Count int 
Declare @columnName varchar(500)
Set @columnName = Case When @status = 1 Then 'AcceptDatetime' 
				  When @status = 2 Then 'DispatchedDatetime'
				  When @status = 3 Then 'RejectedDatetime'
				  When @status = 4 Then 'ArrivedDatetime'
				  When @status = 5 Then 'PickupDatetime'
				  When @status = 6 Then 'DeliveredDatetime'
				  When @status = 7 Then 'CanceledDatetime'
				  End
DECLARE @sql VARCHAR(MAX)
Set @sql = 'Update OrderMaster Set '+@columnName+' = GETDATE() Where Id='+@OrderId+''
Exec (@sql)
Update OrderMaster Set DriverStatusId = @status,OrderStatusId = @status,DriverId=@DriverId Where Id =@OrderId  

Set @Count = (Select  Count(*) from OrderMaster Where DriverId = @DriverId And DriverStatusId != 6)  
 if (@status = 2 Or @status = 1)  
 Begin   
 Update DriverLogin Set DriverStatusId = @status Where DriverId = @DriverId  
 End  
 Else If (@Count = 0 And @status = 6)  
 Begin  
 Update DriverLogin Set DriverStatusId = @status Where DriverId = @DriverId  
 End  
End  

GO

