CREATE Procedure [dbo].[SP_UpdateProduct]  
@SubCategoryId  int,      
@ItemDesc   varchar(500),      
@ShortDesc   varchar(5000),      
@SortOrder   int,      
@ImageURL   nvarchar(Max),      
@CreatedBy   int,      
@IsActive   bit,      
