CREATE Procedure [dbo].[SP_UpdatePurchases]
@Id						int,
@SupplierInfoId			int,
@PaymentType			varchar(100),
@InvoiceNumber			varchar(500),
@PurchaseDate			datetime,
@CreatedBy				int,
@IsActive				bit,
@JsonPurchaseDetails	varchar(Max),
@Msg					varchar(100) Out
AS
BEGIN TRY            
    BEGIN TRANSACTION  
		DEclare @PurchasesId int 

			Update PurchasesMaster Set SupplierInfoId =@SupplierInfoId,PaymentType=@PaymentType,InvoiceNumber=@InvoiceNumber,PurchaseDate=@PurchaseDate,ModifyDate=GETDATE(),ModifyBy=@CreatedBy,IsActive=@IsActive
									Where Id = @Id
		set @PurchasesId   =  @Id

		Delete From purchasesDetails Where PurchasesId =@PurchasesId
		Declare @JsonPurchaseDetailsTable  Table(
			PurchasesId	int,
			UOMId	int,
			RawMaterialId bit,
			SizeDesc decimal(18,2),
			QtyDesc decimal(18,2),
			Rate decimal(18,2),
			Amount decimal(18,2),
			CreatedDate	datetime,
			CreatedBy int,
			IsDeleted bit,
			IsActive bit
			
			)
			
			Insert Into @JsonPurchaseDetailsTable
		Select * from OpenJson(@JsonPurchaseDetails)
			With (PurchasesId	int,
			UOMId	int,
			RawMaterialId bit,
			SizeDesc decimal(18,2),
			QtyDesc decimal(18,2),
			Rate decimal(18,2),
			Amount decimal(18,2),
			CreatedDate	datetime,
			CreatedBy int,
			IsDeleted bit,
			IsActive bit
			)

			Update @JsonPurchaseDetailsTable Set PurchasesId =@PurchasesId, CreatedDate =GETDATE(),CreatedBy = @CreatedBy ,IsDeleted = 0 ,IsActive = 1

			Insert into purchasesDetails
			Select * from @JsonPurchaseDetailsTable

			set @Msg ='Invoice Midified Successfully'
COMMIT TRANSACTION            
END TRY            
BEGIN CATCH            
          
 ROLLBACK TRANSACTION          
 Set @Msg = ERROR_MESSAGE()      
End CATCH 

GO

-- Stored Procedure: [SP_UpdateQRScan]
IF OBJECT_ID('[SP_UpdateQRScan]', 'P') IS NOT NULL DROP PROCEDURE [SP_UpdateQRScan];
GO
     
CREATE Procedure [dbo].[SP_UpdateQRScan]      
@FlightId   int =0,  
@SlipCode	varchar(50),  
@ScanBy		int =0, 
@msg		varchar(100) Out

As      
Begin      
    
	Declare @Cat Varchar(500)      
	Select @Cat = IsScan from FlightDetails Where (Id = @FlightId OR SlipCode LIKE CONCAT('%-', @SlipCode)) 
	AND CreatedDate >= DATEADD(HOUR, -3, FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss'))
         
	IF(@Cat IS NULL) 
		Begin      
			set @msg ='Invalid Slip Code'
		End
	Else If(@Cat = 0)
		Begin     
			Select fd.*,(SELECT TOP 1 c1.fname FROM Customer c1 WHERE c1.FlightId = fd.Id) AS PassengerName
			from flightdetails fd where fd.SlipCode LIKE CONCAT('%-', @SlipCode)

			Update FlightDetails Set IsScan = 1, ScanBy = @ScanBy, ScanDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss')
			Where (Id = @FlightId OR SlipCode LIKE CONCAT('%-', @SlipCode))      
			set @msg ='Success' 
		End      
	Else       
		Begin      
			set @msg ='Slip Code Already Used'
		End      
      
      
End 

GO

