-- Stored Procedure: [SP_WaiterLogin]
IF OBJECT_ID('[SP_WaiterLogin]', 'P') IS NOT NULL DROP PROCEDURE [SP_WaiterLogin];
GO

CREATE Procedure [dbo].[SP_WaiterLogin]   
@UserName varchar(100),  
@Password varchar(100),  
@FCMToken varchar(MAX),  
@ClientCode varchar(100),  
@Msg varchar(100) OUT  
AS  
Begin  
    -- Check for valid client code
    if Not Exists(Select * from Restaurant Where ClientCode = @ClientCode)  
    Begin  
        Set @Msg = 'Invalid Authorization Code'  
        Return  
    End  

    -- Check if waiter exists
    if Exists (Select * from Waiter Where Waiter_UserName = @UserName)  
    Begin  
        -- Check if the provided password matches
        if Exists (Select * from Waiter Where Waiter_UserName = @UserName AND Waiter_Password = @Password And (IsLogin IS NULL OR IsLogin = 0))  
        Begin  
            Select *, (Select RestaurantName from Restaurant) AS RestaurantName from Waiter Where Waiter_UserName = @UserName AND Waiter_Password = @Password  
        
            Update Waiter Set IsLogin = 1, LoginDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss') 
			Where Waiter_UserName = @UserName AND Waiter_Password = @Password  
            set @Msg = ''  
        End  
        else  
        Begin  
            -- Check if the waiter is already logged in or if the password is incorrect
            if Exists (Select * from Waiter Where Waiter_UserName = @UserName AND (IsLogin = 1))  
            Begin  
                Set @Msg = 'Waiter Already Logged In'  
            End  
            Else  
            Begin  
                Set @Msg = 'Invalid Username or Password'  
            End  
        End  
    End  
    else  
    Begin  
        Set @Msg = 'Invalid Username or Password'  
    End  
End

GO

