CREATE Procedure [dbo].[SP_WebLogin]    
@UserName  Varchar(100),    
@UserPassword Varchar(100)    
AS    
Begin    
  if Exists (Select Id from login L Where L.UserName = @UserName And L.UserPassword = @UserPassword )    
  Begin    
  Select     
  L.ResturantId,L.UserId,L.UserName,R.RestaurantShortName,R.RestaurantName, L.IsBackOffice
  from login L Inner Join UserDetail UD On L.UserId = UD.Id   
  Inner Join Restaurant R On R.ID = L.ResturantId  
  Where L.UserName = @UserName And L.UserPassword = @UserPassword    
  And UD.IsActive = 1 And (UD.IsDeleted = 0 OR UD.IsDeleted IS NULL)
  
  Update login Set IsLogin = 1, LoginDate = FORMAT(SWITCHOFFSET(SYSDATETIMEOFFSET(), '+05:00'), 'yyyy-MM-dd HH:mm:ss') Where UserName = @UserName And UserPassword = @UserPassword    
  End    
End  

